    LyricStanza(startTimeMs: 630000, devanagari: 'स्थान भूमि श्मशान दुर्जटि धरे अलखरो ध्यान\nदिगंबर महादेव भगवान अजनमां अकळ अनुपम', transliteration: ''),
    LyricStanza(startTimeMs: 660000, devanagari: 'स्थान भूमि श्मशान दुर्जटि धरे अलखरो ध्यान\nदिगंबर महादेव भगवान अजनमां अकळ अनुपम', transliteration: ''),
    LyricStanza(startTimeMs: 690000, devanagari: 'देव दैत्य ने नाग मानवी कोईना पामे ताड\nअजरवर तारा गुनालाय थाय समर्पे शंभु दम दम', transliteration: ''),
  ],
  '2qxZxnDurvU': [
    LyricStanza(startTimeMs: 0, devanagari: 'श्रीनीलकण्ठ नमश्शिवायाष्टकम्\nनमो नमः कारणकारणाय\nजगन्मयायाहितपाशकाय ।\nत्वत्पादपद्माश्रितरक्षकाय\nश्रीनीलकण्ठाय नमः शिवाय ॥ १॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'ध्यायन्ति ये त्वां यतयः स्तुवन्ति\nहृदम्बुजे दीपसमप्रकाशम् ।\nनासाग्रविन्यस्तविलोचनाय\nश्रीनीलकण्ठाय नमः शिवाय ॥ २॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'सर्गस्थितिध्वंसनकारणाय\nयमादियोगाष्टकसिद्धिदाय ।\nतपस्विनां शीघ्रफलप्रदाय ।\nश्रीनीलकण्ठाय नमः शिवाय ॥ ३॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'वेदादिरूपाय त्रिलोचनाय\nवेदान्तवेद्याय दिगम्बराय ।\nविभूतिशुभ्राय जटाधराय\nश्रीनीलकण्ठाय नमः शिवाय ॥ ४॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'उग्राय संसारभयापहाय\nज्ञानप्रदायशुसुखप्रदाय ।\nकालान्तकाय प्रलयानिलाय\nश्रीनीलकण्ठाय नमः शिवाय ॥ ५॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'विधातृरूपाय जगद्धिताय\nरमेशरूपाय सदाशिवाय ।\nअनन्तरूपाय चतुर्भुजाय\nश्रीनीलकण्ठाय नमः शिवाय ॥ ६॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'विश्वैकवन्द्याय कलाधराय\nसमस्तलोकैकसमाश्रयाय ।\nकुठारपाशाङ्कुशपालिने च\nश्रीनीलकण्ठाय नमः शिवाय ॥ ७॥', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'शर्वाय सर्वप्रियकारणाय\nपिनाकिने बाणधराय तुभ्यम् ।\nगौरीप्रियायाखिलपालकाय\nश्रीनीलकण्ठाय नमः शिवाय ॥ ८॥', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'इति स्तुत्वा महादेवं प्रणम्य च पुनः पुनः ।\nविदध्यू ऋषयस्तत्र सुराः पद्मभुवादयः ॥ ९॥\nइति श्रीनीलकण्ठ नमः शिवायाष्टकं सम्पूर्णम् ।', transliteration: ''),
  ],
  '3eJTp3P1ZMQ': [
    LyricStanza(startTimeMs: 0, devanagari: '॥ श्रीरुद्राष्टकम् ॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'नमामीशमीशान निर्वाणरूपं\nविभुं व्यापकं ब्रह्मवेदस्वरूपम् ।\nनिजं निर्गुणं निर्विकल्पं निरीहं\nचिदाकाशमाकाशवासं भजेऽहम् ॥ १॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'निराकारमोंकारमूलं तुरीयं\nगिरा ज्ञान गोतीतमीशं गिरीशम् ।\nकरालं महाकाल कालं कृपालं\nगुणागार संसारपारं नतोऽहम् ॥ २॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'तुषाराद्रि संकाश गौरं गभीरं\nमनोभूत कोटिप्रभा श्री शरीरम् ।\nस्फुरन्मौलि कल्लोलिनी चारु गङ्गा\nलसद्भालबालेन्दु कण्ठे भुजङ्गा ॥ ३॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'चलत्कुण्डलं भ्रू सुनेत्रं विशालं\nप्रसन्नाननं नीलकण्ठं दयालम् ।\nमृगाधीशचर्माम्बरं मुण्डमालं\nप्रियं शंकरं सर्वनाथं भजामि ॥ ४॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'प्रचण्डं प्रकृष्टं प्रगल्भं परेशं\nअखण्डं अजं भानुकोटिप्रकाशम् ।\nत्रयः शूल निर्मूलनं शूलपाणिं\nभजेऽहं भवानीपतिं भावगम्यम् ॥ ५॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'कलातीत कल्याण कल्पान्तकारी\nसदा सज्जनानन्ददाता पुरारी ।\nचिदानन्द संदोह मोहापहारी\nप्रसीद प्रसीद प्रभो मन्मथारी ॥ ६॥', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'न यावत् उमानाथ पादारविन्दं\nभजन्तीह लोके परे वा नराणाम् ।\nन तावत् सुखं शान्ति सन्तापनाशं\nप्रसीद प्रभो सर्वभूताधिवासम् ॥ ७॥', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'न जानामि योगं जपं नैव पूजां\nनतोऽहं सदा सर्वदा शम्भु तुभ्यम् ।\nजरा जन्म दुःखौघ तातप्यमानं\nप्रभो पाहि आपन्नमामीश शम्भो ॥ ८॥', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'रुद्राष्टकमिदं प्रोक्तं विप्रेण हरतोषये ।\nये पठन्ति नरा भक्त्या तेषां शम्भुः प्रसीदति ॥', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: '॥ इति श्रीगोस्वामितुलसीदासकृतं श्रीरुद्राष्टकं संपूर्णम् ॥', transliteration: ''),
  ],
  '5Z7sZ0riNrI': [
    LyricStanza(startTimeMs: 0, devanagari: 'भगवति तव तीरे नीरमात्राशनोऽहं\nविगतविषयतृष्णः कृष्णमाराधयामि ।\nसकलकलुषभङ्गे स्वर्गसोपानगङ्गे\nतरलतरतरङ्गे देवि गङ्गे प्रसीद ॥ १॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'भगवति भवलीलामौलिमाले तवाम्भः\nकणमणुपरिमाणं प्राणिनो ये स्पृशन्ति ।\nअमरनगरनारीचामरमरग्राहिणीनां\nविगतकलिकलङ्कातङ्कमङ्के लुठन्ति ॥ २॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'ब्रह्माण्डं खण्डयन्ती हरशिरसि जटावल्लिमुल्लासयन्ती\nस्वर्लोकात् आपतन्ती कनकगिरिगुहागण्डशैलात् स्खलन्ती ।\nक्षोणी पृष्ठे लुठन्ती दुरितचयचमूर्निर्भरं भर्त्सयन्ती\nपाथोधिं पूरयन्ती सुरनगरसरित् पावनी नः पुनातु ॥ ३॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'मज्जन्मातङ्गकुम्भच्युतमदमदिरामोदमत्तालिजालं\nस्नानैः सिद्धाङ्गनानां कुचयुगविगलत् कुङ्कुमासङ्गपिङ्गम् ।\nसायम्प्रातर्मुनीनां कुशकुसुमचयैः छन्नतीरस्थनीरं\nपायान्नो गाङ्गमम्भः करिकलभकराक्रान्तरंहस्तरङ्गम् ॥ ४॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'आदावादि पितामहस्य नियमव्यापारपात्रे जलं\nपश्चात् पन्नगशायिनो भगवतः पादोदकं पावनम् ।\nभूयः शम्भुजटाविभूषणमणिः जह्वोर्महर्षेरियं\nकन्या कल्मषनाशिनी भगवती भागीरथी दृश्यते ॥ ५॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'शैलेन्द्रात् अवतारिणी निजजले मज्जत् जनोत्तारिणी\nपारावारविहारिणी भवभयश्रेणी समुत्सारिणी ।\nशेषाहेरनुकारिणी हरशिरोवल्लीदलाकारिणी\nकाशीप्रान्तविहारिणी विजयते गङ्गा मनोहारिणी ॥ ६॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'कुतो वीचिर्वीचिस्तव यदि गता लोचनपथं\nत्वमापीता पीताम्बरपुरनिवासं वितरसि ।\nत्वदुत्सङ्गे गङ्गे पतति यदि कायस्तनुभृतां\nतदा मातः शातक्रतवपदलाभोऽप्यतिलघुः ॥ ७॥', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'गङ्गे त्रैलोक्यसारे सकलसुरवधूधौतविस्तीर्णतोये\nपूर्णब्रह्मस्वरूपे हरिचरणरजोहारिणि स्वर्गमार्गे ।\nप्रायश्चित्तं यदि स्यात् तव जलकणिका ब्रह्महत्यादिपापे\nकस्त्वां स्तोतुं समर्थः त्रिजगदघहरे देवि गङ्गे प्रसीद ॥ ८॥', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'मातर्जाह्नवी शम्भुसङ्गमिलिते मौलौ निधायाञ्जलिं\nत्वत्तीरे वपुषोऽवसानसमये नारायणाङ्घ्रिद्वयम् ।\nसानन्दं स्मरतो भविष्यति मम प्राणप्रयाणोत्सवे\nभूयात् भक्तिरविच्युता हरिहराद्वैतात्मिका शाश्वती ॥ ९॥', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'गङ्गाष्टकमिदं पुण्यं यः पठेत् प्रयतो नरः ।\nसर्वपापविनिर्भुक्तो विष्णुलोकं स गच्छति ॥ १०॥', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'इति श्रीमत्परमहंसपरिव्राजकाचार्य श्रीगोविन्दभगवत्पूज्यपादस्यशिष्या\nश्रीमच्छङ्करभगवतः कृतौ गङ्गाष्टकस्तोत्रं सम्पूर्णम् ।', transliteration: ''),
  ],
  '8vnaZ3wskBo': [
    LyricStanza(startTimeMs: 0, devanagari: 'श्रीबद्रीनाथाष्टकम्\nभू-वैकुण्ठकृतावासं देवदेवं जगत्पतिम् ।\nचतुर्वर्गप्रदातारं श्रीबद्रीशं नमाम्यहम् ॥ १॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'तापत्रयहरं साक्षाच्छान्तिपुष्टिबलप्रदम् ।\nपरमानन्ददातारं श्रीबद्रीशं नमाम्यहम् ॥ २॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'सद्यः पापक्षयकरं सद्यः कैवल्यदायकम् ।\nलोकत्रयविधातारं श्रीबद्रीशं नमाम्यहम् ॥ ३॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'भक्तवाञ्छाकल्पतरुं करुणारसविग्रहम् ।\nभवाब्धिपारकर्तारं श्रीबद्रीशं नमाम्यहम् ॥ ४॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'सर्वदेवनुतं शश्वत् सर्वतीर्थपदं विभुम् ।\nलीलयोपात्तवपुषं श्रीबद्रीशं नमाम्यहम् ॥ ५॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'अनादिनिधनं कालकालं भीमयमच्युतम् ।\nसर्वाश्चर्यमयं देवं श्रीबद्रीशं नमाम्यहम् ॥ ६॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'गन्धमादनकूटस्थं नरनारायणात्मकम् ।\nबदरीखण्डमध्यस्थं श्रीबद्रीशं नमाम्यहम् ॥ ७॥', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'शत्रूदासीनमित्राणां सर्वज्ञं समदर्शिनम् ।\nब्रह्मानन्दचिदाभासं श्रीबद्रीशं नमाम्यहम् ॥ ८॥', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'श्रीबद्रीशाष्टकमिदं यः पठेत्प्रयतः शुचिः ।\nसर्वपापविनिमुक्तः स शान्तिं लभते पराम् ॥ ९॥', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'इति श्रीबद्रीनाथाष्टकं सम्पूर्णम् ॥', transliteration: ''),
  ],
  '9-ErXqupZKs': [
    LyricStanza(startTimeMs: 0, devanagari: 'जय हो तारो माँ, जय हो तारो माँ\nजय हो तारो माँ, जय हो तारो माँ\nहे माँ हरसिद्ध हाथ जोडी करु तने वंदना\nतारा विना कोण समजे अंतरनी संवेदना', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'तुं दयाळी तुं कृपाळी आद्यशक्ति ईश्वरी\nमारण तारण एक तुज छे प्रणमु तने परमेश्वरी\nहे माँ हरसिद्ध हाथ जोडी करु तने वंदना\nतारा विना कोण समजे अंतरनी संवेदना', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'अहीं तहीं भटकी रह्या ना मार्ग कोई सुझतो\nकुकर्मोनो वागेलो माडी घाव नथी रूझतो\nभुलो हशे लाखो अमारी माफ तमे करजो\nमने पापना पंथे जता माँ पाछो तमे वाळजो', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'हे माँ हरसिद्ध हाथ जोडी करु तने वंदना\nतारा विना कोण समजे अंतरनी संवेदना', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'काम क्रोध लोभ कपटने हुं ईर्षानो भरेल छुं\nना माफी पामु एवा माडी कर्मोनो करेल छुं\nआ पापीने उगारो माडी दया तमे दाखवो\nतारा विना मारु कोण छे कोनो भरोसो राखवो', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'हे माँ हरसिद्ध हाथ जोडी करु तने वंदना\nतारा विना कोण समजे अंतरनी संवेदना', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'आ पुराए ब्रह्माडमां माडी तमारु तेज छे\nआ विश्वने डोलाववुं तारा माटे सहेज छे\nतारी मरजी विना तो माडी कांईना थइ शके\nतुं धारे मां जे करवा एने कोई ना रोकी शके', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'हे माँ हरसिद्ध हाथ जोडी करु तने वंदना\nतारा विना कोण समजे अंतरनी संवेदना', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'तारा गुण गावा सात सागरनी शाही ओछी पडे\nतारी करुणाना किस्सा माडी हरघडी नवा जडे\nअनेक रूपो तारा छे माँ तुं छे हर एक अंशमां\nतुं सचराचर रमनारी त्रणे लोक तारा वशमां', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'हे माँ हरसिद्ध हाथ जोडी करु तने वंदना\nतारा विना कोण समजे अंतरनी संवेदना', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'मतलबी आ जगत छे ने संबंध सहु खोखला\nतारा विना उगर्याना माडी नथी कोई दाखला\nअनेक जनने तार्या छे माँ मुजने तारो तमे\nआरो नथी हवे कोई तारा शरणे आव्या अमे', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'हे माँ हरसिद्ध हाथ जोडी करु तने वंदना\nतारा विना कोण समजे अंतरनी संवेदना', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'आधार एक तारो छे माँ एक तारो आशरो\nडुबती आ नैया तारजो पुण्यना प्रकाश पाथरो\nजेवो गणो तेवो ओ माता हुं तमारो बाळ छुं\nबळदेव कहे माँ तारा विना हुं तो निराधार छुं', transliteration: ''),
    LyricStanza(startTimeMs: 390000, devanagari: 'हे माँ हरसिद्ध हाथ जोडी करु तने वंदना\nतारा विना कोण समजे अंतरनी संवेदना\nतारा विना कोण समजे अंतरनी संवेदना', transliteration: ''),
  ],
  'AXvmt88JLWg': [
    LyricStanza(startTimeMs: 0, devanagari: 'नमो नमो दुर्गे सुख करनी ।\nनमो नमो दुर्गे दुःख हरनी ॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'निरंकार है ज्योति तुम्हारी ।\nतिहूँ लोक फैली उजियारी ॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'शशि ललाट मुख महाविशाला ।\nनेत्र लाल भृकुटि विकराला ॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'रूप मातु को अधिक सुहावे ।\nदरश करत जन अति सुख पावे ॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'तुम संसार शक्ति लै कीना ।\nपालन हेतु अन्न धन दीना ॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'अन्नपूर्णा हुई जग पाला ।\nतुम ही आदि सुन्दरी बाला ॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'प्रलयकाल सब नाशन हारी ।\nतुम गौरी शिवशंकर प्यारी ॥', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'शिव योगी तुम्हरे गुण गावें ।\nब्रह्मा विष्णु तुम्हें नित ध्यावें ॥', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'रूप सरस्वती को तुम धारा ।\nदे सुबुद्धि ऋषि मुनिन उबारा ॥', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'धरयो रूप नरसिंह को अम्बा ।\nपरगट भई फाड़कर खम्बा ॥10॥', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'रक्षा करि प्रह्लाद बचायो ।\nहिरण्याक्ष को स्वर्ग पठायो ॥', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'लक्ष्मी रूप धरो जग माहीं ।\nश्री नारायण अंग समाहीं ॥', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'क्षीरसिन्धु में करत विलासा ।\nदयासिन्धु दीजै मन आसा ॥', transliteration: ''),
    LyricStanza(startTimeMs: 390000, devanagari: 'हिंगलाज में तुम्हीं भवानी ।\nमहिमा अमित न जात बखानी ॥', transliteration: ''),
    LyricStanza(startTimeMs: 420000, devanagari: 'मातंगी अरु धूमावति माता ।\nभुवनेश्वरी बगला सुख दाता ॥', transliteration: ''),
    LyricStanza(startTimeMs: 450000, devanagari: 'श्री भैरव तारा जग तारिणी ।\nछिन्न भाल भव दुःख निवारिणी ॥', transliteration: ''),
    LyricStanza(startTimeMs: 480000, devanagari: 'केहरि वाहन सोह भवानी ।\nलांगुर वीर चलत अगवानी ॥', transliteration: ''),
    LyricStanza(startTimeMs: 510000, devanagari: 'कर में खप्पर खड्ग विराजै ।\nजाको देख काल डर भाजै ॥', transliteration: ''),
    LyricStanza(startTimeMs: 540000, devanagari: 'सोहै अस्त्र और त्रिशूला ।\nजाते उठत शत्रु हिय शूला ॥', transliteration: ''),
    LyricStanza(startTimeMs: 570000, devanagari: 'नगरकोट में तुम्हीं विराजत ।\nतिहुँलोक में डंका बाजत ॥20॥', transliteration: ''),
    LyricStanza(startTimeMs: 600000, devanagari: 'शुम्भ निशुम्भ दानव तुम मारे ।\nरक्तबीज शंखन संहारे ॥', transliteration: ''),
    LyricStanza(startTimeMs: 630000, devanagari: 'महिषासुर नृप अति अभिमानी ।\nजेहि अघ भार मही अकुलानी ॥', transliteration: ''),
    LyricStanza(startTimeMs: 660000, devanagari: 'रूप कराल कालिका धारा ।\nसेन सहित तुम तिहि संहारा ॥', transliteration: ''),
    LyricStanza(startTimeMs: 690000, devanagari: 'परी गाढ़ सन्तन पर जब जब ।\nभई सहाय मातु तुम तब तब ॥', transliteration: ''),
    LyricStanza(startTimeMs: 720000, devanagari: 'अमरपुरी अरु बासव लोका ।\nतब महिमा सब रहें अशोका ॥', transliteration: ''),
    LyricStanza(startTimeMs: 750000, devanagari: 'ज्वाला में है ज्योति तुम्हारी ।\nतुम्हें सदा पूजें नरनारी ॥', transliteration: ''),
    LyricStanza(startTimeMs: 780000, devanagari: 'प्रेम भक्ति से जो यश गावें ।\nदुःख दारिद्र निकट नहिं आवें ॥', transliteration: ''),
    LyricStanza(startTimeMs: 810000, devanagari: 'ध्यावे तुम्हें जो नर मन लाई ।\nजन्ममरण ताकौ छुटि जाई ॥', transliteration: ''),
    LyricStanza(startTimeMs: 840000, devanagari: 'जोगी सुर मुनि कहत पुकारी ।\nयोग न हो बिन शक्ति तुम्हारी ॥', transliteration: ''),
    LyricStanza(startTimeMs: 870000, devanagari: 'शंकर आचारज तप कीनो ।\nकाम अरु क्रोध जीति सब लीनो ॥30', transliteration: ''),
    LyricStanza(startTimeMs: 900000, devanagari: 'निशिदिन ध्यान धरो शंकर को ।\nकाहु काल नहिं सुमिरो तुमको ॥', transliteration: ''),
    LyricStanza(startTimeMs: 930000, devanagari: 'शक्ति रूप का मरम न पायो ।\nशक्ति गई तब मन पछितायो ॥', transliteration: ''),
    LyricStanza(startTimeMs: 960000, devanagari: 'शरणागत हुई कीर्ति बखानी ।\nजय जय जय जगदम्ब भवानी ॥', transliteration: ''),
    LyricStanza(startTimeMs: 990000, devanagari: 'भई प्रसन्न आदि जगदम्बा ।\nदई शक्ति नहिं कीन विलम्बा ॥', transliteration: ''),
    LyricStanza(startTimeMs: 1020000, devanagari: 'मोको मातु कष्ट अति घेरो ।\nतुम बिन कौन हरै दुःख मेरो ॥', transliteration: ''),
    LyricStanza(startTimeMs: 1050000, devanagari: 'आशा तृष्णा निपट सतावें ।\nमोह मदादिक सब बिनशावें ॥', transliteration: ''),
    LyricStanza(startTimeMs: 1080000, devanagari: 'शत्रु नाश कीजै महारानी ।\nसुमिरौं इकचित तुम्हें भवानी ॥', transliteration: ''),
    LyricStanza(startTimeMs: 1110000, devanagari: 'करो कृपा हे मातु दयाला ।\nऋद्धिसिद्धि दै करहु निहाला ॥', transliteration: ''),
    LyricStanza(startTimeMs: 1140000, devanagari: 'जब लगि जिऊँ दया फल पाऊँ ।\nतुम्हरो यश मैं सदा सुनाऊँ ॥', transliteration: ''),
    LyricStanza(startTimeMs: 1170000, devanagari: 'श्री दुर्गा चालीसा जो कोई गावै ।\nसब सुख भोग परमपद पावै ॥40', transliteration: ''),
    LyricStanza(startTimeMs: 1200000, devanagari: 'देवीदास शरण निज जानी ।\nकहु कृपा जगदम्ब भवानी ॥', transliteration: ''),
  ],
  'BhwOproElxU': [
    LyricStanza(startTimeMs: 0, devanagari: 'ॐ जय शिव ओंकारा, प्रभु जय शिव ओंकारा।\nब्रह्मा विष्णु सदाशिव, अर्द्धांगी धारा ॥ ॐ हर हर हर महादेव॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'एकानन चतुरानन पंचानन राजे। शिव पंचानन राजे।\nहंसासन गरुड़ासन वृषवाहन साजे ॥ ॐ हर हर हर महादेव.॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'दो भुज चार चतुर्भुज दस भुज अति सोहे। प्रभु दस भुज अति सोहे।\nतीनों रूप निरखते। त्रिभुवन मन मोहे ॥ ॐ हर हर हर महादेव॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'अक्षमाला बनमाला मुण्डमाला धारी। शिव मुण्डमाला धारी।\nचंदन मृगमद चंदा, सोहे त्रिपुरारी॥ ॐ हर हर हर महादेव॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'श्वेताम्बर पीताम्बर बाघम्बर अंगे। शिव बाघम्बर अंगे।\nब्रह्मादिक सनकादिक भूतादिक संगे ॥ ॐ हर हर हर महादेव॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'कर के मध्य कमंडलु चक्र त्रिशूल धर्ता। शिव कर में त्रिशूल धर्ता।\nजगकर्ता जगहर्ता जगपालनकर्ता॥ ॐ हर हर हर महादेव॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'ब्रह्मा विष्णु सदाशिव जानत अविवेका। स्वामी जानत अविवेका।\nप्रणवाक्षर के मध्ये ये तीनों एका ॥ ॐ हर हर हर महादेव॥', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'त्रिगुण शिवजी की आरती जो कोई नर गावे। प्रभु प्रेम सहित गावे।\nकहत शिवानन्द स्वामी मनवांछित फल पावे ॥ ॐ हर हर हर महादेव॥', transliteration: ''),
  ],
  'Boia7bAOCSo': [
    LyricStanza(startTimeMs: 0, devanagari: '॥ श्री एकलिंग-अरावली-स्तवः ॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'अरावली-शैल-सुमेखलायाः, मध्ये लसत्-कांचन-भूमि-भागे।\nउदयपुरस्योपरि रम्य-देशे, कैलास-धाम्ना सदृशं विभाति॥ १॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'श्याम-प्रभं चारु-चतुर्मुखं तं, पाषाण-देहे शिव-तत्त्व-लीनम्।\nबप्पा-नरेन्द्रैः अर्चित-पाद-पद्मं, एकलिंगं शिरसा नमामि॥ २॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'यत्र द्रुमाः चामर-वात-लीलां, कुर्वन्ति नित्यं पवनेन मन्दम्।\nमेवाड़-नाथोऽपि च यत्र भृत्यः, दीवान-रूपेण भजति ईशम्॥ ३॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'गम्भीर-नादैः प्रति-कन्दरासु, ओंकार-शब्दः प्रतिगुञ्जते यः।\nतं मेदपाटेश्वर-राजरूपं, वन्दे महेशं कुलदेव-तुल्यम्॥ ४॥', transliteration: ''),
  ],
  'BvuqFmLmFBU': [
    LyricStanza(startTimeMs: 0, devanagari: 'लख लख दिवला री है आरती,\nआ पाबूजी रे धाम,\nजगमग जोता है जागती,\nऐ राठौड़ो रे धाम,\nरमती जगती है आरती,\nआ कोलूमण्ड रे माय।।', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'ढोल नगाड़ा है बाजता पाबु,\nजाळर रो झनकार,\nआरतियों में है आवजो,\nपाबु केसर रे असवार,\nरमती जगती है आरती,\nआ कोलूमण्ड रे माय।।', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'हाथ में भालो है सोवणो,\nपाबु सोरठड़ी तलवार,\nकमर कठारो है बांधणों,\nपाबु भालो बिजलसार,\nरमती जगती है आरती,\nआ कोलूमण्ड रे माय।।', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'गूगल खेवा है धूप पाबु,\nगाय रो गीरत मंगाय,\nनारेलो री है जोत जगे पाबु,\nथोरे मन्दिर रे मोय,\nरमती जगती है आरती,\nआ कोलूमण्ड रे माय।।', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'चांदा ढेमा है लावजो संग,\nसन्तो सांवत ने साथ,\nकेलम पेमल है लावजो,\nसंग सोढ़ी राणी रे साथ,\nरमती जगती है आरती,\nआ कोलूमण्ड रे माय।।', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'तीन लोक में है आरती पाबु,\nगावे गणा नर नार,\nसांझ सवेरे है आरती होवे,\nथोरे मन्दिर रे माय,\nरमती जगती है आरती,\nआ कोलूमण्ड रे माय।।', transliteration: ''),
  ],
  'DXix2UR7tN0': [
    LyricStanza(startTimeMs: 0, devanagari: 'यो नारायण आत्मरूप इति यज्जानाम्यहं तत्त्वतः\nयस्मिन् सर्वमिदं प्रकल्पितमहो रज्ज्वां यथाहिर्वृथा ।\nमायायाविनिवर्तकं निजमहो ब्रह्मेति यः श्रूयते\nनित्यं तं बदरीश्वरं गुरुवरं सच्चित्सुखं नौम्यहम् ॥ १॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'ब्रह्मैक्यं निजपावनं सुरुचिरं मायाविहीनं परं\nज्ञात्वा सर्वमतीत्य मायिकमिदं जीवेश-विश्वादिकम् ।\nयस्मिन्नित्यमहं जले जलमिव प्राप्यैकतां संस्थितः\nनित्यं तं बदरीश्वरं गुरुवरं सच्चित्सुखं नौम्यहम् ॥ २॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'एकस्मिन् कथमीदृशं जगदिदं मायाऽपि वा भाव्यते\nनैकस्मिन्नितरस्य भाव इति यत्सत्यं श्रुतेः सम्मतम् ॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'द्वैतं हेतुरहो भयस्य गदितं ज्ञात्वैक्यमालम्ब्य च\nनित्यं तं बदरीश्वरं गुरुवरं सच्चित्सुखं नौम्यहम् ॥ ३॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'वन्ध्यापुत्रजनिर्यथैंव किलतद्धेतुस्तथैंव मृषा\nविश्वं, तस्यच कारणं तदपि चेन् मिथ्येन्द्रजालादिवत् ॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'यस्मिन्नैव जगन्नहेतुरपि या मायाऽस्य वा प्रस्फुरेत\nनित्यं तं बदरीश्वरं गुरुवरं सच्चित्सुखं नौम्यहम् ॥ ४॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'भ्रान्त्युत्थं यदि वा भवेद्भवतु तज्जीवेश-विश्वादिकं\nमायामात्रमिदं न मेऽस्ति नितरां भ्रान्तेरधिष्ठानतः ।\nयस्मिन् भूम्नि नरश्चयोविदिति वा नामापि न श्रूयते\nनित्यं तं बदरीश्वरं गुरुवरं सच्चित्सुखं नौम्यहम् ॥ ५॥', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'जीवन्मुक्तिप्रदं शुद्धं श्रीनारायण-पञ्चकम् ।\nपठनाच्छ्रवणादस्य जीवनमुक्तिमवाप्नुयात् ॥ ६॥', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: '॥ इति शिवम् ॥', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'इति श्रीमत् परमहंसपरिव्राजकाचार्य सद्गुरू भगवान\nश्रीधरस्वामीमहाराजविरचितं श्रीबद्रीनारायणस्तोत्रं सम्पूर्णम् ।', transliteration: ''),
  ],
  'Df9pA_R5SH8': [
    LyricStanza(startTimeMs: 0, devanagari: 'जय हो तारो माँ, जय हो तारो माँ\nजय हो तारो माँ, जय हो तारो माँ\nहे माँ मोमाई हाथ जोडी करु तने वंदना\nतारा विना कोण समजे अंतरनी संवेदना', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'तुं दयाळी तुं कृपाळी आद्यशक्ति ईश्वरी\nमारण तारण एक तुज छे प्रणमु तने परमेश्वरी\nहे माँ मोमाई हाथ जोडी करु तने वंदना\nतारा विना कोण समजे अंतरनी संवेदना', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'अहीं तहीं भटकी रह्या ना मार्ग कोई सुझतो\nकुकर्मोनो वागेलो माडी घाव नथी रूझतो\nभुलो हशे लाखो अमारी माफ तमे करजो\nमने पापना पंथे जता माँ पाछो तमे वाळजो', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'हे माँ मोमाई हाथ जोडी करु तने वंदना\nतारा विना कोण समजे अंतरनी संवेदना', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'काम क्रोध लोभ कपटने हुं ईर्षानो भरेल छुं\nना माफी पामु एवा माडी कर्मोनो करेल छुं\nआ पापीने उगारो माडी दया तमे दाखवो\nतारा विना मारु कोण छे कोनो भरोसो राखवो', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'हे माँ मोमाई हाथ जोडी करु तने वंदना\nतारा विना कोण समजे अंतरनी संवेदना', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'आ पुराए ब्रह्माडमां माडी तमारु तेज छे\nआ विश्वने डोलाववुं तारा माटे सहेज छे\nतारी मरजी विना तो माडी कांईना थइ शके\nतुं धारे मां जे करवा एने कोई ना रोकी शके', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'हे माँ मोमाई हाथ जोडी करु तने वंदना\nतारा विना कोण समजे अंतरनी संवेदना', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'तारा गुण गावा सात सागरनी शाही ओछी पडे\nतारी करुणाना किस्सा माडी हरघडी नवा जडे\nअनेक रूपो तारा छे माँ तुं छे हर एक अंशमां\nतुं सचराचर रमनारी त्रणे लोक तारा वशमां', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'हे माँ मोमाई हाथ जोडी करु तने वंदना\nतारा विना कोण समजे अंतरनी संवेदना', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'मतलबी आ जगत छे ने संबंध सहु खोखला\nतारा विना उगर्याना माडी नथी कोई दाखला\nअनेक जनने तार्या छे माँ मुजने तारो तमे\nआरो नथी हवे कोई तारा शरणे आव्या अमे', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'हे माँ मोमाई हाथ जोडी करु तने वंदना\nतारा विना कोण समजे अंतरनी संवेदना', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'आधार एक तारो छे माँ एक तारो आशरो\nडुबती आ नैया तारजो पुण्यना प्रकाश पाथरो\nजेवो गणो तेवो ओ माता हुं तमारो बाळ छुं\nबळदेव कहे माँ तारा विना हुं तो निराधार छुं', transliteration: ''),
    LyricStanza(startTimeMs: 390000, devanagari: 'हे माँ मोमाई हाथ जोडी करु तने वंदना\nतारा विना कोण समजे अंतरनी संवेदना\nतारा विना कोण समजे अंतरनी संवेदना', transliteration: ''),
