  'DhTsvZavDNM': [
    LyricStanza(startTimeMs: 0, devanagari: 'जय गिरिजा पति दीन दयाला ।\nसदा करत सन्तन प्रतिपाला ॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'भाल चन्द्रमा सोहत नीके ।\nकानन कुण्डल नागफनी के ॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'अंग गौर शिर गंग बहाये ।\nमुण्डमाल तन क्षार लगाए ॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'वस्त्र खाल बाघम्बर सोहे ।\nछवि को देखि नाग मन मोहे ॥ 4', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'मैना मातु की हवे दुलारी ।\nबाम अंग सोहत छवि न्यारी ॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'कर त्रिशूल सोहत छवि भारी ।\nकरत सदा शत्रुन क्षयकारी ॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'नन्दि गणेश सोहै तहँ कैसे ।\nसागर मध्य कमल हैं जैसे ॥', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'कार्तिक श्याम और गणराऊ ।\nया छवि को कहि जात न काऊ ॥ 8', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'देवन जबहीं जाय पुकारा ।\nतब ही दुख प्रभु आप निवारा ॥', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'किया उपद्रव तारक भारी ।\nदेवन सब मिलि तुमहिं जुहारी ॥', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'तुरत षडानन आप पठायउ ।\nलवनिमेष महँ मारि गिरायउ ॥', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'आप जलंधर असुर संहारा ।\nसुयश तुम्हार विदित संसारा ॥ 12', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'त्रिपुरासुर सन युद्ध मचाई ।\nसबहिं कृपा कर लीन बचाई ॥', transliteration: ''),
    LyricStanza(startTimeMs: 390000, devanagari: 'किया तपहिं भागीरथ भारी ।\nपुरब प्रतिज्ञा तासु पुरारी ॥', transliteration: ''),
    LyricStanza(startTimeMs: 420000, devanagari: 'दानिन महँ तुम सम कोउ नाहीं ।\nसेवक स्तुति करत सदाहीं ॥', transliteration: ''),
    LyricStanza(startTimeMs: 450000, devanagari: 'वेद नाम महिमा तव गाई।\nअकथ अनादि भेद नहिं पाई ॥ 16', transliteration: ''),
    LyricStanza(startTimeMs: 480000, devanagari: 'प्रकटी उदधि मंथन में ज्वाला ।\nजरत सुरासुर भए विहाला ॥', transliteration: ''),
    LyricStanza(startTimeMs: 510000, devanagari: 'कीन्ही दया तहं करी सहाई ।\nनीलकण्ठ तब नाम कहाई ॥', transliteration: ''),
    LyricStanza(startTimeMs: 540000, devanagari: 'पूजन रामचन्द्र जब कीन्हा ।\nजीत के लंक विभीषण दीन्हा ॥', transliteration: ''),
    LyricStanza(startTimeMs: 570000, devanagari: 'सहस कमल में हो रहे धारी ।\nकीन्ह परीक्षा तबहिं पुरारी ॥ 20', transliteration: ''),
    LyricStanza(startTimeMs: 600000, devanagari: 'एक कमल प्रभु राखेउ जोई ।\nकमल नयन पूजन चहं सोई ॥', transliteration: ''),
    LyricStanza(startTimeMs: 630000, devanagari: 'कठिन भक्ति देखी प्रभु शंकर ।\nभए प्रसन्न दिए इच्छित वर ॥', transliteration: ''),
    LyricStanza(startTimeMs: 660000, devanagari: 'जय जय जय अनन्त अविनाशी ।\nकरत कृपा सब के घटवासी ॥', transliteration: ''),
    LyricStanza(startTimeMs: 690000, devanagari: 'दुष्ट सकल नित मोहि सतावै ।\nभ्रमत रहौं मोहि चैन न आवै ॥ 24', transliteration: ''),
    LyricStanza(startTimeMs: 720000, devanagari: 'त्राहि त्राहि मैं नाथ पुकारो ।\nयेहि अवसर मोहि आन उबारो ॥', transliteration: ''),
    LyricStanza(startTimeMs: 750000, devanagari: 'लै त्रिशूल शत्रुन को मारो ।\nसंकट से मोहि आन उबारो ॥', transliteration: ''),
    LyricStanza(startTimeMs: 780000, devanagari: 'मात-पिता भ्राता सब होई ।\nसंकट में पूछत नहिं कोई ॥', transliteration: ''),
    LyricStanza(startTimeMs: 810000, devanagari: 'स्वामी एक है आस तुम्हारी ।\nआय हरहु मम संकट भारी ॥ 28', transliteration: ''),
    LyricStanza(startTimeMs: 840000, devanagari: 'धन निर्धन को देत सदा हीं ।\nजो कोई जांचे सो फल पाहीं ॥', transliteration: ''),
    LyricStanza(startTimeMs: 870000, devanagari: 'अस्तुति केहि विधि करैं तुम्हारी ।\nक्षमहु नाथ अब चूक हमारी ॥', transliteration: ''),
    LyricStanza(startTimeMs: 900000, devanagari: 'शंकर हो संकट के नाशन ।\nमंगल कारण विघ्न विनाशन ॥', transliteration: ''),
    LyricStanza(startTimeMs: 930000, devanagari: 'योगी यति मुनि ध्यान लगावैं ।\nशारद नारद शीश नवावैं ॥ 32', transliteration: ''),
    LyricStanza(startTimeMs: 960000, devanagari: 'नमो नमो जय नमः शिवाय ।\nसुर ब्रह्मादिक पार न पाय ॥', transliteration: ''),
    LyricStanza(startTimeMs: 990000, devanagari: 'जो यह पाठ करे मन लाई ।\nता पर होत है शम्भु सहाई ॥', transliteration: ''),
    LyricStanza(startTimeMs: 1020000, devanagari: 'ॠनियां जो कोई हो अधिकारी ।\nपाठ करे सो पावन हारी ॥', transliteration: ''),
    LyricStanza(startTimeMs: 1050000, devanagari: 'पुत्र हीन कर इच्छा जोई ।\nनिश्चय शिव प्रसाद तेहि होई ॥ 36', transliteration: ''),
    LyricStanza(startTimeMs: 1080000, devanagari: 'पण्डित त्रयोदशी को लावे ।\nध्यान पूर्वक होम करावे ॥', transliteration: ''),
    LyricStanza(startTimeMs: 1110000, devanagari: 'त्रयोदशी व्रत करै हमेशा ।\nताके तन नहीं रहै कलेशा ॥', transliteration: ''),
    LyricStanza(startTimeMs: 1140000, devanagari: 'धूप दीप नैवेद्य चढ़ावे ।\nशंकर सम्मुख पाठ सुनावे ॥', transliteration: ''),
    LyricStanza(startTimeMs: 1170000, devanagari: 'जन्म जन्म के पाप नसावे ।\nअन्त धाम शिवपुर में पावे ॥ 40', transliteration: ''),
    LyricStanza(startTimeMs: 1200000, devanagari: 'कहैं अयोध्यादास आस तुम्हारी ।\nजानि सकल दुःख हरहु हमारी ॥', transliteration: ''),
  ],
  'DkoU-QcgKMg': [
    LyricStanza(startTimeMs: 0, devanagari: 'नमो देव नारायण स्वामी। घट घट के प्रभु अन्तर्यामी॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'जगत उजागर सब गुण। सागर देवनारायण नटवर नागर ॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'जय जय जय भक्तन हितकारी इच्छा पूरण करो हमारी ॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'भोग मोक्ष के दाता देवा। निस दिन करूँ आपकी सेवा ॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'दे सत पंथ कुपंथ निवारो। किरपा कर भव पार उतारो ॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'अधम उधारण नाम तुम्हारा। भक्त मनोरथ पूरण हारा ॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'धर कर संत रूप यदुराया। साडू माता को याचन आया ॥', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'करत स्नान साडुमाता सुन आई। अपने घर खुद भिक्षा लाई॥', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'प्रेम विवश ज्यों की त्यों धाई। बिना वस्त्र पहने चली आई ॥', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'नग्न देख प्रभु संकुचे मन माई। पीठ फेरली जब यदुराई ॥', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'साडूमाता यो वचन उचारा। तुम हो जगत पिता करतारा ॥', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'मैं बालक तुम हो पितु माता। नग्न देख प्रभु क्यो शरमाता ॥', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'सुनत बचन देखा भगवन्ता। बाल बढ़ाय तन ढ़का तुरन्ता ॥', transliteration: ''),
    LyricStanza(startTimeMs: 390000, devanagari: 'ले भिक्षा यों कहत मुरारी। मांगहु वर इच्छा अनुसारी ॥', transliteration: ''),
    LyricStanza(startTimeMs: 420000, devanagari: 'जो तुम स्वामी देना चाहो। आप समान पुत्र बक्षाओ ॥', transliteration: ''),
    LyricStanza(startTimeMs: 450000, devanagari: 'मम समान और कौ भोरी। मैं सुत होहुँ मात हित तोरी ॥', transliteration: ''),
    LyricStanza(startTimeMs: 480000, devanagari: 'मैं छलने आया था तौही। उलटा छला मात ते मोही ॥', transliteration: ''),
    LyricStanza(startTimeMs: 510000, devanagari: 'नापा साडुमात को मारण धाया। उसी समय प्रकटे यदुराया ॥', transliteration: ''),
    LyricStanza(startTimeMs: 540000, devanagari: 'आम्बा निम्बा मरे सिरदारा। जिन्दा करया आप किरतारा ॥', transliteration: ''),
    LyricStanza(startTimeMs: 570000, devanagari: 'किशना खाती का कोढ़ हटाया। कर दीन्ही कंचन सी काया ॥', transliteration: ''),
    LyricStanza(startTimeMs: 600000, devanagari: 'प्रकटया जब प्रभु मालासेरी माही। राण नगर सारी थर्राई ॥', transliteration: ''),
    LyricStanza(startTimeMs: 630000, devanagari: 'मारण विप्र आपको आया। संग आपके भुजंग पाया ॥', transliteration: ''),
    LyricStanza(startTimeMs: 660000, devanagari: 'दुजा विप्र आया शैताना। बने आप उसी वक्त जवाना ॥', transliteration: ''),
    LyricStanza(startTimeMs: 690000, devanagari: 'तीजा विप्र आया कर रीसा। वृद्ध रूप धरिया जगदीशा ॥', transliteration: ''),
    LyricStanza(startTimeMs: 720000, devanagari: 'काल भैरव असुर बड़धारी। वश मे किया आप गिरधारी ॥', transliteration: ''),
    LyricStanza(startTimeMs: 750000, devanagari: 'मालवा देश माहि गोविन्दा। छोछु भाट को किना जिन्दा ॥', transliteration: ''),
    LyricStanza(startTimeMs: 780000, devanagari: 'धारा नगरी राजा की बाई। पीपलदे शुभ नाम कहाई ॥', transliteration: ''),
    LyricStanza(startTimeMs: 810000, devanagari: 'ताके कोढ़ नशाये आपा। अखिंया खोली हरे सन्तापा ॥', transliteration: ''),
    LyricStanza(startTimeMs: 840000, devanagari: 'भुणा जी को लेने ताई। छोछु भाट को जवान बनाया ॥', transliteration: ''),
    LyricStanza(startTimeMs: 870000, devanagari: 'भुणा जी को कीना वीरा। टुट पड़या जुड़ा जंजीरा ॥', transliteration: ''),
    LyricStanza(startTimeMs: 900000, devanagari: 'आप धणी देमाली आया। बीला जी का कोढ़ हटाया ॥', transliteration: ''),
    LyricStanza(startTimeMs: 930000, devanagari: 'वैधा नाथ की धुणी आया। बहु कोढ़िन का कोढ़ हटायाद ॥', transliteration: ''),
    LyricStanza(startTimeMs: 960000, devanagari: 'जैतु का सब संकट मेटा। इच्छा पुरी दीन्हा बेटा ॥', transliteration: ''),
    LyricStanza(startTimeMs: 990000, devanagari: 'लाला था इक जात बलाई। उसकी आप दो देह बनाई ॥', transliteration: ''),
    LyricStanza(startTimeMs: 1020000, devanagari: 'दीनो के रक्षक कहलाओ। म्हारे ताई क्यो शरमाओ ॥', transliteration: ''),
    LyricStanza(startTimeMs: 1050000, devanagari: 'आशा पूरण करो हमारी। अरजी सुणयो बेग मुरारी ॥', transliteration: ''),
    LyricStanza(startTimeMs: 1080000, devanagari: 'मनोकामना पूरण किज्यो। अष्ट सिद्धि नव निधि दीज्यो ॥', transliteration: ''),
    LyricStanza(startTimeMs: 1110000, devanagari: 'कई मोहि मारे ताना। लज्जा तुम राखो भगवाना ॥', transliteration: ''),
    LyricStanza(startTimeMs: 1140000, devanagari: 'हंसी जो मेरी करवासी। उध्द बिड़द आपकी जासी ॥', transliteration: ''),
    LyricStanza(startTimeMs: 1170000, devanagari: 'आप हमारे गुरू पितु माता। आप ही मित्र द्रव धाता ॥', transliteration: ''),
    LyricStanza(startTimeMs: 1200000, devanagari: 'आप कृपा बुद्धि बल पाऊँ। दाता तुम कह जाचन जाऊँ ॥', transliteration: ''),
    LyricStanza(startTimeMs: 1230000, devanagari: 'जय जय जय भुणा जी के भ्राता। कुमति निवारो सुमति दाता॥', transliteration: ''),
    LyricStanza(startTimeMs: 1260000, devanagari: 'दुष्टो को अब बेग खपाओ। धर्म ध्वजा जग में फहराओ ॥', transliteration: ''),
  ],
  'DtSBLpQStT4': [
    LyricStanza(startTimeMs: 0, devanagari: '॥ अथ श्रीललितासहस्रनामस्तोत्रम् ॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'ॐ श्रीमाता श्रीमहाराज्ञी श्रीमत्-सिंहासनेश्वरी ।\nचिदग्नि-कुण्ड-सम्भूता देवकार्य-समुद्यता ॥ १॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'उद्यद्भानु-सहस्राभा चतुर्बाहु-समन्विता ।\nरागस्वरूप-पाशाढ्या क्रोधाकाराङ्कुशोज्ज्वला ॥ २॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'मनोरूपेक्षु-कोदण्डा पञ्चतन्मात्र-सायका ।\nनिजारुण-प्रभापूर-मज्जद्ब्रह्माण्ड-मण्डला ॥ ३॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'चम्पकाशोक-पुन्नाग-सौगन्धिक-लसत्कचा ।\nकुरुविन्दमणि-श्रेणी-कनत्कोटीर-मण्डिता ॥ ४॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'अष्टमीचन्द्र-विभ्राज-दलिकस्थल-शोभिता ।\nमुखचन्द्र-कलङ्काभ-मृगनाभि-विशेषका ॥ ५॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'वदनस्मर-माङ्गल्य-गृहतोरण-चिल्लिका ।\nवक्त्रलक्ष्मी-परीवाह-चलन्मीनाभ-लोचना ॥ ६॥', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'नवचम्पक-पुष्पाभ-नासादण्ड-विराजिता ।\nताराकान्ति-तिरस्कारि-नासाभरण-भासुरा ॥ ७॥', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'कदम्बमञ्जरी-कॢप्त-कर्णपूर-मनोहरा ।\nताटङ्क-युगली-भूत-तपनोडुप-मण्डला ॥ ८॥', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'पद्मराग-शिलादर्श-परिभावि-कपोलभूः ।\nनवविद्रुम-बिम्बश्री-न्यक्कारि-रदनच्छदा ॥ ९॥', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'शुद्ध-विद्याङ्कुराकार-द्विजपङ्क्ति-द्वयोज्ज्वला ।\nकर्पूर-वीटिकामोद-समाकर्षि-दिगन्तरा ॥ १०॥', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'निज-सल्लाप-माधुर्य-विनिर्भर्त्सित-कच्छपी ।\nमन्दस्मित-प्रभापूर-मज्जत्कामेश-मानसा ॥ ११॥', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'अनाकलित-सादृश्य-चिबुकश्री-विराजिता ।\nकामेश-बद्ध-माङ्गल्य-सूत्र-शोभित-कन्धरा ॥ १२॥', transliteration: ''),
    LyricStanza(startTimeMs: 390000, devanagari: 'कनकाङ्गद-केयूर-कमनीय-भुजान्विता ।\nरत्नग्रैवेय-चिन्ताक-लोल-मुक्ता-फलान्विता ॥ १३॥', transliteration: ''),
    LyricStanza(startTimeMs: 420000, devanagari: 'कामेश्वर-प्रेमरत्न-मणि-प्रतिपण-स्तनी ।\nनाभ्यालवाल-रोमालि-लता-फल-कुचद्वयी ॥ १४॥', transliteration: ''),
    LyricStanza(startTimeMs: 450000, devanagari: 'लक्ष्यरोम-लताधारता-समुन्नेय-मध्यमा ।\nस्तनभार-दलन्मध्य-पट्टबन्ध-वलित्रया ॥ १५॥', transliteration: ''),
    LyricStanza(startTimeMs: 480000, devanagari: 'अरुणारुण-कौसुम्भ-वस्त्र-भास्वत्-कटीतटी ।\nरत्न-किङ्किणिका-रम्य-रशना-दाम-भूषिता ॥ १६॥', transliteration: ''),
    LyricStanza(startTimeMs: 510000, devanagari: 'कामेश-ज्ञात-सौभाग्य-मार्दवोरु-द्वयान्विता ।\nमाणिक्य-मुकुटाकार-जानुद्वय-विराजिता ॥ १७॥', transliteration: ''),
    LyricStanza(startTimeMs: 540000, devanagari: 'इन्द्रगोप-परिक्षिप्त-स्मरतूणाभ-जङ्घिका ।\nगूढगुल्फा कूर्मपृष्ठ-जयिष्णु-प्रपदान्विता ॥ १८॥', transliteration: ''),
    LyricStanza(startTimeMs: 570000, devanagari: 'नख-दीधिति-संछन्न-नमज्जन-तमोगुणा ।\nपदद्वय-प्रभाजाल-पराकृत-सरोरुहा ॥ १९॥', transliteration: ''),
    LyricStanza(startTimeMs: 600000, devanagari: 'सिञ्जान-मणिमञ्जीर-मण्डित-श्री-पदाम्बुजा ।\nमराली-मन्दगमना महालावण्य-शेवधिः ॥ २०॥', transliteration: ''),
    LyricStanza(startTimeMs: 630000, devanagari: 'सर्वारुणाऽनवद्याङ्गी सर्वाभरण-भूषिता ।\nशिव-कामेश्वराङ्कस्था शिवा स्वाधीन-वल्लभा ॥ २१॥', transliteration: ''),
    LyricStanza(startTimeMs: 660000, devanagari: 'सुमेरु-मध्य-श‍ृङ्गस्था श्रीमन्नगर-नायिका ।\nचिन्तामणि-गृहान्तस्था पञ्च-ब्रह्मासन-स्थिता ॥ २२॥', transliteration: ''),
    LyricStanza(startTimeMs: 690000, devanagari: 'महापद्माटवी-संस्था कदम्बवन-वासिनी ।\nसुधासागर-मध्यस्था कामाक्षी कामदायिनी ॥ २३॥', transliteration: ''),
    LyricStanza(startTimeMs: 720000, devanagari: 'देवर्षि-गण-संघात-स्तूयमानात्म-वैभवा ।\nभण्डासुर-वधोद्युक्त-शक्तिसेना-समन्विता ॥ २४॥', transliteration: ''),
    LyricStanza(startTimeMs: 750000, devanagari: 'सम्पत्करी-समारूढ-सिन्धुर-व्रज-सेविता ।\nअश्वारूढाधिष्ठिताश्व-कोटि-कोटिभिरावृता ॥ २५॥', transliteration: ''),
    LyricStanza(startTimeMs: 780000, devanagari: 'चक्रराज-रथारूढ-सर्वायुध-परिष्कृता ।\nगेयचक्र-रथारूढ-मन्त्रिणी-परिसेविता ॥ २६॥', transliteration: ''),
    LyricStanza(startTimeMs: 810000, devanagari: 'किरिचक्र-रथारूढ-दण्डनाथा-पुरस्कृता ।\nज्वाला-मालिनिकाक्षिप्त-वह्निप्राकार-मध्यगा ॥ २७॥', transliteration: ''),
    LyricStanza(startTimeMs: 840000, devanagari: 'भण्डसैन्य-वधोद्युक्त-शक्ति-विक्रम-हर्षिता ।\nनित्या-पराक्रमाटोप-निरीक्षण-समुत्सुका ॥ २८॥', transliteration: ''),
    LyricStanza(startTimeMs: 870000, devanagari: 'भण्डपुत्र-वधोद्युक्त-बाला-विक्रम-नन्दिता ।\nमन्त्रिण्यम्बा-विरचित-विषङ्ग-वध-तोषिता ॥ २९॥', transliteration: ''),
    LyricStanza(startTimeMs: 900000, devanagari: 'विशुक्र-प्राणहरण-वाराही-वीर्य-नन्दिता ।\nकामेश्वर-मुखालोक-कल्पित-श्रीगणेश्वरा ॥ ३०॥', transliteration: ''),
    LyricStanza(startTimeMs: 930000, devanagari: 'महागणेश-निर्भिन्न-विघ्नयन्त्र-प्रहर्षिता ।\nभण्डासुरेन्द्र-निर्मुक्त-शस्त्र-प्रत्यस्त्र-वर्षिणी ॥ ३१॥', transliteration: ''),
    LyricStanza(startTimeMs: 960000, devanagari: 'कराङ्गुलि-नखोत्पन्न-नारायण-दशाकृतिः ।\nमहा-पाशुपतास्त्राग्नि-निर्दग्धासुर-सैनिका ॥ ३२॥', transliteration: ''),
    LyricStanza(startTimeMs: 990000, devanagari: 'कामेश्वरास्त्र-निर्दग्ध-सभण्डासुर-शून्यका ।\nब्रह्मोपेन्द्र-महेन्द्रादि-देव-संस्तुत-वैभवा ॥ ३३॥', transliteration: ''),
    LyricStanza(startTimeMs: 1020000, devanagari: 'हर-नेत्राग्नि-संदग्ध-काम-सञ्जीवनौषधिः ।\nश्रीमद्वाग्भव-कूटैक-स्वरूप-मुख-पङ्कजा ॥ ३४॥', transliteration: ''),
    LyricStanza(startTimeMs: 1050000, devanagari: 'कण्ठाधः-कटि-पर्यन्त-मध्यकूट-स्वरूपिणी ।\nशक्ति-कूटैकतापन्न-कट्यधोभाग-धारिणी ॥ ३५॥', transliteration: ''),
    LyricStanza(startTimeMs: 1080000, devanagari: 'मूल-मन्त्रात्मिका मूलकूटत्रय-कलेवरा ।\nकुलामृतैक-रसिका कुलसंकेत-पालिनी ॥ ३६॥', transliteration: ''),
    LyricStanza(startTimeMs: 1110000, devanagari: 'कुलाङ्गना कुलान्तस्था कौलिनी कुलयोगिनी ।\nअकुला समयान्तस्था समयाचार-तत्परा ॥ ३७॥', transliteration: ''),
    LyricStanza(startTimeMs: 1140000, devanagari: 'मूलाधारैक-निलया ब्रह्मग्रन्थि-विभेदिनी ।\nमणि-पूरान्तरुदिता विष्णुग्रन्थि-विभेदिनी ॥ ३८॥', transliteration: ''),
    LyricStanza(startTimeMs: 1170000, devanagari: 'आज्ञा-चक्रान्तरालस्था रुद्रग्रन्थि-विभेदिनी ।\nसहस्राराम्बुजारूढा सुधा-साराभिवर्षिणी ॥ ३९॥', transliteration: ''),
    LyricStanza(startTimeMs: 1200000, devanagari: 'तडिल्लता-समरुचिः षट्चक्रोपरि-संस्थिता ।\nमहासक्तिः कुण्डलिनी बिसतन्तु-तनीयसी ॥ ४०॥', transliteration: ''),
    LyricStanza(startTimeMs: 1230000, devanagari: 'भवानी भावनागम्या भवारण्य-कुठारिका ।\nभद्रप्रिया भद्रमूर्तिर्भक्त-सौभाग्यदायिनी ॥ ४१॥', transliteration: ''),
    LyricStanza(startTimeMs: 1260000, devanagari: 'भक्तिप्रिया भक्तिगम्या भक्तिवश्या भयापहा ।\nशाम्भवी शारदाराध्या शर्वाणी शर्मदायिनी ॥ ४२॥', transliteration: ''),
    LyricStanza(startTimeMs: 1290000, devanagari: 'शाङ्करी श्रीकरी साध्वी शरच्चन्द्र-निभानना ।\nशातोदरी शान्तिमती निराधारा निरञ्जना ॥ ४३॥', transliteration: ''),
    LyricStanza(startTimeMs: 1320000, devanagari: 'निर्लेपा निर्मला नित्या निराकारा निराकुला ।\nनिर्गुणा निष्कला शान्ता निष्कामा निरुपप्लवा ॥ ४४॥', transliteration: ''),
    LyricStanza(startTimeMs: 1350000, devanagari: 'नित्यमुक्ता निर्विकारा निष्प्रपञ्चा निराश्रया ।\nनित्यशुद्धा नित्यबुद्धा निरवद्या निरन्तरा ॥ ४५॥', transliteration: ''),
    LyricStanza(startTimeMs: 1380000, devanagari: 'निष्कारणा निष्कलङ्का निरुपाधिर्निरीश्वरा ।\nनीरागा रागमथनी निर्मदा मदनाशिनी ॥ ४६॥', transliteration: ''),
    LyricStanza(startTimeMs: 1410000, devanagari: 'निश्चिन्ता निरहंकारा निर्मोहा मोहनाशिनी ।\nनिर्ममा ममताहन्त्री निष्पापा पापनाशिनी ॥ ४७॥', transliteration: ''),
    LyricStanza(startTimeMs: 1440000, devanagari: 'निष्क्रोधा क्रोधशमनी निर्लोभा लोभनाशिनी ।\nनिःसंशया संशयघ्नी निर्भवा भवनाशिनी ॥ ४८॥', transliteration: ''),
    LyricStanza(startTimeMs: 1470000, devanagari: 'निर्विकल्पा निराबाधा निर्भेदा भेदनाशिनी ।\nनिर्नाशा मृत्युमथनी निष्क्रिया निष्परिग्रहा ॥ ४९॥', transliteration: ''),
    LyricStanza(startTimeMs: 1500000, devanagari: 'निस्तुला नीलचिकुरा निरपाया निरत्यया ।\nदुर्लभा दुर्गमा दुर्गा दुःखहन्त्री सुखप्रदा ॥ ५०॥', transliteration: ''),
    LyricStanza(startTimeMs: 1530000, devanagari: 'दुष्टदूरा दुराचार-शमनी दोषवर्जिता ।\nसर्वज्ञा सान्द्रकरुणा समानाधिक-वर्जिता ॥ ५१॥', transliteration: ''),
    LyricStanza(startTimeMs: 1560000, devanagari: 'सर्वशक्तिमयी सर्व-मङ्गला सद्गतिप्रदा ।\nसर्वेश्वरी सर्वमयी सर्वमन्त्र-स्वरूपिणी ॥ ५२॥', transliteration: ''),
    LyricStanza(startTimeMs: 1590000, devanagari: 'सर्व-यन्त्रात्मिका सर्व-तन्त्ररूपा मनोन्मनी ।\nमाहेश्वरी महादेवी महालक्ष्मीर्मृडप्रिया ॥ ५३॥', transliteration: ''),
    LyricStanza(startTimeMs: 1620000, devanagari: 'महारूपा महापूज्या महापातक-नाशिनी ।\nमहामाया महासत्त्वा महाशक्तिर्महारतिः ॥ ५४॥', transliteration: ''),
    LyricStanza(startTimeMs: 1650000, devanagari: 'महाभोगा महैश्वर्या महावीर्या महाबला ।\nमहाबुद्धिर्महासिद्धिर्महायोगेश्वरेश्वरी ॥ ५५॥', transliteration: ''),
    LyricStanza(startTimeMs: 1680000, devanagari: 'महातन्त्रा महामन्त्रा महायन्त्रा महासना ।\nमहायाग-क्रमाराध्या महाभैरव-पूजिता ॥ ५६॥', transliteration: ''),
    LyricStanza(startTimeMs: 1710000, devanagari: 'महेश्वर-महाकल्प-महाताण्डव-साक्षिणी ।\nमहाकामेश-महिषी महात्रिपुर-सुन्दरी ॥ ५७॥', transliteration: ''),
    LyricStanza(startTimeMs: 1740000, devanagari: 'चतुःषष्ट्युपचाराढ्या चतुःषष्टिकलामयी ।\nमहाचतुः-षष्टिकोटि-योगिनी-गणसेविता ॥ ५८॥', transliteration: ''),
    LyricStanza(startTimeMs: 1770000, devanagari: 'मनुविद्या चन्द्रविद्या चन्द्रमण्डल-मध्यगा ।\nचारुरूपा चारुहासा चारुचन्द्र-कलाधरा ॥ ५९॥', transliteration: ''),
    LyricStanza(startTimeMs: 1800000, devanagari: 'चराचर-जगन्नाथा चक्रराज-निकेतना ।\nपार्वती पद्मनयना पद्मराग-समप्रभा ॥ ६०॥', transliteration: ''),
    LyricStanza(startTimeMs: 1830000, devanagari: 'पञ्च-प्रेतासनासीना पञ्चब्रह्म-स्वरूपिणी ।\nचिन्मयी परमानन्दा विज्ञान-घनरूपिणी ॥ ६१॥', transliteration: ''),
    LyricStanza(startTimeMs: 1860000, devanagari: 'ध्यान-ध्यातृ-ध्येयरूपा धर्माधर्म-विवर्जिता ।\nविश्वरूपा जागरिणी स्वपन्ती तैजसात्मिका ॥ ६२॥', transliteration: ''),
    LyricStanza(startTimeMs: 1890000, devanagari: 'सुप्ता प्राज्ञात्मिका तुर्या सर्वावस्था-विवर्जिता ।\nसृष्टिकर्त्री ब्रह्मरूपा गोप्त्री गोविन्दरूपिणी ॥ ६३॥', transliteration: ''),
    LyricStanza(startTimeMs: 1920000, devanagari: 'संहारिणी रुद्ररूपा तिरोधान-करीश्वरी ।\nसदाशिवाऽनुग्रहदा पञ्चकृत्य-परायणा ॥ ६४॥', transliteration: ''),
    LyricStanza(startTimeMs: 1950000, devanagari: 'भानुमण्डल-मध्यस्था भैरवी भगमालिनी ।\nपद्मासना भगवती पद्मनाभ-सहोदरी ॥ ६५॥', transliteration: ''),
    LyricStanza(startTimeMs: 1980000, devanagari: 'उन्मेष-निमिषोत्पन्न-विपन्न-भुवनावली ।\nसहस्र-शीर्षवदना सहस्राक्षी सहस्रपात् ॥ ६६॥', transliteration: ''),
    LyricStanza(startTimeMs: 2010000, devanagari: 'आब्रह्म-कीट-जननी वर्णाश्रम-विधायिनी ।\nनिजाज्ञारूप-निगमा पुण्यापुण्य-फलप्रदा ॥ ६७॥', transliteration: ''),
    LyricStanza(startTimeMs: 2040000, devanagari: 'श्रुति-सीमन्त-सिन्दूरी-कृत-पादाब्ज-धूलिका ।\nसकलागम-सन्दोह-शुक्ति-सम्पुट-मौक्तिका ॥ ६८॥', transliteration: ''),
    LyricStanza(startTimeMs: 2070000, devanagari: 'पुरुषार्थप्रदा पूर्णा भोगिनी भुवनेश्वरी ।\nअम्बिकाऽनादि-निधना हरिब्रह्मेन्द्र-सेविता ॥ ६९॥', transliteration: ''),
    LyricStanza(startTimeMs: 2100000, devanagari: 'नारायणी नादरूपा नामरूप-विवर्जिता ।\nह्रींकारी ह्रीमती हृद्या हेयोपादेय-वर्जिता ॥ ७०॥', transliteration: ''),
    LyricStanza(startTimeMs: 2130000, devanagari: 'राजराजार्चिता राज्ञी रम्या राजीवलोचना ।\nरञ्जनी रमणी रस्या रणत्किङ्किणि-मेखला ॥ ७१॥', transliteration: ''),
    LyricStanza(startTimeMs: 2160000, devanagari: 'रमा राकेन्दुवदना रतिरूपा रतिप्रिया ।\nरक्षाकरी राक्षसघ्नी रामा रमणलम्पटा ॥ ७२॥', transliteration: ''),
    LyricStanza(startTimeMs: 2190000, devanagari: 'काम्या कामकलारूपा कदम्ब-कुसुम-प्रिया ।\nकल्याणी जगतीकन्दा करुणा-रस-सागरा ॥ ७३॥', transliteration: ''),
    LyricStanza(startTimeMs: 2220000, devanagari: 'कलावती कलालापा कान्ता कादम्बरीप्रिया ।\nवरदा वामनयना वारुणी-मद-विह्वला ॥ ७४॥', transliteration: ''),
    LyricStanza(startTimeMs: 2250000, devanagari: 'विश्वाधिका वेदवेद्या विन्ध्याचल-निवासिनी ।\nविधात्री वेदजननी विष्णुमाया विलासिनी ॥ ७५॥', transliteration: ''),
    LyricStanza(startTimeMs: 2280000, devanagari: 'क्षेत्रस्वरूपा क्षेत्रेशी क्षेत्र-क्षेत्रज्ञ-पालिनी ।\nक्षयवृद्धि-विनिर्मुक्ता क्षेत्रपाल-समर्चिता ॥ ७६॥', transliteration: ''),
    LyricStanza(startTimeMs: 2310000, devanagari: 'विजया विमला वन्द्या वन्दारु-जन-वत्सला ।\nवाग्वादिनी वामकेशी वह्निमण्डल-वासिनी ॥ ७७॥', transliteration: ''),
    LyricStanza(startTimeMs: 2340000, devanagari: 'भक्तिमत्-कल्पलतिका पशुपाश-विमोचिनी ।\nसंहृताशेष-पाषण्डा सदाचार-प्रवर्तिका ॥ ७८॥', transliteration: ''),
    LyricStanza(startTimeMs: 2370000, devanagari: 'तापत्रयाग्नि-सन्तप्त-समाह्लादन-चन्द्रिका ।\nतरुणी तापसाराध्या तनुमध्या तमोऽपहा ॥ ७९॥', transliteration: ''),
    LyricStanza(startTimeMs: 2400000, devanagari: 'चितिस्तत्पद-लक्ष्यार्था चिदेकरस-रूपिणी ।\nस्वात्मानन्द-लवीभूत-ब्रह्माद्यानन्द-सन्ततिः ॥ ८०॥', transliteration: ''),
    LyricStanza(startTimeMs: 2430000, devanagari: 'परा प्रत्यक्चितीरूपा पश्यन्ती परदेवता ।\nमध्यमा वैखरीरूपा भक्त-मानस-हंसिका ॥ ८१॥', transliteration: ''),
    LyricStanza(startTimeMs: 2460000, devanagari: 'कामेश्वर-प्राणनाडी कृतज्ञा कामपूजिता ।\nश‍ृङ्गार-रस-सम्पूर्णा जया जालन्धर-स्थिता ॥ ८२॥', transliteration: ''),
    LyricStanza(startTimeMs: 2490000, devanagari: 'ओड्याणपीठ-निलया बिन्दु-मण्डलवासिनी ।\nरहोयाग-क्रमाराध्या रहस्तर्पण-तर्पिता ॥ ८३॥', transliteration: ''),
    LyricStanza(startTimeMs: 2520000, devanagari: 'सद्यःप्रसादिनी विश्व-साक्षिणी साक्षिवर्जिता ।\nषडङ्गदेवता-युक्ता षाड्गुण्य-परिपूरिता ॥ ८४॥', transliteration: ''),
    LyricStanza(startTimeMs: 2550000, devanagari: 'नित्यक्लिन्ना निरुपमा निर्वाण-सुख-दायिनी ।\nनित्या-षोडशिका-रूपा श्रीकण्ठार्ध-शरीरिणी ॥ ८५॥', transliteration: ''),
    LyricStanza(startTimeMs: 2580000, devanagari: 'प्रभावती प्रभारूपा प्रसिद्धा परमेश्वरी ।\nमूलप्रकृतिरव्यक्ता व्यक्ताव्यक्त-स्वरूपिणी ॥ ८६॥', transliteration: ''),
    LyricStanza(startTimeMs: 2610000, devanagari: 'व्यापिनी विविधाकारा विद्याविद्या-स्वरूपिणी ।\nमहाकामेश-नयन-कुमुदाह्लाद-कौमुदी ॥ ८७॥', transliteration: ''),
    LyricStanza(startTimeMs: 2640000, devanagari: 'भक्त-हार्द-तमोभेद-भानुमद्भानु-सन्ततिः ।\nशिवदूती शिवाराध्या शिवमूर्तिः शिवङ्करी ॥ ८८॥', transliteration: ''),
    LyricStanza(startTimeMs: 2670000, devanagari: 'शिवप्रिया शिवपरा शिष्टेष्टा शिष्टपूजिता ।\nअप्रमेया स्वप्रकाशा मनोवाचामगोचरा ॥ ८९॥', transliteration: ''),
    LyricStanza(startTimeMs: 2700000, devanagari: 'चिच्छक्तिश् चेतनारूपा जडशक्तिर्जडात्मिका ।\nगायत्री व्याहृतिः सन्ध्या द्विजवृन्द-निषेविता ॥ ९०॥', transliteration: ''),
    LyricStanza(startTimeMs: 2730000, devanagari: 'तत्त्वासना तत्त्वमयी पञ्च-कोशान्तर-स्थिता ।\nनिःसीम-महिमा नित्य-यौवना मदशालिनी ॥ ९१॥', transliteration: ''),
    LyricStanza(startTimeMs: 2760000, devanagari: 'मदघूर्णित-रक्ताक्षी मदपाटल-गण्डभूः ।\nचन्दन-द्रव-दिग्धाङ्गी चाम्पेय-कुसुम-प्रिया ॥ ९२॥', transliteration: ''),
    LyricStanza(startTimeMs: 2790000, devanagari: 'कुशला कोमलाकारा कुरुकुल्ला कुलेश्वरी ।\nकुलकुण्डालया कौल-मार्ग-तत्पर-सेविता ॥ ९३॥', transliteration: ''),
    LyricStanza(startTimeMs: 2820000, devanagari: 'कुमार-गणनाथाम्बा तुष्टिः पुष्टिर्मतिर्धृतिः ।\nशान्तिः स्वस्तिमती कान्तिर्नन्दिनी विघ्ननाशिनी ॥ ९४॥', transliteration: ''),
    LyricStanza(startTimeMs: 2850000, devanagari: 'तेजोवती त्रिनयना लोलाक्षी-कामरूपिणी ।\nमालिनी हंसिनी माता मलयाचल-वासिनी ॥ ९५॥', transliteration: ''),
    LyricStanza(startTimeMs: 2880000, devanagari: 'सुमुखी नलिनी सुभ्रूः शोभना सुरनायिका ।\nकालकण्ठी कान्तिमती क्षोभिणी सूक्ष्मरूपिणी ॥ ९६॥', transliteration: ''),
    LyricStanza(startTimeMs: 2910000, devanagari: 'वज्रेश्वरी वामदेवी वयोऽवस्था-विवर्जिता ।\nसिद्धेश्वरी सिद्धविद्या सिद्धमाता यशस्विनी ॥ ९७॥', transliteration: ''),
    LyricStanza(startTimeMs: 2940000, devanagari: 'विशुद्धिचक्र-निलयाऽऽरक्तवर्णा त्रिलोचना ।\nखट्वाङ्गादि-प्रहरणा वदनैक-समन्विता ॥ ९८॥', transliteration: ''),
    LyricStanza(startTimeMs: 2970000, devanagari: 'पायसान्नप्रिया त्वक्स्था पशुलोक-भयङ्करी ।\nअमृतादि-महाशक्ति-संवृता डाकिनीश्वरी ॥ ९९॥', transliteration: ''),
    LyricStanza(startTimeMs: 3000000, devanagari: 'अनाहताब्ज-निलया श्यामाभा वदनद्वया ।\nदंष्ट्रोज्ज्वलाऽक्ष-मालादि-धरा रुधिरसंस्थिता ॥ १००॥', transliteration: ''),
    LyricStanza(startTimeMs: 3030000, devanagari: 'कालरात्र्यादि-शक्त्यौघ-वृता स्निग्धौदनप्रिया ।\nमहावीरेन्द्र-वरदा राकिण्यम्बा-स्वरूपिणी ॥ १०१॥', transliteration: ''),
    LyricStanza(startTimeMs: 3060000, devanagari: 'मणिपूराब्ज-निलया वदनत्रय-संयुता ।\nवज्रादिकायुधोपेता डामर्यादिभिरावृता ॥ १०२॥', transliteration: ''),
    LyricStanza(startTimeMs: 3090000, devanagari: 'रक्तवर्णा मांसनिष्ठा गुडान्न-प्रीत-मानसा ।\nसमस्तभक्त-सुखदा लाकिन्यम्बा-स्वरूपिणी ॥ १०३॥', transliteration: ''),
    LyricStanza(startTimeMs: 3120000, devanagari: 'स्वाधिष्ठानाम्बुज-गता चतुर्वक्त्र-मनोहरा ।\nशूलाद्यायुध-सम्पन्ना पीतवर्णाऽतिगर्विता ॥ १०४॥', transliteration: ''),
    LyricStanza(startTimeMs: 3150000, devanagari: 'मेदोनिष्ठा मधुप्रीता बन्धिन्यादि-समन्विता ।\nदध्यन्नासक्त-हृदया काकिनी-रूप-धारिणी ॥ १०५॥', transliteration: ''),
    LyricStanza(startTimeMs: 3180000, devanagari: 'मूलाधाराम्बुजारूढा पञ्च-वक्त्राऽस्थि-संस्थिता ।\nअङ्कुशादि-प्रहरणा वरदादि-निषेविता ॥ १०६॥', transliteration: ''),
    LyricStanza(startTimeMs: 3210000, devanagari: 'मुद्गौदनासक्त-चित्ता साकिन्यम्बा-स्वरूपिणी ।\nआज्ञा-चक्राब्ज-निलया शुक्लवर्णा षडानना ॥ १०७॥', transliteration: ''),
    LyricStanza(startTimeMs: 3240000, devanagari: 'मज्जासंस्था हंसवती-मुख्य-शक्ति-समन्विता ।\nहरिद्रान्नैक-रसिका हाकिनी-रूप-धारिणी ॥ १०८॥', transliteration: ''),
    LyricStanza(startTimeMs: 3270000, devanagari: 'सहस्रदल-पद्मस्था सर्व-वर्णोप-शोभिता ।\nसर्वायुधधरा शुक्ल-संस्थिता सर्वतोमुखी ॥ १०९॥', transliteration: ''),
    LyricStanza(startTimeMs: 3300000, devanagari: 'सर्वौदन-प्रीतचित्ता याकिन्यम्बा-स्वरूपिणी ।\nस्वाहा स्वधाऽमतिर्मेधा श्रुतिः स्मृतिरनुत्तमा ॥ ११०॥', transliteration: ''),
    LyricStanza(startTimeMs: 3330000, devanagari: 'पुण्यकीर्तिः पुण्यलभ्या पुण्यश्रवण-कीर्तना ।\nपुलोमजार्चिता बन्ध-मोचनी बन्धुरालका ॥ १११॥', transliteration: ''),
    LyricStanza(startTimeMs: 3360000, devanagari: 'विमर्शरूपिणी विद्या वियदादि-जगत्प्रसूः ।\nसर्वव्याधि-प्रशमनी सर्वमृत्यु-निवारिणी ॥ ११२॥', transliteration: ''),
    LyricStanza(startTimeMs: 3390000, devanagari: 'अग्रगण्याऽचिन्त्यरूपा कलिकल्मष-नाशिनी ।\nकात्यायनी कालहन्त्री कमलाक्ष-निषेविता ॥ ११३॥', transliteration: ''),
    LyricStanza(startTimeMs: 3420000, devanagari: 'ताम्बूल-पूरित-मुखी दाडिमी-कुसुम-प्रभा ।\nमृगाक्षी मोहिनी मुख्या मृडानी मित्ररूपिणी ॥ ११४॥', transliteration: ''),
    LyricStanza(startTimeMs: 3450000, devanagari: 'नित्यतृप्ता भक्तनिधिर्नियन्त्री निखिलेश्वरी ।\nमैत्र्यादि-वासनालभ्या महाप्रलय-साक्षिणी ॥ ११५॥', transliteration: ''),
    LyricStanza(startTimeMs: 3480000, devanagari: 'परा शक्तिः परा निष्ठा प्रज्ञानघन-रूपिणी ।\nमाध्वीपानालसा मत्ता मातृका-वर्ण-रूपिणी ॥ ११६॥', transliteration: ''),
    LyricStanza(startTimeMs: 3510000, devanagari: 'महाकैलास-निलया मृणाल-मृदु-दोर्लता ।\nमहनीया दयामूर्तिर्महासाम्राज्य-शालिनी ॥ ११७॥', transliteration: ''),
    LyricStanza(startTimeMs: 3540000, devanagari: 'आत्मविद्या महाविद्या श्रीविद्या कामसेविता ।\nश्री-षोडशाक्षरी-विद्या त्रिकूटा कामकोटिका ॥ ११८॥', transliteration: ''),
    LyricStanza(startTimeMs: 3570000, devanagari: 'कटाक्ष-किङ्करी-भूत-कमला-कोटि-सेविता ।\nशिरःस्थिता चन्द्रनिभा भालस्थेन्द्र-धनुःप्रभा ॥ ११९॥', transliteration: ''),
    LyricStanza(startTimeMs: 3600000, devanagari: 'हृदयस्था रविप्रख्या त्रिकोणान्तर-दीपिका ।\nदाक्षायणी दैत्यहन्त्री दक्षयज्ञ-विनाशिनी ॥ १२०॥', transliteration: ''),
    LyricStanza(startTimeMs: 3630000, devanagari: 'दरान्दोलित-दीर्घाक्षी दर-हासोज्ज्वलन्-मुखी ।\nगुरुमूर्तिर्गुणनिधिर्गोमाता गुहजन्मभूः ॥ १२१॥', transliteration: ''),
    LyricStanza(startTimeMs: 3660000, devanagari: 'देवेशी दण्डनीतिस्था दहराकाश-रूपिणी ।\nप्रतिपन्मुख्य-राकान्त-तिथि-मण्डल-पूजिता ॥ १२२॥', transliteration: ''),
    LyricStanza(startTimeMs: 3690000, devanagari: 'कलात्मिका कलानाथा काव्यालाप-विनोदिनी ।\nसचामर-रमा-वाणी-सव्य-दक्षिण-सेविता ॥ १२३॥', transliteration: ''),
    LyricStanza(startTimeMs: 3720000, devanagari: 'आदिशक्तिरमेयाऽऽत्मा परमा पावनाकृतिः ।\nअनेककोटि-ब्रह्माण्ड-जननी दिव्यविग्रहा ॥ १२४॥', transliteration: ''),
    LyricStanza(startTimeMs: 3750000, devanagari: 'क्लींकारी केवला गुह्या कैवल्य-पददायिनी ।\nत्रिपुरा त्रिजगद्वन्द्या त्रिमूर्तिस्त्रिदशेश्वरी ॥ १२५॥', transliteration: ''),
    LyricStanza(startTimeMs: 3780000, devanagari: 'त्र्यक्षरी दिव्य-गन्धाढ्या सिन्दूर-तिलकाञ्चिता ।\nउमा शैलेन्द्रतनया गौरी गन्धर्व-सेविता ॥ १२६॥', transliteration: ''),
    LyricStanza(startTimeMs: 3810000, devanagari: 'विश्वगर्भा स्वर्णगर्भाऽवरदा वागधीश्वरी ।\nध्यानगम्याऽपरिच्छेद्या ज्ञानदा ज्ञानविग्रहा ॥ १२७॥', transliteration: ''),
    LyricStanza(startTimeMs: 3840000, devanagari: 'सर्ववेदान्त-संवेद्या सत्यानन्द-स्वरूपिणी ।\nलोपामुद्रार्चिता लीला-कॢप्त-ब्रह्माण्ड-मण्डला ॥ १२८॥', transliteration: ''),
    LyricStanza(startTimeMs: 3870000, devanagari: 'अदृश्या दृश्यरहिता विज्ञात्री वेद्यवर्जिता ।\nयोगिनी योगदा योग्या योगानन्दा युगन्धरा ॥ १२९॥', transliteration: ''),
    LyricStanza(startTimeMs: 3900000, devanagari: 'इच्छाशक्ति-ज्ञानशक्ति-क्रियाशक्ति-स्वरूपिणी ।\nसर्वाधारा सुप्रतिष्ठा सदसद्रूप-धारिणी ॥ १३०॥', transliteration: ''),
    LyricStanza(startTimeMs: 3930000, devanagari: 'अष्टमूर्तिरजाजैत्री लोकयात्रा-विधायिनी ।\nएकाकिनी भूमरूपा निर्द्वैता द्वैतवर्जिता ॥ १३१॥', transliteration: ''),
    LyricStanza(startTimeMs: 3960000, devanagari: 'अन्नदा वसुदा वृद्धा ब्रह्मात्मैक्य-स्वरूपिणी ।\nबृहती ब्राह्मणी ब्राह्मी ब्रह्मानन्दा बलिप्रिया ॥ १३२॥', transliteration: ''),
    LyricStanza(startTimeMs: 3990000, devanagari: 'भाषारूपा बृहत्सेना भावाभाव-विवर्जिता ।\nसुखाराध्या शुभकरी शोभना सुलभा गतिः ॥ १३३॥', transliteration: ''),
    LyricStanza(startTimeMs: 4020000, devanagari: 'राज-राजेश्वरी राज्य-दायिनी राज्य-वल्लभा ।\nराजत्कृपा राजपीठ-निवेशित-निजाश्रिता ॥ १३४॥', transliteration: ''),
    LyricStanza(startTimeMs: 4050000, devanagari: 'राज्यलक्ष्मीः कोशनाथा चतुरङ्ग-बलेश्वरी ।\nसाम्राज्य-दायिनी सत्यसन्धा सागरमेखला ॥ १३५॥', transliteration: ''),
    LyricStanza(startTimeMs: 4080000, devanagari: 'दीक्षिता दैत्यशमनी सर्वलोक-वशङ्करी ।\nसर्वार्थदात्री सावित्री सच्चिदानन्द-रूपिणी ॥ १३६॥', transliteration: ''),
    LyricStanza(startTimeMs: 4110000, devanagari: 'देश-कालापरिच्छिन्ना सर्वगा सर्वमोहिनी ।\nसरस्वती शास्त्रमयी गुहाम्बा गुह्यरूपिणी ॥ १३७॥', transliteration: ''),
    LyricStanza(startTimeMs: 4140000, devanagari: 'सर्वोपाधि-विनिर्मुक्ता सदाशिव-पतिव्रता ।\nसम्प्रदायेश्वरी साध्वी गुरुमण्डल-रूपिणी ॥ १३८॥', transliteration: ''),
    LyricStanza(startTimeMs: 4170000, devanagari: 'कुलोत्तीर्णा भगाराध्या माया मधुमती मही ।\nगणाम्बा गुह्यकाराध्या कोमलाङ्गी गुरुप्रिया ॥ १३९॥', transliteration: ''),
    LyricStanza(startTimeMs: 4200000, devanagari: 'स्वतन्त्रा सर्वतन्त्रेशी दक्षिणामूर्ति-रूपिणी ।\nसनकादि-समाराध्या शिवज्ञान-प्रदायिनी ॥ १४०॥', transliteration: ''),
    LyricStanza(startTimeMs: 4230000, devanagari: 'चित्कलाऽऽनन्द-कलिका प्रेमरूपा प्रियङ्करी ।\nनामपारायण-प्रीता नन्दिविद्या नटेश्वरी ॥ १४१॥', transliteration: ''),
    LyricStanza(startTimeMs: 4260000, devanagari: 'मिथ्या-जगदधिष्ठाना मुक्तिदा मुक्तिरूपिणी ।\nलास्यप्रिया लयकरी लज्जा रम्भादिवन्दिता ॥ १४२॥', transliteration: ''),
    LyricStanza(startTimeMs: 4290000, devanagari: 'भवदाव-सुधावृष्टिः पापारण्य-दवानला ।\nदौर्भाग्य-तूलवातूला जराध्वान्त-रविप्रभा ॥ १४३॥', transliteration: ''),
    LyricStanza(startTimeMs: 4320000, devanagari: 'भाग्याब्धि-चन्द्रिका भक्त-चित्तकेकि-घनाघना ।\nरोगपर्वत-दम्भोलिर्मृत्युदारु-कुठारिका ॥ १४४॥', transliteration: ''),
    LyricStanza(startTimeMs: 4350000, devanagari: 'महेश्वरी महाकाली महाग्रासा महाशना ।\nअपर्णा चण्डिका चण्डमुण्डासुर-निषूदिनी ॥ १४५॥', transliteration: ''),
    LyricStanza(startTimeMs: 4380000, devanagari: 'क्षराक्षरात्मिका सर्व-लोकेशी विश्वधारिणी ।\nत्रिवर्गदात्री सुभगा त्र्यम्बका त्रिगुणात्मिका ॥ १४६॥', transliteration: ''),
    LyricStanza(startTimeMs: 4410000, devanagari: 'स्वर्गापवर्गदा शुद्धा जपापुष्प-निभाकृतिः ।\nओजोवती द्युतिधरा यज्ञरूपा प्रियव्रता ॥ १४७॥', transliteration: ''),
    LyricStanza(startTimeMs: 4440000, devanagari: 'दुराराध्या दुराधर्षा पाटली-कुसुम-प्रिया ।\nमहती मेरुनिलया मन्दार-कुसुम-प्रिया ॥ १४८॥', transliteration: ''),
    LyricStanza(startTimeMs: 4470000, devanagari: 'वीराराध्या विराड्रूपा विरजा विश्वतोमुखी ।\nप्रत्यग्रूपा पराकाशा प्राणदा प्राणरूपिणी ॥ १४९॥', transliteration: ''),
    LyricStanza(startTimeMs: 4500000, devanagari: 'मार्ताण्ड-भैरवाराध्या मन्त्रिणीन्यस्त-राज्यधूः ।\nत्रिपुरेशी जयत्सेना निस्त्रैगुण्या परापरा ॥ १५०॥', transliteration: ''),
    LyricStanza(startTimeMs: 4530000, devanagari: 'सत्य-ज्ञानानन्द-रूपा सामरस्य-परायणा ।\nकपर्दिनी कलामाला कामधुक् कामरूपिणी ॥ १५१॥', transliteration: ''),
    LyricStanza(startTimeMs: 4560000, devanagari: 'कलानिधिः काव्यकला रसज्ञा रसशेवधिः ।\nपुष्टा पुरातना पूज्या पुष्करा पुष्करेक्षणा ॥ १५२॥', transliteration: ''),
    LyricStanza(startTimeMs: 4590000, devanagari: 'परंज्योतिः परंधाम परमाणुः परात्परा ।\nपाशहस्ता पाशहन्त्री परमन्त्र-विभेदिनी ॥ १५३॥', transliteration: ''),
    LyricStanza(startTimeMs: 4620000, devanagari: 'मूर्ताऽमूर्ताऽनित्यतृप्ता मुनिमानस-हंसिका ।\nसत्यव्रता सत्यरूपा सर्वान्तर्यामिनी सती ॥ १५४॥', transliteration: ''),
    LyricStanza(startTimeMs: 4650000, devanagari: 'ब्रह्माणी ब्रह्मजननी बहुरूपा बुधार्चिता ।\nप्रसवित्री प्रचण्डाऽऽज्ञा प्रतिष्ठा प्रकटाकृतिः ॥ १५५॥', transliteration: ''),
    LyricStanza(startTimeMs: 4680000, devanagari: 'प्राणेश्वरी प्राणदात्री पञ्चाशत्पीठ-रूपिणी ।\nविश‍ृङ्खला विविक्तस्था वीरमाता वियत्प्रसूः ॥ १५६॥', transliteration: ''),
    LyricStanza(startTimeMs: 4710000, devanagari: 'मुकुन्दा मुक्तिनिलया मूलविग्रह-रूपिणी ।\nभावज्ञा भवरोगघ्नी भवचक्र-प्रवर्तिनी ॥ १५७॥', transliteration: ''),
    LyricStanza(startTimeMs: 4740000, devanagari: 'छन्दःसारा शास्त्रसारा मन्त्रसारा तलोदरी ।\nउदारकीर्तिरुद्दामवैभवा वर्णरूपिणी ॥ १५८॥', transliteration: ''),
    LyricStanza(startTimeMs: 4770000, devanagari: 'जन्ममृत्यु-जरातप्त-जनविश्रान्ति-दायिनी ।\nसर्वोपनिष-दुद्-घुष्टा शान्त्यतीत-कलात्मिका ॥ १५९॥', transliteration: ''),
    LyricStanza(startTimeMs: 4800000, devanagari: 'गम्भीरा गगनान्तस्था गर्विता गानलोलुपा ।\nकल्पना-रहिता काष्ठाऽकान्ता कान्तार्ध-विग्रहा ॥ १६०॥', transliteration: ''),
    LyricStanza(startTimeMs: 4830000, devanagari: 'कार्यकारण-निर्मुक्ता कामकेलि-तरङ्गिता ।\nकनत्कनकता-टङ्का लीला-विग्रह-धारिणी ॥ १६१॥', transliteration: ''),
    LyricStanza(startTimeMs: 4860000, devanagari: 'अजा क्षयविनिर्मुक्ता मुग्धा क्षिप्र-प्रसादिनी ।\nअन्तर्मुख-समाराध्या बहिर्मुख-सुदुर्लभा ॥ १६२॥', transliteration: ''),
    LyricStanza(startTimeMs: 4890000, devanagari: 'त्रयी त्रिवर्गनिलया त्रिस्था त्रिपुरमालिनी ।\nनिरामया निरालम्बा स्वात्मारामा सुधासृतिः ॥ १६३॥', transliteration: ''),
    LyricStanza(startTimeMs: 4920000, devanagari: 'संसारपङ्क-निर्मग्न-समुद्धरण-पण्डिता ।\nयज्ञप्रिया यज्ञकर्त्री यजमान-स्वरूपिणी ॥ १६४॥', transliteration: ''),
    LyricStanza(startTimeMs: 4950000, devanagari: 'धर्माधारा धनाध्यक्षा धनधान्य-विवर्धिनी ।\nविप्रप्रिया विप्ररूपा विश्वभ्रमण-कारिणी ॥ १६५॥', transliteration: ''),
    LyricStanza(startTimeMs: 4980000, devanagari: 'विश्वग्रासा विद्रुमाभा वैष्णवी विष्णुरूपिणी ।\nअयोनिर्योनिनिलया कूटस्था कुलरूपिणी ॥ १६६॥', transliteration: ''),
    LyricStanza(startTimeMs: 5010000, devanagari: 'वीरगोष्ठीप्रिया वीरा नैष्कर्म्या नादरूपिणी ।\nविज्ञानकलना कल्या विदग्धा बैन्दवासना ॥ १६७॥', transliteration: ''),
    LyricStanza(startTimeMs: 5040000, devanagari: 'तत्त्वाधिका तत्त्वमयी तत्त्वमर्थ-स्वरूपिणी ।\nसामगानप्रिया सौम्या सदाशिव-कुटुम्बिनी ॥ १६८॥', transliteration: ''),
    LyricStanza(startTimeMs: 5070000, devanagari: 'सव्यापसव्य-मार्गस्था सर्वापद्विनिवारिणी ।\nस्वस्था स्वभावमधुरा धीरा धीरसमर्चिता ॥ १६९॥', transliteration: ''),
    LyricStanza(startTimeMs: 5100000, devanagari: 'चैतन्यार्घ्य-समाराध्या चैतन्य-कुसुमप्रिया ।\nसदोदिता सदातुष्टा तरुणादित्य-पाटला ॥ १७०॥', transliteration: ''),
    LyricStanza(startTimeMs: 5130000, devanagari: 'दक्षिणा-दक्षिणाराध्या दरस्मेर-मुखाम्बुजा ।\nकौलिनी-केवलाऽनर्घ्य-कैवल्य-पददायिनी ॥ १७१॥', transliteration: ''),
    LyricStanza(startTimeMs: 5160000, devanagari: 'स्तोत्रप्रिया स्तुतिमती श्रुति-संस्तुत-वैभवा ।\nमनस्विनी मानवती महेशी मङ्गलाकृतिः ॥ १७२॥', transliteration: ''),
    LyricStanza(startTimeMs: 5190000, devanagari: 'विश्वमाता जगद्धात्री विशालाक्षी विरागिणी ।\nप्रगल्भा परमोदारा परामोदा मनोमयी ॥ १७३॥', transliteration: ''),
    LyricStanza(startTimeMs: 5220000, devanagari: 'व्योमकेशी विमानस्था वज्रिणी वामकेश्वरी ।\nपञ्चयज्ञ-प्रिया पञ्च-प्रेत-मञ्चाधिशायिनी ॥ १७४॥', transliteration: ''),
    LyricStanza(startTimeMs: 5250000, devanagari: 'पञ्चमी पञ्चभूतेशी पञ्च-संख्योपचारिणी ।\nशाश्वती शाश्वतैश्वर्या शर्मदा शम्भुमोहिनी ॥ १७५॥', transliteration: ''),
    LyricStanza(startTimeMs: 5280000, devanagari: 'धराधरसुता धन्या धर्मिणी धर्मवर्धिनी ।\nलोकातीता गुणातीता सर्वातीता शमात्मिका ॥ १७६॥', transliteration: ''),
    LyricStanza(startTimeMs: 5310000, devanagari: 'बन्धूक-कुसुमप्रख्या बाला लीलाविनोदिनी ।\nसुमङ्गली सुखकरी सुवेषाढ्या सुवासिनी ॥ १७७॥', transliteration: ''),
    LyricStanza(startTimeMs: 5340000, devanagari: 'सुवासिन्यर्चन-प्रीताऽऽशोभना शुद्धमानसा ।\nबिन्दु-तर्पण-सन्तुष्टा पूर्वजा त्रिपुराम्बिका ॥ १७८॥', transliteration: ''),
    LyricStanza(startTimeMs: 5370000, devanagari: 'दशमुद्रा-समाराध्या त्रिपुराश्री-वशङ्करी ।\nज्ञानमुद्रा ज्ञानगम्या ज्ञानज्ञेय-स्वरूपिणी ॥ १७९॥', transliteration: ''),
    LyricStanza(startTimeMs: 5400000, devanagari: 'योनिमुद्रा त्रिखण्डेशी त्रिगुणाम्बा त्रिकोणगा ।\nअनघाऽद्भुत-चारित्रा वाञ्छितार्थ-प्रदायिनी ॥ १८०॥', transliteration: ''),
    LyricStanza(startTimeMs: 5430000, devanagari: 'अभ्यासातिशय-ज्ञाता षडध्वातीत-रूपिणी ।\nअव्याज-करुणा-मूर्तिरज्ञान-ध्वान्त-दीपिका ॥ १८१॥', transliteration: ''),
    LyricStanza(startTimeMs: 5460000, devanagari: 'आबाल-गोप-विदिता सर्वानुल्लङ्घ्य-शासना ।\nश्रीचक्रराज-निलया श्रीमत्-त्रिपुरसुन्दरी ॥ १८२॥', transliteration: ''),
    LyricStanza(startTimeMs: 5490000, devanagari: 'श्रीशिवा शिव-शक्त्यैक्य-रूपिणी ललिताम्बिका ।\nएवं श्रीललिता देव्या नाम्नां साहस्रकं जगुः ॥', transliteration: ''),
    LyricStanza(startTimeMs: 5520000, devanagari: '॥ इति श्रीब्रह्माण्डपुराणे उत्तरखण्डे श्रीहयग्रीवागस्त्यसंवादे\nश्रीललिता सहस्रनाम स्तोत्र कथनं सम्पूर्णम् ॥', transliteration: ''),
  ],
  'ELNedIogu-Q': [
    LyricStanza(startTimeMs: 0, devanagari: 'जय हो तारो माँ जय हो तारो माँ (2)\nहे माँ खोडल हाथ जोडी करुं तने वंदना\nतारा विना कोण समजे अंतरनी संवेदना', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'तु दयाळी तुं कृपाळी आद्यशक्ति ईश्वरी\nमारण तारण एक तुज छे प्रणमु तने परमेश्वरी\nहे माँ खोडल हाथ जोडी करुं तने वंदना\nतारा विना कोण समजे अंतरनी संवेदना', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'अहीं तहीं भटकी रह्या ना मार्ग कोई सूझतो\nकुकर्मोनो वागेलो माडी घाव नथी रूझतो\nभुलो हशे लाखो अमारी माफ तमे करजो\nमने पापना पंथे जता माँ पाछो तमे वाळजो', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'हे माँ खोडल हाथ जोडी करुं तने वंदना\nतारा विना कोण समजे अंतरनी संवेदना', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'काम क्रोध लोभ कपटने हुं ईर्षानो भरेल छुं\nना माफी पामु एवा माडी कर्मोनो करेल छुं\nआ पापीने उगारो माडी दया तमे दाखवो\nतारा विना मारु कोण छे कोनो भरोसो राखवो', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'हे माँ खोडल हाथ जोडी करुं तने वंदना\nतारा विना कोण समजे अंतरनी संवेदना', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'आ पुराए ब्रह्मांडमां माडी तमारुं तेज छे\nआ विश्वने डोलाववु तारा माटे सहेज छे\nतारी मरजी विना तो माडी कांईना थई शके\nतु धारे माँ जे करवा एने कोई ना रोकी शके', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'हे माँ खोडल हाथ जोडी करुं तने वंदना\nतारा विना कोण समजे अंतरनी संवेदना', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'तारा गुण गावा सात सागरनी शाही ओछी पडे\nतारी करुणाना किस्सा माडी हरघडी नवा जडे\nअनेक रूपो तारा छे माँ तुं छे हर एक अंशमा\nतु सचराचर रमनारी त्रणे लोक तारा वशमां', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'हे माँ खोडल हाथ जोडी करुं तने वंदना\nतारा विना कोण समजे अंतरनी संवेदना', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'मतलबी आ जगत छे ने संबंध सहु खोखला\nतारा विना उगर्या ना माडी नथी कोई दाखला\nअनेक जनने तार्या छे माँ मुज ने तारो तमे\nहे माँ खोडल हाथ जोडी करुं तने वंदना', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'तारा विना कोण समजे अंतरनी संवेदना\nआधार एक तारो छे माँ एक तारो आशरो\nडूबती आ नैया तारजो पुण्यना प्रकाश पाथरो\nजेवो गणो तेवो ओ माता हुं तमारो बाळ छुं', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'बळदेव कहे माँ तारा विना हुं तो निराधार छुं\nहे माँ खोडल हाथ जोडी करुं तने वंदना\nतारा विना कोण समजे अंतरनी संवेदना (2)', transliteration: ''),
  ],
  'EMO1AT1UQf0': [
    LyricStanza(startTimeMs: 0, devanagari: 'आरती कुंजबिहारी की,\nश्री गिरिधर कृष्ण मुरारी की ॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'आरती कुंजबिहारी की,\nश्री गिरिधर कृष्ण मुरारी की ॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'गले में बैजंती माला,\nबजावै मुरली मधुर बाला ।\nश्रवण में कुण्डल झलकाला,\nनंद के आनंद नंदलाला ।\nगगन सम अंग कांति काली,\nराधिका चमक रही आली ।\nलतन में ठाढ़े बनमाली\nभ्रमर सी अलक,', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'कस्तूरी तिलक,\nचंद्र सी झलक,\nललित छवि श्यामा प्यारी की,\nश्री गिरिधर कृष्ण मुरारी की ॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'आरती कुंजबिहारी की,\nश्री गिरिधर कृष्ण मुरारी की ॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'कनकमय मोर मुकुट बिलसै,\nदेवता दरसन को तरसैं ।\nगगन सों सुमन रासि बरसै ।\nबजे मुरचंग,\nमधुर मिरदंग,\nग्वालिन संग,\nअतुल रति गोप कुमारी की,\nश्री गिरिधर कृष्णमुरारी की ॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'आरती कुंजबिहारी की,\nश्री गिरिधर कृष्ण मुरारी की ॥', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'जहां ते प्रकट भई गंगा,\nसकल मन हारिणि श्री गंगा ।\nस्मरन ते होत मोह भंगा\nबसी शिव सीस,\nजटा के बीच,\nहरै अघ कीच,\nचरन छवि श्रीबनवारी की,\nश्री गिरिधर कृष्णमुरारी की ॥', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'आरती कुंजबिहारी की,\nश्री गिरिधर कृष्ण मुरारी की ॥', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'चमकती उज्ज्वल तट रेनू,\nबज रही वृंदावन बेनू ।\nचहुं दिसि गोपि ग्वाल धेनू\nहंसत मृदु मंद,\nचांदनी चंद,\nकटत भव फंद,\nटेर सुन दीन दुखारी की,\nश्री गिरिधर कृष्णमुरारी की ॥', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'आरती कुंजबिहारी की,\nश्री गिरिधर कृष्ण मुरारी की ॥', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'आरती कुंजबिहारी की,\nश्री गिरिधर कृष्ण मुरारी की ॥', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'आरती कुंजबिहारी की,\nश्री गिरिधर कृष्ण मुरारी की ॥', transliteration: ''),
