  'EOOm_mBLKLY': [
    LyricStanza(startTimeMs: 0, devanagari: 'जय गिरिजा पति दीन दयाला ।\nसदा करत सन्तन प्रतिपाला ॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'भाल चन्द्रमा सोहत नीके ।\nकानन कुण्डल नागफनी के ॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'अंग गौर शिर गंग बहाये ।\nमुण्डमाल तन क्षार लगाए ॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'वस्त्र खाल बाघम्बर सोहे ।\nछवि को देखि नाग मन मोहे ॥ 4', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'मैना मातु की हवे दुलारी ।\nबाम अंग सोहत छवि न्यारी ॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'कर त्रिशूल सोहत छवि भारी ।\nकरत सदा शत्रुन क्षयकारी ॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'नन्दि गणेश सोहै तहँ कैसे ।\nसागर मध्य कमल हैं जैसे ॥', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'कार्तिक श्याम और गणराऊ ।\nया छवि को कहि जात न काऊ ॥ 8', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'देवन जबहीं जाय पुकारा ।\nतब ही दुख प्रभु आप निवारा ॥', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'किया उपद्रव तारक भारी ।\nदेवन सब मिलि तुमहिं जुहारी ॥', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'तुरत षडानन आप पठायउ ।\nलवनिमेष महँ मारि गिरायउ ॥', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'आप जलंधर असुर संहारा ।\nसुयश तुम्हार विदित संसारा ॥ 12', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'त्रिपुरासुर सन युद्ध मचाई ।\nसबहिं कृपा कर लीन बचाई ॥', transliteration: ''),
    LyricStanza(startTimeMs: 390000, devanagari: 'किया तपहिं भागीरथ भारी ।\nपुरब प्रतिज्ञा तासु पुरारी ॥', transliteration: ''),
    LyricStanza(startTimeMs: 420000, devanagari: 'दानिन महँ तुम सम कोउ नाहीं ।\nसेवक स्तुति करत सदाहीं ॥', transliteration: ''),
    LyricStanza(startTimeMs: 450000, devanagari: 'वेद नाम महिमा तव गाई।\nअकथ अनादि भेद नहिं पाई ॥ 16', transliteration: ''),
    LyricStanza(startTimeMs: 480000, devanagari: 'प्रकटी उदधि मंथन में ज्वाला ।\nजरत सुरासुर भए विहाला ॥', transliteration: ''),
    LyricStanza(startTimeMs: 510000, devanagari: 'कीन्ही दया तहं करी सहाई ।\nनीलकण्ठ तब नाम कहाई ॥', transliteration: ''),
    LyricStanza(startTimeMs: 540000, devanagari: 'पूजन रामचन्द्र जब कीन्हा ।\nजीत के लंक विभीषण दीन्हा ॥', transliteration: ''),
    LyricStanza(startTimeMs: 570000, devanagari: 'सहस कमल में हो रहे धारी ।\nकीन्ह परीक्षा तबहिं पुरारी ॥ 20', transliteration: ''),
    LyricStanza(startTimeMs: 600000, devanagari: 'एक कमल प्रभु राखेउ जोई ।\nकमल नयन पूजन चहं सोई ॥', transliteration: ''),
    LyricStanza(startTimeMs: 630000, devanagari: 'कठिन भक्ति देखी प्रभु शंकर ।\nभए प्रसन्न दिए इच्छित वर ॥', transliteration: ''),
    LyricStanza(startTimeMs: 660000, devanagari: 'जय जय जय अनन्त अविनाशी ।\nकरत कृपा सब के घटवासी ॥', transliteration: ''),
    LyricStanza(startTimeMs: 690000, devanagari: 'दुष्ट सकल नित मोहि सतावै ।\nभ्रमत रहौं मोहि चैन न आवै ॥ 24', transliteration: ''),
    LyricStanza(startTimeMs: 720000, devanagari: 'त्राहि त्राहि मैं नाथ पुकारो ।\nयेहि अवसर मोहि आन उबारो ॥', transliteration: ''),
    LyricStanza(startTimeMs: 750000, devanagari: 'लै त्रिशूल शत्रुन को मारो ।\nसंकट से मोहि आन उबारो ॥', transliteration: ''),
    LyricStanza(startTimeMs: 780000, devanagari: 'मात-पिता भ्राता सब होई ।\nसंकट में पूछत नहिं कोई ॥', transliteration: ''),
    LyricStanza(startTimeMs: 810000, devanagari: 'स्वामी एक है आस तुम्हारी ।\nआय हरहु मम संकट भारी ॥ 28', transliteration: ''),
    LyricStanza(startTimeMs: 840000, devanagari: 'धन निर्धन को देत सदा हीं ।\nजो कोई जांचे सो फल पाहीं ॥', transliteration: ''),
    LyricStanza(startTimeMs: 870000, devanagari: 'अस्तुति केहि विधि करैं तुम्हारी ।\nक्षमहु नाथ अब चूक हमारी ॥', transliteration: ''),
    LyricStanza(startTimeMs: 900000, devanagari: 'शंकर हो संकट के नाशन ।\nमंगल कारण विघ्न विनाशन ॥', transliteration: ''),
    LyricStanza(startTimeMs: 930000, devanagari: 'योगी यति मुनि ध्यान लगावैं ।\nशारद नारद शीश नवावैं ॥ 32', transliteration: ''),
    LyricStanza(startTimeMs: 960000, devanagari: 'नमो नमो जय नमः शिवाय ।\nसुर ब्रह्मादिक पार न पाय ॥', transliteration: ''),
    LyricStanza(startTimeMs: 990000, devanagari: 'जो यह पाठ करे मन लाई ।\nता पर होत है शम्भु सहाई ॥', transliteration: ''),
    LyricStanza(startTimeMs: 1020000, devanagari: 'ॠनियां जो कोई हो अधिकारी ।\nपाठ करे सो पावन हारी ॥', transliteration: ''),
    LyricStanza(startTimeMs: 1050000, devanagari: 'पुत्र हीन कर इच्छा जोई ।\nनिश्चय शिव प्रसाद तेहि होई ॥ 36', transliteration: ''),
    LyricStanza(startTimeMs: 1080000, devanagari: 'पण्डित त्रयोदशी को लावे ।\nध्यान पूर्वक होम करावे ॥', transliteration: ''),
    LyricStanza(startTimeMs: 1110000, devanagari: 'त्रयोदशी व्रत करै हमेशा ।\nताके तन नहीं रहै कलेशा ॥', transliteration: ''),
    LyricStanza(startTimeMs: 1140000, devanagari: 'धूप दीप नैवेद्य चढ़ावे ।\nशंकर सम्मुख पाठ सुनावे ॥', transliteration: ''),
    LyricStanza(startTimeMs: 1170000, devanagari: 'जन्म जन्म के पाप नसावे ।\nअन्त धाम शिवपुर में पावे ॥ 40', transliteration: ''),
    LyricStanza(startTimeMs: 1200000, devanagari: 'कहैं अयोध्यादास आस तुम्हारी ।\nजानि सकल दुःख हरहु हमारी ॥', transliteration: ''),
  ],
  'ElVaIJJmpBk': [
    LyricStanza(startTimeMs: 0, devanagari: 'षष्टियै नोक्क शरवन भवनार्\nसिश्टरुक् कुडवुम् सॆन्कदिर् वेलोन्\nपादम् इरण्डिल् पन्मणि चदन्गै\nगीतम् पाड किङ्किणि याड', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'मैय नडन्चॆयुम् मयिल् वाहननार्\nकैयिल् वेलाल् ऎनै काक्क वॆण्ड्रु वन्दु\nवर वर वेला युदनार् वरुग\nवरुग वरुग मयिलोन् वरुग', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'इन्दिरन् मुदला यॆण्डिसै पोट्र\nमन्तिर वडिवेल् वरुग वरुग', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'वासवन् मरुगा वरुग वरुग\nनेसक् कुऱमगळ् निनैवोन् वरुग\nआरुमुखम् पडैत्त अय्या वरुग\nनीऱिडुम् वेलवन् नित्तम् वरुग', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'सिरगिरि वेलवन् सीक्किरम् वरुग\nशरहन भवनार् शडुदियिल् वरुग', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'रहण भवच र र र र र र र\nरिहण भवच रि रि रि रि रि रि रि\nविणभव शरहण वीरा नमो नमो\nनिभव शरहण निऱ निऱ निऱन', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'वचर हणब वरुग वरुग\nअसुरर् कुडि कॆडुत्त अय्या वरुग\nऎन्नै आळुम् इळैयोन् कैयिल्\nपन्निरण्डायुम् पासान्गुशमुम्', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'परन्ध विऴिगळ् पन्निरण्डिलन्ग\nविरैन्दु ऎनैक् काक्क वेलोन् वरुग\nअय्युम् किलियुम् अडैवुडन् शौवुम्\nउय्यॊळि शौवुम्, उयिरैयुङ् किलियुम्', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'किलियुम् शौवुम् किळरॊळिऐयुम्\nनिलै पॆट्ऱॆन्मुन् नित्तमुम् ऒळिरुम्', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'शन्मुखन् नीयुम् तनिऒळि यॊव्वुम्\nकुण्डलि याम् शिव गुहन् दिनम् वरुग', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'आरुमुखमुम् अणिमुडि आरुम्\nनीरिडु नॆट्रियुम् नीण्ड पुरुवमुम्\nपन्निरु कण्णुम् पवलच् चॆव्वायुम्', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'नन् नॆरि नॆट्रियिल् नवमणिच् चुट्टियुम्\nई अरारु सॆवियिल् इलगु कुण्डलमुम्\nआरिरु तिण्भुयत् तऴगिय मार्बिल्\nपल् बूशनमुम् पदक्कमुम् दरित्तु', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'नन्मनि पूण्ड नवरत्न मालैयुम्\nमुप्पुरि नूलुम् मुत्तणि मार्बुम्\nसॆप्पऴ गुडैय तिरुवयिरु उन्दियुम्\nतुवण्ड मरुन्गिल् सुडरॊलि पट्टुम्', transliteration: ''),
    LyricStanza(startTimeMs: 390000, devanagari: 'नवरत्नम् पदित्त नर्चीऱावुम्\nइरु तॊडै अऴगुम् इणैमुऴन् दालुम्', transliteration: ''),
    LyricStanza(startTimeMs: 420000, devanagari: 'तिरुवडि यदनिल् शिलम्बॊलि मुऴन्ग\nशॆगगण शॆगगण शॆगगण शॆगण\nमॊगमॊग मॊगमॊग मॊगमॊग मॊगन\nनगनग नगनग नगनग नगॆन', transliteration: ''),
    LyricStanza(startTimeMs: 450000, devanagari: 'डिगुगुण डिगुडिगु डिगुगुण डिगुण\nर र र र र र र र र र र\nरि रि रि रि रि रि रि रि रि रि रि रि रि रि रि\nडु डु डु डु डु डु डु डु डु डु डु डु डु डु डु', transliteration: ''),
    LyricStanza(startTimeMs: 480000, devanagari: 'डगु डगु डिगु डिगु डङ्गु डिङ्गुगु\nविन्दु विन्दु मयिलोन् विन्दु', transliteration: ''),
    LyricStanza(startTimeMs: 510000, devanagari: 'मुन्दु मुन्दु मुरुगवॆळ् मुन्दु\nऎण्ड्रनै याळुम् येरगच् सॆल्व!\nमैन्दन् वेण्डुम् वरमगिऴ्न्द् उदवुम्\nलाला लाला लाला वेसमुम्', transliteration: ''),
    LyricStanza(startTimeMs: 540000, devanagari: 'लीला लीला लीला विनोदनॆण्ड्रु\nउन् तिरु वडियै उरुदियॆण्ड्रॆण्णुम्\nऎण्ड्रनै वैत्तुन् इणैयडि काक्क\nऎन्नुयिर्क् कुरियाम् इरैवन् काक्क', transliteration: ''),
    LyricStanza(startTimeMs: 570000, devanagari: 'पन्निरु विऴियाल् बालनैक् काक्क\nअडियेन् वदनम् अऴगुवेल् काक्क', transliteration: ''),
    LyricStanza(startTimeMs: 600000, devanagari: 'पॊडिपुनै नॆट्रियै पुनिदवेल् काक्क\nकदिर्वेल् इरण्डुम् कण्णिनैक् काक्क\nविऴि सॆवि यिरण्डुम् वेलवर् काक्क\nनासिगळ् इरण्डुम् नल्वेल् काक्का', transliteration: ''),
    LyricStanza(startTimeMs: 630000, devanagari: 'पेसिय वैथनै पॆरुवेल् काक्क\nमुप्पत् तिरुपल् मुनैवेल् काक्क\nसॆप्पिय नावैच् चॆव्वेल् काक्क', transliteration: ''),
    LyricStanza(startTimeMs: 660000, devanagari: 'कन्नम् इरण्डुम् कार्थिवेल् काक्क\nऎन्निलन्ग् कऴुत्तै इनियवेल् काक्क\nमार्बै रत्न वडिवेल् काक्क', transliteration: ''),
    LyricStanza(startTimeMs: 690000, devanagari: 'सॆरिळ मुलैमार् तिरुवेल् काक्क\nवडिवेल् इरुतोळ् वळम्पॆर काक्क\nपिडरिगळ् इरण्डुम् पॆरुवेल् काक्क\nअऴगुडन् मुदुगै अरुळ्वेल् काक्क', transliteration: ''),
    LyricStanza(startTimeMs: 720000, devanagari: 'पऴु पतिनारुम् परुवेल् काक्क\nवॆट्रिवेल् वयिट्रै विळन्गवे काक्क\nसिट्रिडै अऴगुर शॆव्वेल् काक्क\nनानाङ् कयिट्रै नल्वेल् काक्क', transliteration: ''),
    LyricStanza(startTimeMs: 750000, devanagari: 'आण्पॆन् कुरि यिरण्डुम् अयिल्वेल् काक्क\nपिट्टम् इरण्डुम् पॆरुवेल् काक्क', transliteration: ''),
    LyricStanza(startTimeMs: 780000, devanagari: 'वट्टक् कुडत्तै वल्वेल् काक्क\nपणै तॊडै इरण्डुम् परुवेल् काक्क\nकणैक्काल् मुऴन्ताल् कदिर्वेल् काक्क\nअय्विरल् अडियिनै अरुळ्वेल् काक्क', transliteration: ''),
    LyricStanza(startTimeMs: 810000, devanagari: 'कैकळिरण्डुम् करुनैवेल् काक्क\nमुन्कै इरण्डुम् मुरण्वेल् काक्क\nपिन्कै इरण्डुम् पिन्नवळ् इरुक्क\nनाविल् सरस्वति नट्रुनै याग', transliteration: ''),
    LyricStanza(startTimeMs: 840000, devanagari: 'नाबिक् कमलम् नल्वेल् काक्क\nमुप्पाल् नाडियै मुनैवेल् काक्क', transliteration: ''),
    LyricStanza(startTimeMs: 870000, devanagari: 'ऎप्पॊऴुदुम् ऎनै ऎदिर्वेल् काक्क\nअडियेन् वचनम् अशैवुळ नेरम्\nकडुगवे वन्दु कनकवेल् काक्क\nवरुम्पगळ् तन्निल् वज्रवेल् काक्क', transliteration: ''),
    LyricStanza(startTimeMs: 900000, devanagari: 'अरैयिरुळ् तन्निल् अनैयवेल् काक्क\nयेमतिल् जामत्तिल् ऎदिर्वेल् काक्क\nतामदम् नीक्कि चतुर्वेल् काक्क\nकाक्क काक्क कनकवेल् काक्क', transliteration: ''),
    LyricStanza(startTimeMs: 930000, devanagari: 'नोक्क नोक्क नॊडियिनिल् नोक्क\nताक्क ताक्क तडैयरत् ताक्क', transliteration: ''),
    LyricStanza(startTimeMs: 960000, devanagari: 'पार्क्क पार्क्क पावम् पॊडिपड\nबिल्ली शूनियम् पॆरुम्पगै अगल\nवल्ल भूथम् वलाटिगप् पेय्गळ्\nअल्लल् पडुत्तुम् अडन्ग मुनियुम्', transliteration: ''),
    LyricStanza(startTimeMs: 990000, devanagari: 'पिळ्ळैगळ् टिन्नुम् पुऴक्कडै मुनियुम्\nकॊऌवै पॆय्गळुम् कुरळैप् पेय्गळुम्\nपॆन्कलै तॊडरुम् ब्रह्म्म राक्शसरुम्\nअडियनै कण्डाल् अलरिक् कलन्गिड', transliteration: ''),
    LyricStanza(startTimeMs: 1020000, devanagari: 'इरिसि काट्टॆरि इत्तुन्ब सेनैयुम्\nऎल्लिलुम् इरुट्टिलुम् ऎदिर्पडुम् अण्णरुम्', transliteration: ''),
    LyricStanza(startTimeMs: 1050000, devanagari: 'कनपूजै कॊळ्ळुम् कालियॊ डनैवरुम्\nविट्टान्ग् काररुम् मिगुपल पेय्गळुम्\nतण्डियक् काररुम् चण्डाळर्गळुम्\nऎन् पॆयर् शॊल्लवुम् इडि विऴुन् दॊडिड', transliteration: ''),
    LyricStanza(startTimeMs: 1080000, devanagari: 'आनै यडियिनिल् अरुम्पा वैगलुम्\nपूनै मयिरुम् पिळ्ळैगल् ऎन्बुम्\nनगमुम् मयिरुम् नीळ्मुडि मण्डैयुम्\nपावैगळुडने पल कलशत्तुडन्', transliteration: ''),
    LyricStanza(startTimeMs: 1110000, devanagari: 'मनैयिर् पुदैत्त वन्जनै तनैयुम्\nऒट्टिय पावैयुम् ऒट्टिय सॆरुक्कुम्', transliteration: ''),
    LyricStanza(startTimeMs: 1140000, devanagari: 'कासुम् पनमुम् कावुडन् सोरुम्\nओदुमन्जनमुम् ऒरुवऴिप् पोक्कुम्\nअडियनै कण्डाल् अलैन्दु कुलैन्दिड\nमाट्रार् वन्चगर् वन्दु वणङ्गिड', transliteration: ''),
    LyricStanza(startTimeMs: 1170000, devanagari: 'काल धूताल् ऎनैक् कण्डार् कलन्गिड\nअन्जि नडुङ्गिड अरण्डु पुरण्डिड\nवाइ विट्टलरि मधि कॆट्टॊड\nपडियिनिल् मुत्ताप् पासक् कयिट्राल्', transliteration: ''),
    LyricStanza(startTimeMs: 1200000, devanagari: 'कट्टुडन् अन्गम् कदरिडक् कट्टु\nकट्टि उरुट्टु कैकाल् मुरिय', transliteration: ''),
    LyricStanza(startTimeMs: 1230000, devanagari: 'कट्टु कट्टु कदरिडक् कट्टु\nमुट्टु मुट्टु विऴिगळ् पिदुन्गिड\nचॆक्कु चॆक्कु चॆदिल् चॆदिलाग\nचॊक्कु चॊक्कु सूर्पगै चॊक्कु', transliteration: ''),
    LyricStanza(startTimeMs: 1260000, devanagari: 'कुत्तु कुत्तु कूर्वडि वेलाल्\nपट्रु पट्रु पगलवन् तणलॆरि\nतणलॆरि तणलॆरि तणलदुवाग\nविडुविडु वेलै वॆरुण्डदु ओड', transliteration: ''),
    LyricStanza(startTimeMs: 1290000, devanagari: 'पुलियुम् नरियुम् पुन्नरि नायुम्\nऎलियुम् करडियुम् इनित् तॊडर्न्द् ओड', transliteration: ''),
    LyricStanza(startTimeMs: 1320000, devanagari: 'तेळुम् पाम्बुम् सॆय्यान् पूरान्\nकडिविड विषन्गळ् कडितुयर् अन्गम्\nएरिय विषन्गल् ऎलिदिनिल् इरन्ग\nपॊळुप्पुन्ज् चुळुक्कुम् ऒरुतलै नॊयुम्', transliteration: ''),
    LyricStanza(startTimeMs: 1350000, devanagari: 'वादम् चयितियम् वलिप्पुप् पित्तम्\nसूळै चयङ् कुन्मम् सॊक्कु चिरन्गु\nकुडैचल् सिलन्दि कुडल्विप् पिरिदि\nपक्क पिळवै पडर् तॊडै वाऴै', transliteration: ''),
    LyricStanza(startTimeMs: 1380000, devanagari: 'कडुवन् पडुवन् कैत्ताळ् सिलन्दि\nपर्कुत्तु अरणै परु वरै याप्पुम्', transliteration: ''),
    LyricStanza(startTimeMs: 1410000, devanagari: 'यॆल्लाप् पिणियुम् ऎण्ड्रनैक् कण्डाल्\nनिल्ला दोड नीयॆनक् करुळ्वाइ\nईर् ऎऴु उलगमुम् ऎनक्कुरवाग\nआणुम् पॆण्णुम् अनैवरुम् यॆनक्क', transliteration: ''),
    LyricStanza(startTimeMs: 1440000, devanagari: 'मण्णाळ् अरसरुम् मगिऴ्न्दुरवागवुम्\nउन्नैत् तुदिक्क उन् तिरुनामम्\nशरवन भवने सैलॊळि भवने\nतिरिपुर भवने तिगऴॊळि भवने', transliteration: ''),
    LyricStanza(startTimeMs: 1470000, devanagari: 'परिपुर भवने पवमॊळि भवने\nअरिथिरु मरुग अमरा पतियै', transliteration: ''),
    LyricStanza(startTimeMs: 1500000, devanagari: 'कात्तुत् देवर्गळ् कडुन्ज् चिरै विडुत्ताइ\nकन्दा गुहने कदिर् वेलवने\nकार्तिकै मैन्दा कडम्बा कडम्बनै\nइडुम्बनै अऴित्त इनियवेल् मुरुगा', transliteration: ''),
    LyricStanza(startTimeMs: 1530000, devanagari: 'तणिकाचलने शन्करन् पुदल्वा\nकदिर्का मत्तुरै कदिर्वेल् मुरुगा', transliteration: ''),
    LyricStanza(startTimeMs: 1560000, devanagari: 'पऴनि पदिवाऴ् बालकुमारा\nआविनन् कुडिवाऴ् अऴगिय वेला\nसॆन्दिन्मा मलैयुरुम् चॆन्गल्वराया\nशमरा पुरिवाऴ् शन्मुखत् अरसे', transliteration: ''),
    LyricStanza(startTimeMs: 1590000, devanagari: 'कारार् कुऴलल् कलैमगळ् नण्ड्राइ\nयॆन्ना इरुक्क यानुनैप् पाड\nयॆनै तॊडर्दिरुक्कुम् ऎन्थै मुरुगनै\nपाडिनेन् आडिनेन् परवसमाग', transliteration: ''),
    LyricStanza(startTimeMs: 1620000, devanagari: 'आडिनेन् आडिनेन् आविनन् बूथियै\nनेसमुडन् यान् नॆट्रियिल् अनिय\nपास विनैगल् पट्रदु नीङ्गि\nउन्पदम् पॆरवे उन्नरुलाग', transliteration: ''),
    LyricStanza(startTimeMs: 1650000, devanagari: 'अन्बुडन् रक्शि अन्नमुन्ज् चॊन्नमुम्\nमॆत्त मॆत्ताग वेलायु दनार्', transliteration: ''),
    LyricStanza(startTimeMs: 1680000, devanagari: 'सिद्धि पॆट्ट्रडियॆन् सिरप्पुडन् वाऴ्ग\nवाऴ्ग वाऴ्ग मयिलोन् वाऴ्ग\nवाऴ्ग वाऴ्ग वडिवेल् वाऴ्ग\nवाऴ्ग वाऴ्ग मलै गुरु वाऴ्ग', transliteration: ''),
    LyricStanza(startTimeMs: 1710000, devanagari: 'वाऴ्ग वाऴ्ग मलै कुर मगळुडन्\nवाऴ्ग वाऴ्ग वारण दुवसम्\nवाऴ्ग वाऴ्ग वॆन् वरुमैगळ् नीङ्ग\nयॆत्तनै कुरैगळ् ऎत्तनै पिऴैगळ्', transliteration: ''),
    LyricStanza(startTimeMs: 1740000, devanagari: 'यॆत्तनै यडियॆन् ऎत्तनै सॆय्यिनुम्\nपॆट्रवन् नीगुरु पॊरुप्पदु उन्कडन्', transliteration: ''),
    LyricStanza(startTimeMs: 1770000, devanagari: 'पॆट्रवळ् कुरमगळ् पॆट्रवळामे\nपिळ्ळै यॆण्ड्रन्बाइ प्रिय मळित्तु\nमैन्दन् ऎन् मीदु उन् मन मगिऴ्न्दु अरुळि\nतन्जम् ऎण्ड्रु अडियार् तऴैत्तिड अरुळ्सॆय्', transliteration: ''),
    LyricStanza(startTimeMs: 1800000, devanagari: 'कन्दर् षष्ठी कवचम् विरुम्बिय\nबालन् देव रायन् पगर्न् ददै\nकालैयिल् मालैयिल् करुत्तुडन् नाळुम्\nआचा रत्तुडन् अन्गङ् तुलक्कि', transliteration: ''),
    LyricStanza(startTimeMs: 1830000, devanagari: 'नेसमुडन् ऒरु निनैवदुवागि\nकन्दर् षष्ठी कवचम् इदनै', transliteration: ''),
    LyricStanza(startTimeMs: 1860000, devanagari: 'चिन्तै कलन्गादु द्यनिप्पवर्गळ्\nऒरुनाळ् मुप्पत् तारुरु कॊण्डु\nओदियॆ जपित्तु उगन्दु नीरणिय\nअष्ट दिक्कुळ्ळोर् अडन्गलुम् वसमै', transliteration: ''),
    LyricStanza(startTimeMs: 1890000, devanagari: 'दिसै मन्नर् ऎण्मर् सॆयलदु अरुळुवर्\nमाट्रलरॆल्लाम् वन्दु वणङ्गुवर्\nनवकोळ् मग्ऴिन्दु नन्मै यळिथिदुम्\nनवमद नॆनवुम् नल्लॆऴिल् पॆरुवर्', transliteration: ''),
    LyricStanza(startTimeMs: 1920000, devanagari: 'ऎन्दनाळुम् ईरॆट्टाइ वाऴ्वर्\nकन्दर् कै वेलम् कवच तडियै', transliteration: ''),
    LyricStanza(startTimeMs: 1950000, devanagari: 'वऴियै काण मॆय्यै विळन्गुम्\nविऴियार्काण वॆरुण्डिडुम् पेय्गळ्\nपॊल्ला दवरै पॊडि पॊडि याक्कुम्\nनल्लॊर् निनैविल् नटनम् पुरियुम्', transliteration: ''),
    LyricStanza(startTimeMs: 1980000, devanagari: 'सर्व शत्तुरु सन्गा रत्तडि\nअरिन्दॆनदु उल्लम् अष्ट लक्ष्मिगळि\nवीर लक्ष्मिक्कु विरुन् दुणवाग\nसूर पद्मावै तुणित्तगै यदनाल्', transliteration: ''),
    LyricStanza(startTimeMs: 2010000, devanagari: 'इरुब तॆऴ्वरुक्कु उवन् दमुदलित्त\nगुरुपरन् पऴनि कुण्ड्रिल् इरुक्कुम्', transliteration: ''),
    LyricStanza(startTimeMs: 2040000, devanagari: 'चिन्न कुऴन्दै सेवडि पोट्रि\nयॆनै तडु ताट्कॊळ यॆण्ड्रन दुळ्ळम्\nमेविय वडिवुरुम् वेलवा पोट्रि\nदेवर्गळ् सेना पतिये पोट्रि', transliteration: ''),
    LyricStanza(startTimeMs: 2070000, devanagari: 'कुरमगळ् मन मगिऴ् कोवे पोट्रि\nतिरमिगु दिव्य देहा पोट्रि\nइडुम्बा युदने इडुम्बा पोट्रि\nकडम्बा पोट्रि कन्दा पोट्रि', transliteration: ''),
    LyricStanza(startTimeMs: 2100000, devanagari: 'वॆट्चि पुनैयुम् वेळे पोट्रि\nउयर्गिरि कनक सबैक्कोर् अरसे', transliteration: ''),
    LyricStanza(startTimeMs: 2130000, devanagari: 'मयिल् नट मिडुवॊइ मलरडि शरणम्\nशरणम् शरणम् शरवण भव ओं\nशरणम् शरणम् षण्मुख शरणम्\nशरणम् शरणम् षण्मुख शरणम्', transliteration: ''),
  ],
  'FlF9MJ-IG4U': [
    LyricStanza(startTimeMs: 0, devanagari: 'लख लख दीवला री,\nए आरती माँ,\nसेरी ए रमती आय,\nरमती जगती ए आरती माँ,\nनाडोल नगरी माय,\nलख लख दिवला री,\nए आरती माँ,\nनाडोल नगरी माय।।', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'हे ढोल बाजे ए आरती माँ,\nभूम भोमिया छिडकाय,\nढोल बाजे ए आरती माँ,\nभूम भोमिया छिडकाय,\nआरती मे ए आवजो माँ,\nगरबे रमती आव,\nआरती मे ए आवजो माँ,\nगरबे रमती आव,', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'लख लख दिवला री,\nए आरती माँ,\nसेरी ए रमती आय।।', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'शेरावाली ए मावडी माँ,\nआशापुरी मेरी माँ,\nहे शेरावाली ए मावडी माँ,\nआशापुरी मेरी माँ,\nवेगा वेगा ए आवजो माँ,\nआरतीया रे माय,\nवेगा वेगा ए आवजो माँ,\nआरतीया रे माय,', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'लख लख दिवला री,\nए आरती माँ,\nसेरी ए रमती आय।।', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'लाल चुनडीया ए मावडी ने,\nलावा मै तो आज,\nलाल चुनडीया ए मावडी ने,\nलावा मै तो आज,\nसिर पर रखडी ए नाक में नथडी,\nगले नवलखीयो हार,\nसिर पर रखडी ए नाक में नथडी,\nगले नवलखीयो हार,', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'लख लख दिवला री,\nए आरती माँ,\nसेरी ए रमती आय।।', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'हे हाथा चुडलो ए मावडी रे,\nनखल्या लाल गुलाल,\nहाथा चुडलो ए मावडी रे,\nनखल्या लाल गुलाल,\nहे आरती मे ए आप पधारो,\nकर सोलह सिन्गार,\nआरती मे ए आप पधारो,\nकर सोलह सिन्गार,', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'लख लख दिवला री,\nए आरती माँ,\nसेरी ए रमती आय।।', transliteration: ''),
  ],
  'Gcf2EmWWML0': [
    LyricStanza(startTimeMs: 0, devanagari: 'गङ्गाष्टकं श्रीवाल्मिकिविरचितम्\nमातः शैलसुता-सपत्नि वसुधा-श‍ृङ्गारहारावलि\nस्वर्गारोहण-वैजयन्ति भवतीं भागीरथीं प्रार्थये ।\nत्वत्तीरे वसतः त्वदंबु पिबतस्त्वद्वीचिषु प्रेङ्खतः\nत्वन्नाम स्मरतस्त्वदर्पितदृशः स्यान्मे शरीरव्ययः ॥ १॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'त्वत्तीरे तरुकोटरान्तरगतो गङ्गे विहङ्गो परं\nत्वन्नीरे नरकान्तकारिणि वरं मत्स्योऽथवा कच्छपः ।\nनैवान्यत्र मदान्धसिन्धुरघटासंघट्टघण्टारण-\nत्कारस्तत्र समस्तवैरिवनिता-लब्धस्तुतिर्भूपतिः ॥ २॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'उक्षा पक्षी तुरग उरगः कोऽपि वा वारणो वाऽ-\nवारीणः स्यां जनन-मरण-क्लेशदुःखासहिष्णुः ।\nन त्वन्यत्र प्रविरल-रणत्किङ्किणी-क्वाणमित्रं\nवारस्त्रीभिश्चमरमरुता वीजितो भूमिपालः ॥ ३॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'काकैर्निष्कुषितं श्वभिः कवलितं गोमायुभिर्लुण्टितं\nस्रोतोभिश्चलितं तटाम्बु-लुलितं वीचीभिरान्दोलितम् ।\nदिव्यस्त्री-कर-चारुचामर-मरुत्संवीज्यमानः कदा\nद्रक्ष्येऽहं परमेश्वरि त्रिपथगे भागीरथी स्वं वपुः ॥ ४॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'अभिनव-बिसवल्ली-पादपद्मस्य विष्णोः\nमदन-मथन-मौलेर्मालती-पुष्पमाला ।\nजयति जयपताका काप्यसौ मोक्षलक्ष्म्याः\nक्षपित-कलिकलङ्का जाह्नवी नः पुनातु ॥ ५॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'एतत्ताल-तमाल-साल-सरलव्यालोल-वल्लीलता-\nच्छत्रं सूर्यकर-प्रतापरहितं शङ्खेन्दु-कुन्दोज्ज्वलम् ।\nगन्धर्वामर-सिद्ध-किन्नरवधू-तुङ्गस्तनास्पालितं\nस्नानाय प्रतिवासरं भवतु मे गाङ्गं जलं निर्मलम् ॥ ६॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'गाङ्गं वारि मनोहारि मुरारि-चरणच्युतम् ।\nत्रिपुरारि-शिरश्चारि पापहारि पुनातु माम् ॥ ७॥', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'पापापहारि दुरितारि तरङ्गधारि\nशैलप्रचारि गिरिराज-गुहाविदारि ।\nझङ्कारकारि हरिपाद-रजोपहारि\nगाङ्गं पुनातु सततं शुभकारि वारि ॥ ८॥', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'गङ्गाष्टकं पठति यः प्रयतः प्रभाते\nवाल्मीकिना विरचितं शुभदं मनुष्यः ।\nप्रक्षाल्य गात्र-कलिकल्मष-पङ्क-माशु\nमोक्षं लभेत् पतति नैव नरो भवाब्धौ ॥ ९॥', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: '॥ इति वाल्मीकिविरचितं गङ्गाष्टकं सम्पूर्णम् ॥', transliteration: ''),
  ],
  'HHNV9sLs4ns': [
    LyricStanza(startTimeMs: 0, devanagari: '॥ न्यासः ॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'अस्य श्रीललितात्रिशती-स्तोत्र-महामन्त्रस्य भगवान् हयग्रीव ऋषिः,\nअनुष्टुप्छन्दः, श्रीललितामहात्रिपुरसुन्दरी देवता,\nऐं बीजम्, सौः शक्तिः, क्लीं कीलकम्,\nमम चतुर्विध-फलपुरुषार्थे जपे पारायणे विनियोगः ॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'ऐं अङ्गुष्ठाभ्यां नमः ।\nक्लीं तर्जनीभ्यां नमः ।\nसौः मध्यमाभ्यां नमः ।\nऐं अनामिकाभ्यां नमः ।\nक्लीं कनिष्ठिकाभ्यां नमः ।\nसौः करतलकरपृष्ठाभ्यां नमः ॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'ऐं हृदयाय नमः ।\nक्लीं शिरसे स्वाहा ।\nसौः शिखायै वषट् ।\nऐं कवचाय हुम् ।\nक्लीं नेत्रत्रयाय वौषट् ।\nसौः अस्त्राय फट् ।\nभूर्भुवस्सुवरोमिति दिग्बन्धः ॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: '॥ ध्यानम् ॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'अतिमधुर-चापहस्तामपरिमितामोद-बाण-सौभाग्याम् ।\nअरुणामतिशयकरुणामभिनव-कुलसुन्दरीं वन्दे ॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: '॥ लं इत्यादि पञ्चपूजा ॥', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'लं पृथिव्यात्मिकायै श्रीललिताम्बिकायै गन्धं समर्पयामि ।\nहं आकाशात्मिकायै श्रीललिताम्बिकायै पुष्पैः पूजयामि ।\nयं वाय्वात्मिकायै श्रीललिताम्बिकायै धूपमाघ्रापयामि ।\nरं वह्यात्मिकायै श्रीललिताम्बिकायै दीपं दर्शयामि ।\nवं अमृतात्मिकायै श्रीललिताम्बिकायै अमृतं महानैवेद्यं निवेदयामि ।\nसं सर्वात्मिकायै श्रीललिताम्बिकायै सर्वोपचारपूजां समर्पयामि ॥', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: '॥ अथ श्रीललितात्रिशती स्तोत्रम् ॥', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'ककाररूपा कल्याणी कल्याणगुणशालिनी ।\nकल्याणशैलनिलया कमनीया कलावती ॥ १॥', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'कमलाक्षी कल्मषघ्नी करुणामृतसागरा ।\nकदम्ब-काननावासा कदम्ब- कुसुमप्रिया ॥ २॥', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'कन्दर्पविद्या कन्दर्प-जनकापाङ्गवीक्षणा ।\nकर्पूरवीटी-सौरभ्य-कल्लोलित-ककुप्तटा ॥ ३॥', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'कलिदोषहरा कञ्जलोचना कम्रविग्रहा ।\nकर्मादिसाक्षिणी कारयित्री कर्मफलप्रदा ॥ ४॥', transliteration: ''),
    LyricStanza(startTimeMs: 390000, devanagari: 'एकाररूपा चैकाक्षर्येकानेकाक्षराकृतिः ।\nएतत्तदित्यनिर्देश्या चैकानन्दचिदाकृतिः ॥ ५॥', transliteration: ''),
    LyricStanza(startTimeMs: 420000, devanagari: 'एवमित्यागमाबोध्या चैकभक्तिमदर्चिता ।\nएकाग्रचित्त-निर्ध्याता चैषणा-रहितादृता ॥ ६॥', transliteration: ''),
    LyricStanza(startTimeMs: 450000, devanagari: 'एलासुगन्धिचिकुरा चैनः कूटविनाशिनी ।\nएकभोगा चैकरसा चैकैश्वर्यप्रदायिनी ॥ ७॥', transliteration: ''),
    LyricStanza(startTimeMs: 480000, devanagari: 'एकातपत्र-साम्राज्यप्रदा चैकान्तपूजिता ।\nएधमानप्रभा चैजदनेकजगदीश्वरी ॥ ८॥', transliteration: ''),
    LyricStanza(startTimeMs: 510000, devanagari: 'एकवीरादि-संसेव्या चैकप्राभव-शालिनी ।\nईकाररूपा चेशित्री चेप्सितार्थ-प्रदायिनी ॥ ९॥', transliteration: ''),
    LyricStanza(startTimeMs: 540000, devanagari: 'ईदृगित्यविनिर्देश्या चेश्वरत्व-विधायिनी ।\nईशानादि-ब्रह्ममयी चेशित्वाद्यष्टसिद्धिदा ॥ १०॥', transliteration: ''),
    LyricStanza(startTimeMs: 570000, devanagari: 'ईक्षित्रीक्षण-सृष्टाण्डकोटिरीश्वरवल्लभा ।\nईडिता चेश्वरार्धाङ्गशरीरेशाधिदेवता ॥ ११॥', transliteration: ''),
    LyricStanza(startTimeMs: 600000, devanagari: 'ईश्वरप्रेरणकरी चेशताण्डव-साक्षिणी ।\nईश्वरोत्सङ्गनिलया चेतिबाधा-विनाशिनी ॥ १२॥', transliteration: ''),
    LyricStanza(startTimeMs: 630000, devanagari: 'ईहाविराहिता चेशशक्तिरीषत्स्मितानना ।\nलकाररूपा ललिता लक्ष्मीवाणीनिषेविता ॥ १३॥', transliteration: ''),
    LyricStanza(startTimeMs: 660000, devanagari: 'लाकिनी ललनारूपा लसद्दाडिमपाटला ।\nललन्तिका-लसत्फाला ललाटनयनार्चिता ॥ १४॥', transliteration: ''),
    LyricStanza(startTimeMs: 690000, devanagari: 'लक्षणोज्ज्वल-दिव्याङ्गी लक्षकोट्यण्ड-नायिका ।\nलक्ष्यार्था लक्षणागम्या लब्धकामा लतातनुः ॥ १५॥', transliteration: ''),
    LyricStanza(startTimeMs: 720000, devanagari: 'ललामराजदलिका लम्बिमुक्तालताञ्चिता ।\nलम्बोदरप्रसूर्लभ्या लज्जाढ्या लयवर्जिता ॥ १६॥', transliteration: ''),
    LyricStanza(startTimeMs: 750000, devanagari: 'ह्रींकाररूपा ह्रींकारनिलया ह्रींपदप्रिया ।\nह्रींकारबीजा ह्रींकारमन्त्रा ह्रींकारलक्षणा ॥ १७॥', transliteration: ''),
    LyricStanza(startTimeMs: 780000, devanagari: 'ह्रींकारजपसुप्रीता ह्रींमती ह्रींविभूषणा ।\nह्रींशीला ह्रींपदाराध्या ह्रींगर्भा ह्रींपदाभिधा ॥ १८॥', transliteration: ''),
    LyricStanza(startTimeMs: 810000, devanagari: 'ह्रींकारवाच्या ह्रींकारपूज्या ह्रींकारपीठिका ।\nह्रींकारवेद्या ह्रींकारचिन्त्या ह्रीं ह्रींशरीरिणी ॥ १९॥', transliteration: ''),
    LyricStanza(startTimeMs: 840000, devanagari: 'हकाररूपा हलधृत्पूजिता हरिणेक्षणा ।\nहरप्रिया हराराध्या हरिब्रह्मेन्द्रवन्दिता ॥ २०॥', transliteration: ''),
    LyricStanza(startTimeMs: 870000, devanagari: 'हयारूढा-सेविताङ्घ्रिर्हयमेध-समर्चिता ।\nहर्यक्षवाहना हंसवाहना हतदानवा ॥ २१॥', transliteration: ''),
    LyricStanza(startTimeMs: 900000, devanagari: 'हत्यादिपापशमनी हरिदश्वादिसेविता ।\nहस्तिकुम्भोत्तुङ्गकुचा हस्तिकृत्ति-प्रियाङ्गना ॥ २२॥', transliteration: ''),
    LyricStanza(startTimeMs: 930000, devanagari: 'हरिद्राकुङ्कुमादिग्धा हर्यश्वाद्यमरार्चिता ।\nहरिकेशसखी हादिविद्या हालामदालसा ॥ २३॥', transliteration: ''),
    LyricStanza(startTimeMs: 960000, devanagari: 'सकाररूपा सर्वज्ञा सर्वेशी सर्वमङ्गला ।\nसर्वकर्त्री सर्वभर्त्री सर्वहन्त्री सनातना ॥ २४॥', transliteration: ''),
    LyricStanza(startTimeMs: 990000, devanagari: 'सर्वानवद्या सर्वाङ्गसुन्दरी सर्वसाक्षिणी ।\nसर्वात्मिका सर्वसौख्यदात्री सर्वविमोहिनी ॥ २५॥', transliteration: ''),
    LyricStanza(startTimeMs: 1020000, devanagari: 'सर्वाधारा सर्वगता सर्वावगुणवर्जिता ।\nसर्वारुणा सर्वमाता सर्वभूषणभूषिता ॥ २६॥', transliteration: ''),
    LyricStanza(startTimeMs: 1050000, devanagari: 'ककारार्था कालहन्त्री कामेशी कामितार्थदा ।\nकामसञ्जीविनी कल्या कठिनस्तनमण्डला ॥ २७॥', transliteration: ''),
    LyricStanza(startTimeMs: 1080000, devanagari: 'करभोरुः कलानाथमुखी कचजिताम्बुदा ।\nकटाक्षस्यन्दिकरुणा कपालिप्राणनायिका ॥ २८॥', transliteration: ''),
    LyricStanza(startTimeMs: 1110000, devanagari: 'कारुण्यविग्रहा कान्ता कान्तिधूत-जपावलिः ।\nकलालापा कम्बुकण्ठी करनिर्जित-पल्लवा ॥ २९॥', transliteration: ''),
    LyricStanza(startTimeMs: 1140000, devanagari: 'कल्पवल्ली-समभुजा कस्तूरी-तिलकाञ्चिता ।\nहकारार्था हंसगतिर्हाटकाभरणोज्ज्वला ॥ ३०॥', transliteration: ''),
    LyricStanza(startTimeMs: 1170000, devanagari: 'हारहारि-कुचाभोगा हाकिनी हल्यवर्जिता ।\nहरित्पति-समाराध्या हठात्कार-हतासुरा ॥ ३१॥', transliteration: ''),
    LyricStanza(startTimeMs: 1200000, devanagari: 'हर्षप्रदा हविर्भोक्त्री हार्द-सन्तमसापहा ।\nहल्लीसलास्यसन्तुष्टा हंसमन्त्रार्थ-रूपिणी ॥ ३२॥', transliteration: ''),
    LyricStanza(startTimeMs: 1230000, devanagari: 'हानोपादान-निर्मुक्ता हर्षिणी हरिसोदरी ।\nहाहाहूहू-मुखस्तुत्या हानिवृद्धि-विवर्जिता ॥ ३३॥', transliteration: ''),
    LyricStanza(startTimeMs: 1260000, devanagari: 'हय्यङ्गवीन-हृदया हरिगोपारुणांशुका ।\nलकाराख्या लतापूज्या लयस्थित्युद्भवेश्वरी ॥ ३४॥', transliteration: ''),
    LyricStanza(startTimeMs: 1290000, devanagari: 'लास्यदर्शन-सन्तुष्टा लाभालाभ-विवर्जिता ।\nलङ्घ्येतराज्ञा लावण्य-शालिनी लघुसिद्धिदा ॥ ३५॥', transliteration: ''),
    LyricStanza(startTimeMs: 1320000, devanagari: 'लाक्षारस-सवर्णाभा लक्ष्मणाग्रज-पूजिता ।\nलभ्येतरा लब्धभक्ति-सुलभा लाङ्गलायुधा ॥ ३६॥', transliteration: ''),
    LyricStanza(startTimeMs: 1350000, devanagari: 'लग्नचामर-हस्त-श्रीशारदा-परिवीजिता ।\nलज्जापद-समाराध्या लम्पटा लकुलेश्वरी ॥ ३७॥', transliteration: ''),
    LyricStanza(startTimeMs: 1380000, devanagari: 'लब्धमाना लब्धरसा लब्धसम्पत्समुन्नतिः ।\nह्रींकारिणी ह्रींकाराद्या ह्रींमध्या ह्रींशिखामणिः ॥ ३८॥', transliteration: ''),
    LyricStanza(startTimeMs: 1410000, devanagari: 'ह्रींकार-कुण्डाग्निशिखा ह्रींकार-शशिचन्द्रिका ।\nह्रींकार-भास्कररुचिर्ह्रींकाराम्भोद-चञ्चला ॥ ३९॥', transliteration: ''),
    LyricStanza(startTimeMs: 1440000, devanagari: 'ह्रींकारकन्दाङ्कुरिका ह्रींकारैक-परायणा ।\nह्रींकार-दीर्घिकाहंसी ह्रींकारोद्यान-केकिनी ॥ ४०॥', transliteration: ''),
    LyricStanza(startTimeMs: 1470000, devanagari: 'ह्रींकारारण्य-हरिणी ह्रींकारावाल-वल्लरी ।\nह्रींकार-पञ्जरशुकी ह्रींकाराङ्गण-दीपिका ॥ ४१॥', transliteration: ''),
    LyricStanza(startTimeMs: 1500000, devanagari: 'ह्रींकार-कन्दरासिंही ह्रींकाराम्भोज-भृङ्गिका ।\nह्रींकारसुमनो-माध्वी ह्रींकार-तरुमञ्जरी ॥ ४२॥', transliteration: ''),
    LyricStanza(startTimeMs: 1530000, devanagari: 'सकाराख्या समरसा सकलागम-संस्तुता ।\nसर्ववेदान्त-तात्पर्यभूमिः सदसदाश्रया ॥ ४३॥', transliteration: ''),
    LyricStanza(startTimeMs: 1560000, devanagari: 'सकला सच्चिदानन्दा साध्या सद्गतिदायिनी ।\nसनकादि-मुनिध्येया सदाशिव-कुटुम्बिनी ॥ ४४॥', transliteration: ''),
    LyricStanza(startTimeMs: 1590000, devanagari: 'सकालाधिष्ठानरूपा सत्यरूपा समाकृतिः ।\nसर्वप्रपञ्च-निर्मात्री समानाधिक-वर्जिता ॥ ४५॥', transliteration: ''),
    LyricStanza(startTimeMs: 1620000, devanagari: 'सर्वोत्तुङ्गा सङ्गहीना सगुणा सकलेष्टदा ।\nककारिणी काव्यलोला कामेश्वर-मनोहरा ॥ ४६॥', transliteration: ''),
    LyricStanza(startTimeMs: 1650000, devanagari: 'कामेश्वर-प्राणनाडी कामेशोत्सङ्ग-वासिनी ।\nकामेश्वरालिङ्गिताङ्गी कामेश्वर-सुखप्रदा ॥ ४७॥', transliteration: ''),
    LyricStanza(startTimeMs: 1680000, devanagari: 'कामेश्वर-प्रणयिनी कामेश्वर-विलासिनी ।\nकामेश्वर-तपःसिद्धिः कामेश्वर-मनःप्रिया ॥ ४८॥', transliteration: ''),
    LyricStanza(startTimeMs: 1710000, devanagari: 'कामेश्वर-प्राणनाथा कामेश्वर-विमोहिनी ।\nकामेश्वर-ब्रह्मविद्या कामेश्वर-गृहेश्वरी ॥ ४९॥', transliteration: ''),
    LyricStanza(startTimeMs: 1740000, devanagari: 'कामेश्वराह्लादकरी कामेश्वर-महेश्वरी ।\nकामेश्वरी कामकोटि-निलया काङ्क्षितार्थदा ॥ ५०॥', transliteration: ''),
    LyricStanza(startTimeMs: 1770000, devanagari: 'लकारिणी लब्धरूपा लब्धधीर्लब्धवाञ्छिता ।\nलब्धपाप-मनोदूरा लब्धाहङ्कार-दुर्गमा ॥ ५१॥', transliteration: ''),
    LyricStanza(startTimeMs: 1800000, devanagari: 'लब्धशक्तिर्लब्धदेहा लब्धैश्वर्य-समुन्नतिः ।\nलब्धवृद्धिर्लब्धलीला लब्धयौवन-शालिनी ॥ ५२॥', transliteration: ''),
    LyricStanza(startTimeMs: 1830000, devanagari: 'लब्धातिशय-सर्वाङ्ग-सौन्दर्या लब्ध-विभ्रमा ।\nलब्धरागा लब्धपतिर्लब्धनानागम-स्थितिः ॥ ५३॥', transliteration: ''),
    LyricStanza(startTimeMs: 1860000, devanagari: 'लब्धभोगा लब्धसुखा लब्धहर्षाभिपूरिता ।\nह्रींकारमूर्तिर्ह्रींकार-सौधश‍ृङ्ग-कपोतिका ॥ ५४॥', transliteration: ''),
    LyricStanza(startTimeMs: 1890000, devanagari: 'ह्रींकार-दुग्धाब्धि-सुधा ह्रींकार-कमलेन्दिरा ।\nह्रींकार-मणिदीपार्चिर्ह्रींकार-तरुशारिका ॥ ५५॥', transliteration: ''),
    LyricStanza(startTimeMs: 1920000, devanagari: 'ह्रींकार-पेटकमणिर्ह्रींकारदर्श-बिम्बिता ।\nह्रींकार-कोशासिलता ह्रींकारास्थान-नर्तकी ॥ ५६॥', transliteration: ''),
    LyricStanza(startTimeMs: 1950000, devanagari: 'ह्रींकार-शुक्तिका-मुक्तामणिर्ह्रींकार-बोधिता ।\nह्रींकारमय-सौवर्ण-स्तम्भ-विद्रुम-पुत्रिका ॥ ५७॥', transliteration: ''),
    LyricStanza(startTimeMs: 1980000, devanagari: 'ह्रींकार-वेदोपनिषद् ह्रींकाराध्वर-दक्षिणा ।\nह्रींकार-नन्दनाराम-नवकल्पक-वल्लरी ॥ ५८॥', transliteration: ''),
    LyricStanza(startTimeMs: 2010000, devanagari: 'ह्रींकार-हिमवद्गङ्गा ह्रींकारार्णव-कौस्तुभा ।\nह्रींकार-मन्त्रसर्वस्वा ह्रींकारपर-सौख्यदा ॥ ५९॥', transliteration: ''),
    LyricStanza(startTimeMs: 2040000, devanagari: '॥ इति श्रीललितात्रिशतीस्तोत्रं सम्पूर्णम् ॥', transliteration: ''),
    LyricStanza(startTimeMs: 2070000, devanagari: '॥ श्रीललिता त्रिशती उत्तरपीठिका ॥', transliteration: ''),
    LyricStanza(startTimeMs: 2100000, devanagari: 'श्रीहयग्रीव उवाच -\nइत्येवं ते मयाऽऽख्यातं देव्या नामशतत्रयम् ।\nरहस्यातिरहस्यत्वाद्गोपनीयं त्वया मुने ॥ १॥', transliteration: ''),
    LyricStanza(startTimeMs: 2130000, devanagari: 'शिववर्णानि नामानि श्रीदेव्या कथितानि हि ।\nशक्तयक्षराणि नामानि कामेश-कथितानि च ॥ २॥', transliteration: ''),
    LyricStanza(startTimeMs: 2160000, devanagari: 'उभयाक्षर-नामानि ह्युभाभ्यां कथितानि वै ।\nतदन्यैर्ग्रथितं स्तोत्रमेतस्य सदृशं किमु ॥ ३॥', transliteration: ''),
    LyricStanza(startTimeMs: 2190000, devanagari: 'नानेन सदृशं स्तोत्रं श्रीदेवी-प्रीतिदायकम् ।\nलोकत्रयेऽपि कल्याणं सम्भवेन्नात्र संशयः ॥ ४॥', transliteration: ''),
