  'IMT9q2YYxnY': [
    LyricStanza(startTimeMs: 0, devanagari: 'जय उमिया माता, ॐ जय उमिया माता,\nआरती गाता तमारी, हैया हरखाता,\nॐ जय उमिया माता', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'लाखो दिवडा जळहळ बळता,तेज तणो नहीं पार,\nमैया तेज तणो नहीं पार,\nदिव्य अलौकिक आभा, विजळीनो चमकार,\nॐ जय उमिया माता', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'मंगलकारी मुर्ति तमारी, मंदिरमां शोभे,\nमैया मंदिरमां शोभे,\nदर्शन करवा तमारा, मन सौनु लोभे,\nॐ जय उमिया माता', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'ढोल नगारा शरणायुंने, झालरनो झणकार,\nमैया झालरनो झणकार,\nमीठा सूर मोरलीना, करता एकाकार,\nॐ जय उमिया माता', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'अनेक रूपे एक तमे छो, परचा माँ पुरनार,\nमैया परचा माँ पुरनार,\nमहीमा तमारो मोटो, जगमां जय जयकार,\nॐ जय उमिया माता', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'सचराचरमां वास करो छो, माता ममताळी,\nमैया माता ममताळी,\nसमरे वेला आवो, करवा रखवाळी,\nॐ जय उमिया माता', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'भवसागरमां भटकेलाने, पलमां माँ तारे,\nमैया पलमां माँ तारे,\nपापी पावन थाता, माँ तारा घ्वारे,\nॐ जय उमिया माता', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'आदी अनादी मात तमे छो, वेदोमां वखणातां,\nमैया वेदोमां वखणातां,\nदेवो,दानव,मानव,गुण तारा गाता,\nॐ जय उमिया माता', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'अमी भरेली आंखोथी,माँ अमृत वरसावो,\nमैया अमृत वरसावो,\nसुना पडेला जीवनमां खुशीयो लहेरावो,\nॐ जय उमिया माता', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'फोरमता फुलडानो हुं तो, फुलगजरो लावुं,\nमैया फुलगजरो लावुं,\nहैयाना हेतेथी माँ तमने पहेरावुं,\nॐ जय उमिया माता', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'श्वासे श्वासे समरण करतो, अतुल तमारो दास,\nमैया अतुल तमारो दास,\nभक्तोने दर्शन आपो, पुरण करो माँ आश,\nॐ जय उमिया माता', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'जय उमिया माता, ॐ जयउमिया माता,\nआरती गाता तमारी, हैया हरखाता,\nॐ जय उमिया माता, ॐ जय उमिया माता,\nॐ जय उमिया माता, ॐ जय उमिया माता,', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'ॐ जय उमिया माता.\nबोलीए उमिया मातकी जय...', transliteration: ''),
  ],
  'JKpk-MH-1CE': [
    LyricStanza(startTimeMs: 0, devanagari: 'जयति जयति जय ललिते माता।तव गुण महिमा है विख्याता॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'तू सुन्दरी, त्रिपुरेश्वरी देवी।सुर नर मुनि तेरे पद सेवी॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'तू कल्याणी कष्ट निवारिणी।तू सुख दायिनी, विपदा हारिणी॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'मोह विनाशिनी दैत्य नाशिनी।भक्त भाविनी ज्योति प्रकाशिनी॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'आदि शक्ति श्री विद्या रूपा।चक्र स्वामिनी देह अनूपा॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'हृदय निवासिनी-भक्त तारिणी।नाना कष्ट विपति दल हारिणी॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'दश विद्या है रुप तुम्हारा।श्री चन्द्रेश्वरी नैमिष प्यारा॥', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'धूमा, बगला, भैरवी, तारा।भुवनेश्वरी, कमला, विस्तारा॥', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'षोडशी, छिन्न्मस्ता, मातंगी।ललितेशक्ति तुम्हारी संगी॥', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'ललिते तुम हो ज्योतित भाला।भक्त जनों का काम संभाला॥', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'भारी संकट जब-जब आये।उनसे तुमने भक्त बचाए॥', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'जिसने कृपा तुम्हारी पायी।उसकी सब विधि से बन आयी॥', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'संकट दूर करो माँ भारी।भक्त जनों को आस तुम्हारी॥', transliteration: ''),
    LyricStanza(startTimeMs: 390000, devanagari: 'त्रिपुरेश्वरी, शैलजा, भवानी।जय जय जय शिव की महारानी॥', transliteration: ''),
    LyricStanza(startTimeMs: 420000, devanagari: 'योग सिद्दि पावें सब योगी।भोगें भोग महा सुख भोगी॥', transliteration: ''),
    LyricStanza(startTimeMs: 450000, devanagari: 'कृपा तुम्हारी पाके माता।जीवन सुखमय है बन जाता॥', transliteration: ''),
    LyricStanza(startTimeMs: 480000, devanagari: 'दुखियों को तुमने अपनाया।महा मूढ़ जो शरण न आया॥', transliteration: ''),
    LyricStanza(startTimeMs: 510000, devanagari: 'तुमने जिसकी ओर निहारा।मिली उसे सम्पत्ति, सुख सारा॥', transliteration: ''),
    LyricStanza(startTimeMs: 540000, devanagari: 'आदि शक्ति जय त्रिपुर प्यारी।महाशक्ति जय जय, भय हारी॥', transliteration: ''),
    LyricStanza(startTimeMs: 570000, devanagari: 'कुल योगिनी, कुण्डलिनी रूपा।लीला ललिते करें अनूपा॥', transliteration: ''),
    LyricStanza(startTimeMs: 600000, devanagari: 'महा-महेश्वरी, महा शक्ति दे।त्रिपुर-सुन्दरी सदा भक्ति दे॥', transliteration: ''),
    LyricStanza(startTimeMs: 630000, devanagari: 'महा महा-नन्दे कल्याणी।मूकों को देती हो वाणी॥', transliteration: ''),
    LyricStanza(startTimeMs: 660000, devanagari: 'इच्छा-ज्ञान-क्रिया का भागी।होता तब सेवा अनुरागी॥', transliteration: ''),
