    LyricStanza(startTimeMs: 780000, devanagari: 'नामा कर्षिणी, चिन्ता कर्षिणी।सर्व मोहिनी सब सुख-वर्षिणी॥', transliteration: ''),
    LyricStanza(startTimeMs: 810000, devanagari: 'महिमा तव सब जग विख्याता।तुम हो दयामयी जग माता॥', transliteration: ''),
