    LyricStanza(startTimeMs: 990000, devanagari: 'छः चक्रों को भेदने वाली।करती हो सबकी रखवाली॥', transliteration: ''),
    LyricStanza(startTimeMs: 1020000, devanagari: 'योगी, भोगी, क्रोधी, कामी।सब हैं सेवक सब अनुगामी॥', transliteration: ''),
    LyricStanza(startTimeMs: 1050000, devanagari: 'सबको पार लगाती हो माँ।सब पर दया दिखाती हो माँ॥', transliteration: ''),
    LyricStanza(startTimeMs: 1080000, devanagari: 'हेमावती, उमा, ब्रह्माणी।भण्डासुर कि हृदय विदारिणी॥', transliteration: ''),
