    LyricStanza(startTimeMs: 120000, devanagari: 'अपरिज्ञाननष्टेषु मन्त्रेष्वव्रतयोगिषु ।\nतिरोहितार्थदैवेषु कृष्ण एव गतिर्मम ॥ ५॥', transliteration: ''),
