    LyricStanza(startTimeMs: 450000, devanagari: 'हो..मंगलकारी तुं महामाया, मोमाई माँ शरणम् ममः\nसुख नी सदा देती छाया, मोमाई माँ शरणम् ममः', transliteration: ''),
    LyricStanza(startTimeMs: 480000, devanagari: 'हो..नबळा ग्रहो ने बळवान करती, मोमाई माँ शरणम् ममः\nपरगट परचा एवा पुरती, मोमाई माँ शरणम् ममः', transliteration: ''),
    LyricStanza(startTimeMs: 510000, devanagari: 'हो..नमन करता माँ तने नर ने नारी, मोमाई माँ शरणम् ममः\nसुखदाता मां तुज ने जाणी, मोमाई माँ शरणम् ममः', transliteration: ''),
