    LyricStanza(startTimeMs: 570000, devanagari: 'हो..महाशक्ति तुं महामाया, मोमाई माँ शरणम् ममः\nचरणे मळे सुख नी छाया, मोमाई माँ शरणम् ममः', transliteration: ''),
