    LyricStanza(startTimeMs: 630000, devanagari: 'हो..मूर्ति तारी मंगलकारी, मोमाई माँ शरणम् ममः\nअमीयल नजरु न्यारी तारी, मोमाई माँ शरणम् ममः', transliteration: ''),
    LyricStanza(startTimeMs: 660000, devanagari: 'हो..तुं दयाळु माँ परम कृपाळु, मोमाई माँ शरणम् ममः\nतारु नाम दुःख हरनारु, मोमाई माँ शरणम् ममः', transliteration: ''),
    LyricStanza(startTimeMs: 690000, devanagari: 'हो..त्रिभुवन तारणहार माता, मोमाई माँ शरणम् ममः\nभक्ति मुक्ति नी माँ दाता, मोमाई माँ शरणम् ममः', transliteration: ''),
    LyricStanza(startTimeMs: 720000, devanagari: 'हो..भोळी भवानी तुं भगवती, मोमाई माँ शरणम् ममः\nदर्शन देजो माँ जगजननी, मोमाई माँ शरणम् ममः', transliteration: ''),
    LyricStanza(startTimeMs: 750000, devanagari: 'हो..जेवो छुं हुं तमारो बाळ, मोमाई माँ शरणम् ममः\nलेजो माडी शरणे मात, मोमाई माँ शरणम् ममः', transliteration: ''),
