    LyricStanza(startTimeMs: 810000, devanagari: 'हो..विश्वंभरी अखिलेश्वरी माता, मोमाई माँ शरणम् ममः\nजगजननी मुक्ति फळदाता, मोमाई माँ शरणम् ममः', transliteration: ''),
    LyricStanza(startTimeMs: 840000, devanagari: 'हो..गौ गंगा गायत्री गीता, मोमाई माँ शरणम् ममः\nपरापरमेश्वरी पुनीता, मोमाई माँ शरणम् ममः', transliteration: ''),
    LyricStanza(startTimeMs: 870000, devanagari: 'हो..भय क्लेश मां तमे मटाडो, मोमाई माँ शरणम् ममः\nदारुण दुःख थी अमने उगारो, मोमाई माँ शरणम् ममः', transliteration: ''),
    LyricStanza(startTimeMs: 900000, devanagari: 'हो..रिद्धि सिद्धि नी तुं सुखदाता, मोमाई माँ शरणम् ममः\nमनवांछित फळ माँ देता, मोमाई माँ शरणम् ममः', transliteration: ''),
    LyricStanza(startTimeMs: 930000, devanagari: 'हो..नेह नीतरती आंखळी तारी, मोमाई माँ शरणम् ममः\nबगडेली बाजी सुधारो माडी, मोमाई माँ शरणम् ममः', transliteration: ''),
    LyricStanza(startTimeMs: 960000, devanagari: 'हो..अभयदाईनी तुं छे माता, मोमाई माँ शरणम् ममः\nसौ जीवो नी तुं सुखदाता, मोमाई माँ शरणम् ममः', transliteration: ''),
