    LyricStanza(startTimeMs: 1020000, devanagari: 'हो..कर जोडी राजेश बोले, मोमाई माँ शरणम् ममः\nफूलडे वधावता मेश्वा बोले, मोमाई माँ शरणम् ममः', transliteration: ''),
