    LyricStanza(startTimeMs: 1080000, devanagari: 'हो..मोमाई माँ शरणम् ममः, मोमाई माँ शरणम् ममः\nमोरगढ नी माँ देवी दयाळु, मोमाई माँ शरणम् ममः', transliteration: ''),
    LyricStanza(startTimeMs: 1110000, devanagari: 'हो..मोमाई माँ शरणम् ममः, मोमाई माँ शरणम् ममः\nमोरगढ नी माँ देवी दयाळु, मोमाई माँ शरणम् ममः\nबोल श्री मोमाई मात नी जय', transliteration: ''),
