  'L-t1V35G-HY': [
    LyricStanza(startTimeMs: 0, devanagari: 'जय केदार उदार शंकर,\nमन भयंकर दुख हरम्।\nगौरी गणपति स्कन्द नन्दी,\nश्री केदार नमाम्यहम्॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'शैल सुन्दर अति हिमालय,\nशुभ्र मन्दिर सुन्दरम्।\nनिकट मंदाकिनी सरस्वती,\nजय केदार नमाम्यहम्॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'उदक कुण्ड है अधम पावन,\nरेतस कुण्ड मनोहरम्।\nहंस कुंड समीप सुन्दर,\nजै केदार नमाम्यहम्॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'अन्नपूर्णा सह अपर्णा,\nकाल भैरव शोभितम्।\nपांच पांडव द्रोपदी सह,\nजय केदार नमाम्यहम्॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'शिव दिगम्बर भस्मधारी,\nअर्द्ध चन्द्र विभूषितम्।\nशीश गंगा कंठ फणिपति,\nजै केदार नमाम्यहम्॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'कर त्रिशूल विशाल डमरू,\nज्ञान गान विशारदम्।\nमध्य महेश्वर तुंग ईश्वर,\nरुद्र कल्प महेश्वरम्॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'पंच धन्य विशाल आलय,\nजै केदार नमाम्यहम्।\nनाथ पावन हे विशालम्,\nपुण्यप्रद हर दर्शनम्॥', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'जय केदार उदार शंकर,\nपाप ताप नमाम्यहम्॥', transliteration: ''),
  ],
  'M7oL2YrT7YI': [
    LyricStanza(startTimeMs: 0, devanagari: 'श्रीलक्ष्मीनृसिंहकरुणारस अथवा करावलम्बस्तोत्रम्\nश्रीमत्पयोनिधिनिकेतनचक्रपाणे\nभोगीन्द्रभोगमणिराजितपुण्यमूर्ते ।\nयोगीश शाश्वत शरण्य भवाब्धिपोत\nलक्ष्मीनृसिंह मम देहि करावलम्बम् ॥ १॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'ब्रह्मेन्द्ररुद्रमरुदर्ककिरीटकोटि-\nसङ्घट्टिताङ्घ्रिकमलामलकान्तिकान्त ।\nलक्ष्मीलसत्कुचसरोरुहराजहंस\nलक्ष्मीनृसिंह मम देहि करावलम्बम् ॥ २॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'संसारघोरगहने चरतो मुरारे\nमारोग्रभीकरमृगप्रचुरार्दितस्य ।\nआर्तस्य मत्सरनिदाघसुदुःखितस्य\nलक्ष्मीनृसिंह मम देहि करावलम्बम् ॥ ३॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'संसारकूपमतिघोरमगाधमूलं\nसम्प्राप्य दुःखशतसर्पसमाकुलस्य ।\nदीनस्य देव कृपया पदमागतस्य\nलक्ष्मीनृसिंह मम देहि करावलम्बम् ॥ ४॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'संसारसागरविशालकरालकाल-\nनक्रग्रहग्रसितनिग्रहविग्रहस्य ।\nव्यग्रस्य रागनिचयोर्मिनिपीडितस्य\nलक्ष्मीनृसिंह मम देहि करावलम्बम् ॥ ५॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'संसारवृक्षमघबीजमनन्तकर्म-\nशाखायुतं करणपत्रमनङ्गपुष्पम् ।\nआरुह्य दुःखफलितं चकितं दयालो\nलक्ष्मीनृसिंह मम देहि करावलम्बम् ॥ ६॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'संसारसर्पविषदिग्धमहोग्रतीव्र-\nदंष्ट्राग्रकोटिपरिदष्टविनष्टमूर्तेः ।\nनागारिवाहन सुधाब्धिनिवास शौरे\nलक्ष्मीनृसिंह मम देहि करावलम्बम् ॥ ७॥', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'संसारदावदहनाकरभीकरोग्र-\nज्वालावलीभिरतिदग्धतनूरुहस्य ।\nत्वत्पादपद्मसरसीरुहमागतस्य\nलक्ष्मीनृसिंह मम देहि करावलम्बम् ॥ ८॥', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'संसारजालपतितस्य जगन्निवास\nसर्वेन्द्रियार्थबडिशाग्रझषोपमस्य ।\nप्रोत्कम्पितप्रचुरतालुकमस्तकस्य\nलक्ष्मीनृसिंह मम देहि करावलम्बम् ॥ ९॥', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'संसारभीकरकरीन्द्रकराभिघात-\nनिष्पीड्यमानवपुषः सकलार्तिनाश ।\nप्राणप्रयाणभवभीतिसमाकुलस्य\nलक्ष्मीनृसिंह मम देहि करावलम्बम् ॥ १०॥', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'अन्धस्य मे हृतविवेकमहाधनस्य\nचोरैर्महाबलिभिरिन्द्रियनामधेयैः ।\nमोहान्धकारकुहरे विनिपातितस्य\nलक्ष्मीनृसिंह मम देहि करावलम्बम् ॥ ११॥', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'लक्ष्मीपते कमलनाभ सुरेश विष्णो\nवैकुण्ठ कृष्ण मधुसूदन पुष्कराक्ष ।\nब्रह्मण्य केशव जनार्दन वासुदेव\nदेवेश देहि कृपणस्य करावलम्बम् ॥ १२॥', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'यन्माययार्जितवपुःप्रचुरप्रवाह-\nमग्नार्थमत्र निवहोरुकरावलम्बम् ।\nलक्ष्मीनृसिंहचरणाब्जमधुव्रतेन\nस्तोत्रं कृतं सुखकरं भुवि शङ्करेण ॥ १३॥', transliteration: ''),
  ],
  'NHBJn0KxWbU': [
    LyricStanza(startTimeMs: 0, devanagari: '॥ श्रीशिवपञ्चाक्षरस्तोत्रम् ॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'नागेन्द्रहाराय त्रिलोचनाय,\nभस्माङ्गरागाय महेश्वराय ।\nनित्याय शुद्धाय दिगम्बराय,\nतस्मै न काराय नमः शिवाय ॥१॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'मन्दाकिनी सलिलचन्दन चर्चिताय,\nनन्दीश्वर प्रमथनाथ महेश्वराय ।\nमन्दारपुष्प बहुपुष्प सुपूजिताय,\nतस्मै म काराय नमः शिवाय ॥२॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'शिवाय गौरीवदनाब्जवृन्द,\nसूर्याय दक्षाध्वरनाशकाय ।\nश्रीनीलकण्ठाय वृषध्वजाय,\nतस्मै शि काराय नमः शिवाय ॥३॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'वसिष्ठकुम्भोद्भवगौतमार्य,\nमुनीन्द्रदेवार्चितशेखराय।\nचन्द्रार्क वैश्वानरलोचनाय,\nतस्मै व काराय नमः शिवाय ॥४॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'यज्ञस्वरूपाय जटाधराय,\nपिनाकहस्ताय सनातनाय ।\nदिव्याय देवाय दिगम्बराय,\nतस्मै य काराय नमः शिवाय ॥५॥', transliteration: ''),
  ],
  'NIV3Zy16Ffw': [
    LyricStanza(startTimeMs: 0, devanagari: 'पितु मातु सहायक स्वामी सखा,\nतुम ही एक नाथ हमारे हो।', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'जिनके कुछ और आधार नहीं,\nतिनके तुम ही रखवारे हो।', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'सब भाँति सदा सुखदायक हो,\nदुःख निर्गुण नाशन हारे हो।', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'प्रतिपाल करो सिगरे जग को,\nअतिशय करुणा उर धारे हो।', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'भुलि हैं हम तो तुमको,\nतुम तो हमरी सुधि नाहिं बिसारे हो।', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'उपकारन को कछु अन्त नहीं,\nछिन ही छिन जो विस्तारे हो।', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'महाराज महा महिमा तुम्हरी,\nमुझसे बिरले बुधवारे हो।', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'शुभ शान्ति निकेतन प्रेमनिधि,\nमन मन्दिर के उजियारे हो।', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'इस जीवन के तुम जीवन हो,\nइन प्राणन के तुम प्यारे हो।', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'तुम सों प्रभु पाय ‘प्रताप’ हरि,\nकेहि के अब और सहारे हो।', transliteration: ''),
  ],
  'Q2ag5XCZVyc': [
    LyricStanza(startTimeMs: 0, devanagari: 'बंशी शोभित कर मधुर, नील जलद तन श्याम।\nअरुण अधर जनु बिम्बा फल, पिताम्बर शुभ साज॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'जय मनमोहन मदन छवि, कृष्णचन्द्र महाराज।\nकरहु कृपा हे रवि तनय, राखहु जन की लाज॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'जय यदुनन्दन जय जगवन्दन।\nजय वसुदेव देवकी नन्दन॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'जय यशुदा सुत नन्द दुलारे।\nजय प्रभु भक्तन के दृग तारे॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'जय नट-नागर नाग नथैया।\nकृष्ण कन्हैया धेनु चरैया॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'पुनि नख पर प्रभु गिरिवर धारो।\nआओ दीनन कष्ट निवारो॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'वंशी मधुर अधर धरी तेरी।\nहोवे पूर्ण मनोरथ मेरो॥', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'आओ हरि पुनि माखन चाखो।\nआज लाज भारत की राखो॥', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'गोल कपोल, चिबुक अरुणारे।\nमृदु मुस्कान मोहिनी डारे॥', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'रंजित राजिव नयन विशाला।\nमोर मुकुट वैजयंती माला॥', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'कुण्डल श्रवण पीतपट आछे।\nकटि किंकणी काछन काछे॥', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'नील जलज सुन्दर तनु सोहे।\nछवि लखि, सुर नर मुनिमन मोहे॥', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'मस्तक तिलक, अलक घुंघराले।\nआओ कृष्ण बाँसुरी वाले॥', transliteration: ''),
    LyricStanza(startTimeMs: 390000, devanagari: 'करि पय पान, पुतनहि तारयो।\nअका बका कागासुर मारयो॥', transliteration: ''),
    LyricStanza(startTimeMs: 420000, devanagari: 'मधुवन जलत अग्नि जब ज्वाला।\nभै शीतल, लखितहिं नन्दलाला॥', transliteration: ''),
    LyricStanza(startTimeMs: 450000, devanagari: 'सुरपति जब ब्रज चढ़यो रिसाई।\nमसूर धार वारि वर्षाई॥', transliteration: ''),
    LyricStanza(startTimeMs: 480000, devanagari: 'लगत-लगत ब्रज चहन बहायो।\nगोवर्धन नखधारि बचायो॥', transliteration: ''),
    LyricStanza(startTimeMs: 510000, devanagari: 'लखि यसुदा मन भ्रम अधिकाई।\nमुख महं चौदह भुवन दिखाई॥', transliteration: ''),
    LyricStanza(startTimeMs: 540000, devanagari: 'दुष्ट कंस अति उधम मचायो।\nकोटि कमल जब फूल मंगायो॥', transliteration: ''),
    LyricStanza(startTimeMs: 570000, devanagari: 'नाथि कालियहिं तब तुम लीन्हें।\nचरणचिन्ह दै निर्भय किन्हें॥', transliteration: ''),
    LyricStanza(startTimeMs: 600000, devanagari: 'करि गोपिन संग रास विलासा।\nसबकी पूरण करी अभिलाषा॥', transliteration: ''),
    LyricStanza(startTimeMs: 630000, devanagari: 'केतिक महा असुर संहारयो।\nकंसहि केस पकड़ि दै मारयो॥', transliteration: ''),
    LyricStanza(startTimeMs: 660000, devanagari: 'मात-पिता की बन्दि छुड़ाई।\nउग्रसेन कहं राज दिलाई॥', transliteration: ''),
    LyricStanza(startTimeMs: 690000, devanagari: 'महि से मृतक छहों सुत लायो।\nमातु देवकी शोक मिटायो॥', transliteration: ''),
    LyricStanza(startTimeMs: 720000, devanagari: 'भौमासुर मुर दैत्य संहारी।\nलाये षट दश सहसकुमारी॥', transliteration: ''),
    LyricStanza(startTimeMs: 750000, devanagari: 'दै भिन्हीं तृण चीर सहारा।\nजरासिंधु राक्षस कहं मारा॥', transliteration: ''),
    LyricStanza(startTimeMs: 780000, devanagari: 'असुर बकासुर आदिक मारयो।\nभक्तन के तब कष्ट निवारियो॥', transliteration: ''),
    LyricStanza(startTimeMs: 810000, devanagari: 'दीन सुदामा के दुःख टारयो।\nतंदुल तीन मूंठ मुख डारयो॥', transliteration: ''),
    LyricStanza(startTimeMs: 840000, devanagari: 'प्रेम के साग विदुर घर मांगे।\nदुर्योधन के मेवा त्यागे॥', transliteration: ''),
    LyricStanza(startTimeMs: 870000, devanagari: 'लखि प्रेम की महिमा भारी।\nऐसे श्याम दीन हितकारी॥', transliteration: ''),
    LyricStanza(startTimeMs: 900000, devanagari: 'भारत के पारथ रथ हांके।\nलिए चक्र कर नहिं बल ताके॥', transliteration: ''),
    LyricStanza(startTimeMs: 930000, devanagari: 'निज गीता के ज्ञान सुनाये।\nभक्तन हृदय सुधा वर्षाये॥', transliteration: ''),
    LyricStanza(startTimeMs: 960000, devanagari: 'मीरा थी ऐसी मतवाली।\nविष पी गई बजाकर ताली॥', transliteration: ''),
    LyricStanza(startTimeMs: 990000, devanagari: 'राना भेजा सांप पिटारी।\nशालिग्राम बने बनवारी॥', transliteration: ''),
    LyricStanza(startTimeMs: 1020000, devanagari: 'निज माया तुम विधिहिं दिखायो।\nउर ते संशय सकल मिटायो॥', transliteration: ''),
    LyricStanza(startTimeMs: 1050000, devanagari: 'तब शत निन्दा करी तत्काला।\nजीवन मुक्त भयो शिशुपाला॥', transliteration: ''),
    LyricStanza(startTimeMs: 1080000, devanagari: 'जबहिं द्रौपदी टेर लगाई।\nदीनानाथ लाज अब जाई॥', transliteration: ''),
    LyricStanza(startTimeMs: 1110000, devanagari: 'तुरतहिं वसन बने नन्दलाला।\nबढ़े चीर भै अरि मुँह काला॥', transliteration: ''),
    LyricStanza(startTimeMs: 1140000, devanagari: 'अस नाथ के नाथ कन्हैया।\nडूबत भंवर बचावत नैया॥', transliteration: ''),
    LyricStanza(startTimeMs: 1170000, devanagari: 'सुन्दरदास आस उर धारी।\nदयादृष्टि कीजै बनवारी॥', transliteration: ''),
    LyricStanza(startTimeMs: 1200000, devanagari: 'नाथ सकल मम कुमति निवारो।\nक्षमहु बेगि अपराध हमारो॥', transliteration: ''),
    LyricStanza(startTimeMs: 1230000, devanagari: 'खोलो पट अब दर्शन दीजै।\nबोलो कृष्ण कन्हैया की जै॥', transliteration: ''),
    LyricStanza(startTimeMs: 1260000, devanagari: 'यह चालीसा कृष्ण का, पाठ करै उर धारि।\nअष्ट सिद्धि नवनिधि फल, लहै पदारथ चारि॥', transliteration: ''),
  ],
  'QgkBIoUeAa0': [
    LyricStanza(startTimeMs: 0, devanagari: 'सौराष्ट्रदेशे विश् अदेऽतिरम्ये ज्योतिर्मयं चन्द्रकलावतंसम् ।\nभक्तिप्रदानाय कृपावतीर्णं तं सोमनाथं शरणं प्रपद्ये ॥ १॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'श्रीशैलश‍ृङ्गे विबुधातिसङ्गे तुलाद्रितुङ्गेऽपि मुदा वसन्तम् ।\nतमर्जुनं मल्लिकपूर्वमेकं नमामि संसारसमुद्रसेतुम् ॥ २॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'अवन्तिकायां विहितावतारं मुक्तिप्रदानाय च सज्जनानाम् ।\nअकालमृत्योः परिरक्षणार्थं वन्दे महाकालमहासुरेशम् ॥ ३॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'कावेरिकानर्मदयोः पवित्रे समागमे सज्जनतारणाय ।\nसदैव मान्धातृपुरे वसन्तं ओङ्कारमीशं शिवमेकमीडे ॥ ४॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'पूर्वोत्तरे प्रज्वलिकानिधाने सदाशिवं तं गिरिजासमेतम् ।\nसुरासुराराधितपादपद्मं श्रीवैद्यनाथं तमहं नमामि ॥ ५॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'याम्ये सदङ्गे नगरेऽतिरम्ये विभूषिताङ्गं विविधैश्च भोगैः ।\nसद्भुक्तिमुक्तिप्रदमीशमेकं श्रीनागनाथं शरणं प्रपद्ये ॥ ६॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'महाद्रिपार्श्वे च तटे रमन्तं सम्पूज्यमानं सततं मुनीन्द्रैः ।\nसुरासुरैर्यक्ष महोरगाढ्यैः केदारमीशं शिवमेकमीडे ॥ ७॥', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'सह्याद्रिशीर्षे विमले वसन्तं गोदावरितीरपवित्रदेशे ।\nयद्धर्शनात्पातकमाशु नाशं प्रयाति तं त्र्यम्बकमीशमीडे ॥ ८॥', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'सुताम्रपर्णीजलराशियोगे निबध्य सेतुं विशिखैरसङ्ख्यैः ।\nश्रीरामचन्द्रेण समर्पितं तं रामेश्वराख्यं नियतं नमामि ॥ ९॥', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'यं डाकिनिशाकिनिकासमाजे निषेव्यमाणं पिशिताशनैश्च ।\nसदैव भीमादिपदप्रसिद्धं तं शङ्करं भक्तहितं नमामि ॥ १०॥', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'सानन्दमानन्दवने वसन्तमानन्दकन्दं हतपापवृन्दम् ।\nवाराणसीनाथमनाथनाथं श्रीविश्वनाथं शरणं प्रपद्ये ॥ ११॥', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'इलापुरे रम्यविशालकेऽस्मिन् समुल्लसन्तं च जगद्वरेण्यम् ।\nवन्दे महोदारतरस्वभावं घृष्णेश्वराख्यं शरणम् प्रपद्ये ॥ १२॥', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'ज्योतिर्मयद्वादशलिङ्गकानां शिवात्मनां प्रोक्तमिदं क्रमेण ।\nस्तोत्रं पठित्वा मनुजोऽतिभक्त्या फलं तदालोक्य निजं भजेच्च ॥', transliteration: ''),
    LyricStanza(startTimeMs: 390000, devanagari: '(एतानि लिङ्गानि सदैव मर्त्याः प्रातः पठन्तोऽमलमानसाश्च ।\nते पुत्रपौत्रैश्च धनैरुदारैः सत्कीर्ति भाजः सुखिनो भवन्ति ॥)\n॥ इति श्रीमद्शङ्कराचार्यविरचितं\nद्वादशज्योतिर्लिङ्गस्तोत्रं सम्पूर्णम् ॥', transliteration: ''),
  ],
  'Qi23pxtWc1A': [
    LyricStanza(startTimeMs: 0, devanagari: 'जै जै जै यमुना महारानी।\nजय कालिन्दि कृष्ण पटरानी।।', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'रूप अनूप शोभा छवि न्यारी।\nमाधव-प्रिया ब्रज शोभा भारी।।', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'भुवन बसी घोर तप कीन्हा।\nपूर्ण मनोरथ मुरारी कीन्हा।।', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'निज अर्धांगी तुम्ही अपनायों।\nसावँरो श्याम पति प्रिय पायो।।', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'रूप अलौकिक अद्भूत ज्योति।\nनीर रेणू दमकत ज्यूँ मोती।।', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'सूर्यसुता श्यामल सब अंगा।\nकोटिचन्द्र ध्युति कान्ति अभंगा।।', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'आश्रय ब्रजाधिश्वर लीन्हा।\nगोकुल बसी शुचि भक्तन कीन्हा।।', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'कृष्ण नन्द घर गोकुल आयों।\nचरण वन्दि करि दर्शन पायों।।', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'सोलह श्रृंगार भुज कंकण सोहे।\nकोटि काम लाजहि मन मोहें।।', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'कृष्णवेश नथ मोती राजत।\nनुपूर घुंघरू चरण में बाजत।।', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'मणि माणक मुक्ता छवि नीकी।\nमोहनी रूप सब उपमा फिकी।।', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'मन्द चलहि प्रिय-प्रीतम प्यारी।\nरीझहि श्याम प्रिय प्रिया निहारी।।', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'मोहन बस करि हृदय विराजत।\nबिनु प्रीतम क्षण चैन न पावत।।', transliteration: ''),
    LyricStanza(startTimeMs: 390000, devanagari: 'मुरलीधर जब मुरली बजावैं।\nसंग केलि कर आनन्द पावैं।।', transliteration: ''),
    LyricStanza(startTimeMs: 420000, devanagari: 'मोर हंस कोकिल नित खेलत।\nजलखग कूजत मृदुबानी बोलत।।', transliteration: ''),
    LyricStanza(startTimeMs: 450000, devanagari: 'जा पर कृपा दृष्टि बरसावें।\nप्रेम को भेद सोई जन पावें।।', transliteration: ''),
    LyricStanza(startTimeMs: 480000, devanagari: 'नाम यमुना जब मुख पे आवें।\nसबहि अमगंल देखि टरि जावें।।', transliteration: ''),
    LyricStanza(startTimeMs: 510000, devanagari: 'भजे नाम यमुना अमृत रस।\nरहे साँवरो सदा ताहि बस।।', transliteration: ''),
    LyricStanza(startTimeMs: 540000, devanagari: 'करूणामयी सकल रसखानि।\nसुर नर मुनि बंदहि सब ज्ञानी।।', transliteration: ''),
    LyricStanza(startTimeMs: 570000, devanagari: 'भूतल प्रकटी अवतार जब लीन्हो।\nउध्दार सभी भक्तन को किन्हो।।', transliteration: ''),
    LyricStanza(startTimeMs: 600000, devanagari: 'शेष गिरा श्रुति पार न पावत।\nयोगी जति मुनी ध्यान लगावत।।', transliteration: ''),
    LyricStanza(startTimeMs: 630000, devanagari: 'दंड प्रणाम जे आचमन करहि।\nनासहि अघ भवसिंधु तरहि।।', transliteration: ''),
    LyricStanza(startTimeMs: 660000, devanagari: 'भाव भक्ति से नीर न्हावें।\nदेव सकल तेहि भाग्य सरावें।।', transliteration: ''),
    LyricStanza(startTimeMs: 690000, devanagari: 'करि ब्रज वास निरंतर ध्यावहि।\nपरमानंद परम पद पावहि।।', transliteration: ''),
    LyricStanza(startTimeMs: 720000, devanagari: 'संत मुनिजन मज्जन करहि।\nनव भक्तिरस निज उर भरहि।।', transliteration: ''),
    LyricStanza(startTimeMs: 750000, devanagari: 'पूजा नेम चरण अनुरागी।\nहोई अनुग्रह दरश बड़भागी।।', transliteration: ''),
    LyricStanza(startTimeMs: 780000, devanagari: 'दीपदान करि आरती करहि।\nअन्तर सुख मन निर्मल रहहि।।', transliteration: ''),
    LyricStanza(startTimeMs: 810000, devanagari: 'कीरति विशद विनय करी गावत।\nसिध्दि अलौकिक भक्ति पावत।।', transliteration: ''),
    LyricStanza(startTimeMs: 840000, devanagari: 'बड़े प्रेम श्रीयमुना पद गावें।\nमोहन सन्मुख सुनन को आवें।।', transliteration: ''),
    LyricStanza(startTimeMs: 870000, devanagari: 'आतुर होय शरणागत आवें।\nकृपाकरी ताहि बेगि अपनावें।।', transliteration: ''),
    LyricStanza(startTimeMs: 900000, devanagari: 'ममतामयी सब जानहि मन की।\nभव पीड़ा हरहि निज जन की।।', transliteration: ''),
    LyricStanza(startTimeMs: 930000, devanagari: 'शरण प्रतिपाल प्रिय कुंजेश्वरी।\nब्रज उपमा प्रीतम प्राणेश्वरी।।', transliteration: ''),
    LyricStanza(startTimeMs: 960000, devanagari: 'श्रीजी यमुना कृपा जब होई।\nब्रह्म सम्बन्ध जीव को होई।।', transliteration: ''),
    LyricStanza(startTimeMs: 990000, devanagari: 'पुष्टिमार्गी नित महिमा गावैं।\nकृष्ण चरण नित भक्ति दृढावैं।।', transliteration: ''),
    LyricStanza(startTimeMs: 1020000, devanagari: 'नमो नमो श्री यमुने महारानी।\nनमो नमो श्रीपति पटरानी।।', transliteration: ''),
    LyricStanza(startTimeMs: 1050000, devanagari: 'नमो नमो यमुने सुख करनी।\nनमो नमो यमुने दु:ख हरनी।।', transliteration: ''),
    LyricStanza(startTimeMs: 1080000, devanagari: 'नमो कृष्णायैं सकल गुणखानी।\nश्रीहरिप्रिया निकुंज निवासिनी।।', transliteration: ''),
    LyricStanza(startTimeMs: 1110000, devanagari: 'करूणामयी अब कृपा कीजैं।\nफदंकाटी मोहि शरण मे लीजैं।।', transliteration: ''),
    LyricStanza(startTimeMs: 1140000, devanagari: 'जो यमुना चालिसा नित गावैं।\nकृपा प्रसाद ते सब सुख पावैं।।', transliteration: ''),
    LyricStanza(startTimeMs: 1170000, devanagari: 'ज्ञान भक्ति धन कीर्ति पावहि।\nअंत समय श्रीधाम ते जावहि।।', transliteration: ''),
  ],
  'RFYwdmaxE4U': [
    LyricStanza(startTimeMs: 0, devanagari: 'जय हरसिध्धी माता, ॐ जय हरसिध्धी माता,\nआरती गाता तमारी, हैया हरखाता,\nॐ जय हरसिध्धी माता', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'लाखो दिवडा जळहळ बळता,तेज तणो नहीं पार,\nमैया तेज तणो नहीं पार,\nदिव्य अलौकिक आभा, विजळीनो चमकार,\nॐ जय हरसिध्धी माता', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'मंगलकारी मुर्ति तमारी, मंदिरमां शोभे,\nमैया मंदिरमां शोभे,\nदर्शन करवा तमारा, मन सौनु लोभे,\nॐ जय हरसिध्धी माता', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'ढोल नगारा शरणायुंने, झालरनो झणकार,\nमैया झालरनो झणकार,\nमीठा सूर मोरलीना, करता एकाकार,\nॐ जय हरसिध्धी माता', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'अनेक रूपे एक तमे छो, परचा माँ पुरनार,\nमैया परचा माँ पुरनार,\nमहीमा तमारो मोटो, जगमां जय जयकार,\nॐ जय हरसिध्धी माता', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'सचराचरमां वास करो छो, माता ममताळी,\nमैया माता ममताळी,\nसमरे वेला आवो, करवा रखवाळी,\nॐ जय हरसिध्धी माता', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'भवसागरमां भटकेलाने, पलमां माँ तारे,\nमैया पलमां माँ तारे,\nपापी पावन थाता, माँ तारा घ्वारे,\nॐ जय हरसिध्धी माता', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'आदी अनादी मात तमे छो, वेदोमां वखणातां,\nमैया वेदोमां वखणातां,\nदेवो,दानव,मानव,गुण तारा गाता,\nॐ जय हरसिध्धी माता', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'अमी भरेली आंखोथी,माँ अमृत वरसावो,\nमैया अमृत वरसावो,\nसुना पडेला जीवनमां खुशीयो लहेरावो,\nॐ जय हरसिध्धी माता', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'फोरमता फुलडानो हुं तो, फुलगजरो लावुं,\nमैया फुलगजरो लावुं,\nहैयाना हेतेथी माँ तमने पहेरावुं,\nॐ जय हरसिध्धी माता', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'श्वासे श्वासे समरण करतो, अतुल तमारो दास,\nमैया अतुल तमारो दास,\nभक्तोने दर्शन आपो, पुरण करो माँ आश,\nॐ जय हरसिध्धी माता', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'जय हरसिध्धी माता, ॐ जय हरसिध्धी माता,\nआरती गाता तमारी, हैया हरखाता,\nॐ जय हरसिध्धी माता, ॐ जय हरसिध्धी माता,\nॐ जय हरसिध्धी माता, ॐ जय हरसिध्धी माता,', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'ॐ जय हरसिध्धी माता.\nबोलीए हरसिध्धी मातकी जय...', transliteration: ''),
  ],
  'R_HytySSO7g': [
    LyricStanza(startTimeMs: 0, devanagari: 'जय जय जय जाहर रणधीरा ।\nपर दुख भंजन बागड़ वीरा ॥१॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'गुरु गोरख का है वरदानी ।\nजाहरवीर जोधा लासानी ॥२॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'गौरवरण मुख महा विशाला ।\nमाथे मुकट घुंघराले बाला ॥३॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'कांधे धनुष गले तुलसी माला ।\nकमर कृपान रक्षा को डाला ॥४॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'जन्में गूगावीर जग जाना ।\nईसवी सन हजार दरमियाना ॥५॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'बल सागर गुण निधि कुमारा ।\nदुखी जनों का बना सहारा ॥६॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'बागड़ पति बाछला नन्दन ।\nजेवर सुत हरि भक्त निकन्दन ॥७॥', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'जेवर राव का पुत्र कहाये ।\nमाता पिता के नाम बढ़ाये ॥८॥', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'पूरन हुई कामना सारी ।\nजिसने विनती करी तुम्हारी ॥९॥', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'सन्त उबारे असुर संहारे ।\nभक्त जनों के काज संवारे ॥१०॥', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'गूगावीर की अजब कहानी ।\nजिसको ब्याही श्रीयल रानी ॥११॥', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'बाछल रानी जेवर राना ।\nमहादुःखी थे बिन सन्ताना ॥१२॥', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'भंगिन ने जब बोली मारी ।\nजीवन हो गया उनको भारी ॥१३॥', transliteration: ''),
    LyricStanza(startTimeMs: 390000, devanagari: 'सूखा बाग पड़ा नौलक्खा ।\nदेख-देख जग का मन दुक्खा ॥१४॥', transliteration: ''),
    LyricStanza(startTimeMs: 420000, devanagari: 'कुछ दिन पीछे साधू आये ।\nचेला चेली संग में लाये ॥१५॥', transliteration: ''),
    LyricStanza(startTimeMs: 450000, devanagari: 'जेवर राव ने कुआ बनवाया ।\nउद्घाटन जब करना चाहा ॥१६॥', transliteration: ''),
    LyricStanza(startTimeMs: 480000, devanagari: 'खारी नीर कुए से निकला ।\nराजा रानी का मन पिघला ॥१७॥', transliteration: ''),
    LyricStanza(startTimeMs: 510000, devanagari: 'रानी तब ज्योतिषी बुलवाया ।\nकौन पाप मैं पुत्र न पाया ॥१८॥', transliteration: ''),
    LyricStanza(startTimeMs: 540000, devanagari: 'कोई उपाय हमको बतलाओ ।\nउन कहा गोरख गुरु मनाओ ॥१९॥', transliteration: ''),
    LyricStanza(startTimeMs: 570000, devanagari: 'गुरु गोरख जो खुश हो जाई ।\nसन्तान पाना मुश्किल नाई ॥२०॥', transliteration: ''),
    LyricStanza(startTimeMs: 600000, devanagari: 'बाछल रानी गोरख गुन गावे ।\nनेम धर्म को न बिसरावे ॥२१॥', transliteration: ''),
    LyricStanza(startTimeMs: 630000, devanagari: 'करे तपस्या दिन और राती ।\nएक वक्त खाय रूखी चपाती ॥२२॥', transliteration: ''),
    LyricStanza(startTimeMs: 660000, devanagari: 'कार्तिक माघ में करे स्नाना ।\nव्रत इकादसी नहीं भुलाना ॥२३॥', transliteration: ''),
    LyricStanza(startTimeMs: 690000, devanagari: 'पूरनमासी व्रत नहीं छोड़े ।\nदान पुण्य से मुख नहीं मोड़े ॥२४॥', transliteration: ''),
    LyricStanza(startTimeMs: 720000, devanagari: 'चेलों के संग गोरख आये ।\nनौलखे में तम्बू तनवाये ॥२५॥', transliteration: ''),
    LyricStanza(startTimeMs: 750000, devanagari: 'मीठा नीर कुए का कीना ।\nसूखा बाग हरा कर दीना ॥२६॥', transliteration: ''),
    LyricStanza(startTimeMs: 780000, devanagari: 'मेवा फल सब साधु खाए ।\nअपने गुरु के गुन को गाये ॥२७॥', transliteration: ''),
    LyricStanza(startTimeMs: 810000, devanagari: 'औघड़ भिक्षा मांगने आए ।\nबाछल रानी ने दुख सुनाये ॥२८॥', transliteration: ''),
    LyricStanza(startTimeMs: 840000, devanagari: 'औघड़ जान लियो मन माहीं ।\nतप बल से कुछ मुश्किल नाहीं ॥२९॥', transliteration: ''),
    LyricStanza(startTimeMs: 870000, devanagari: 'रानी होवे मनसा पूरी ।\nगुरु शरण है बहुत जरूरी ॥३०॥', transliteration: ''),
    LyricStanza(startTimeMs: 900000, devanagari: 'बारह बरस जपा गुरु नामा ।\nतब गोरख ने मन में जाना ॥३१॥', transliteration: ''),
    LyricStanza(startTimeMs: 930000, devanagari: 'पुत्र देन की हामी भर ली ।\nपूरनमासी निश्चय कर ली ॥३२॥', transliteration: ''),
    LyricStanza(startTimeMs: 960000, devanagari: 'काछल कपटिन गजब गुजारा ।\nधोखा गुरु संग किया करारा ॥३३॥', transliteration: ''),
    LyricStanza(startTimeMs: 990000, devanagari: 'बाछल बनकर पुत्र पाया ।\nबहन का दरद जरा नहीं आया ॥३४॥', transliteration: ''),
    LyricStanza(startTimeMs: 1020000, devanagari: 'औघड़ गुरु को भेद बताया ।\nतब बाछल ने गूगल पाया ॥३५॥', transliteration: ''),
    LyricStanza(startTimeMs: 1050000, devanagari: 'कर परसादी दिया गूगल दाना ।\nअब तुम पुत्र जनो मरदाना ॥३६॥', transliteration: ''),
    LyricStanza(startTimeMs: 1080000, devanagari: 'लीली घोड़ी और पण्डतानी ।\nलूना दासी ने भी जानी ॥३७॥', transliteration: ''),
    LyricStanza(startTimeMs: 1110000, devanagari: 'रानी गूगल बाट के खाई ।\nसब बांझों को मिली दवाई ॥३८॥', transliteration: ''),
    LyricStanza(startTimeMs: 1140000, devanagari: 'नरसिंह पंडित लीला घोड़ा ।\nभज्जु कुतवाल जना रणधीरा ॥३९॥', transliteration: ''),
    LyricStanza(startTimeMs: 1170000, devanagari: 'रूप विकट धर सब ही डरावे ।\nजाहरवीर के मन को भावे ॥४०॥', transliteration: ''),
    LyricStanza(startTimeMs: 1200000, devanagari: 'भादों कृष्ण जब नौमी आई ।\nजेवरराव के बजी बधाई ॥४१॥', transliteration: ''),
    LyricStanza(startTimeMs: 1230000, devanagari: 'विवाह हुआ गूगा भये राना ।\nसंगलदीप में बने मेहमाना ॥४२॥', transliteration: ''),
    LyricStanza(startTimeMs: 1260000, devanagari: 'रानी श्रीयल संग परे फेरे ।\nजाहर राज बागड़ का करे ॥४३॥', transliteration: ''),
    LyricStanza(startTimeMs: 1290000, devanagari: 'अरजन सरजन काछल जने ।\nगूगा वीर से रहे वे तने ॥४४॥', transliteration: ''),
    LyricStanza(startTimeMs: 1320000, devanagari: 'दिल्ली गए लड़ने के काजा ।\nअनंग पाल चढ़े महाराजा ॥४५॥', transliteration: ''),
    LyricStanza(startTimeMs: 1350000, devanagari: 'उसने घेरी बागड़ सारी ।\nजाहरवीर न हिम्मत हारी ॥४६॥', transliteration: ''),
    LyricStanza(startTimeMs: 1380000, devanagari: 'अरजन सरजन जान से मारे ।\nअनंगपाल ने शस्त्र डारे ॥४७॥', transliteration: ''),
    LyricStanza(startTimeMs: 1410000, devanagari: 'चरण पकड़कर पिण्ड छुड़ाया ।\nसिंह भवन माड़ी बनवाया ॥४८॥', transliteration: ''),
    LyricStanza(startTimeMs: 1440000, devanagari: 'उसीमें गूगावीर समाये ।\nगोरख टीला धूनी रमाये ॥४९॥', transliteration: ''),
    LyricStanza(startTimeMs: 1470000, devanagari: 'पुण्य वान सेवक वहाँ आये ।\nतन मन धन से सेवा लाए ॥५०॥', transliteration: ''),
    LyricStanza(startTimeMs: 1500000, devanagari: 'मनसा पूरी उनकी होई ।\nगूगावीर को सुमरे जोई ॥५१॥', transliteration: ''),
    LyricStanza(startTimeMs: 1530000, devanagari: 'चालीस दिन पढ़े जाहर चालीसा ।\nसारे कष्ट हरे जगदीसा ॥५२॥', transliteration: ''),
    LyricStanza(startTimeMs: 1560000, devanagari: 'दूध पूत उन्हें दे विधाता ।\nकृपा करे गुरु गोरखनाथ ॥५३॥', transliteration: ''),
    LyricStanza(startTimeMs: 1590000, devanagari: '॥ इति श्री जाहरवीर चालीसा संपूर्णम् ॥', transliteration: ''),
  ],
  'SY8LfusHEwc': [
    LyricStanza(startTimeMs: 0, devanagari: 'उत्तिष्ठोत्तिष्ठ देवेश उत्तिष्ठ हृदयेशय ।\nउत्तिष्ठ त्वमुमास्वामिन् ब्रह्माण्डे मङ्गलं कुरु ॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'शान्ताकारं शिखरशयनं नीलकण्ठं सुरेशं\nविश्वाधारं स्फटिकसदृशं शुभ्रवर्णं शुभाङ्गम् ।\nगौरीकान्तं त्रितयनयनं योगिभिर्ध्यानगम्यं\nवन्दे शम्भुं भवभयहरं सर्वलोकैकनाथम् ॥', transliteration: ''),
