    LyricStanza(startTimeMs: 30000, devanagari: 'ॐ जय यमुना माता…\nपावन श्रीयमुना जल अगम बहै धारा ।\nजो जन शरण में आया कर दिया निस्तारा ।।', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'ॐ जय यमुना माता…\nजो जन प्रातः ही उठकर नित्य स्नान करे ।\nयम के त्रास न पावे जो नित्य ध्यान करे ।।', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'ॐ जय यमुना माता…\nकलिकाल में महिमा तुम्हारी अटल रही ।\nतुम्हारा बड़ा महातम चारो वेद कही ।।', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'ॐ जय यमुना माता…\nआन तुम्हारे माता प्रभु अवतार लियो ।\nनित्य निर्मल जल पीकर कंस को मार दियो ।।', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'ॐ जय यमुना माता…\nनमो मात भय हरणी शुभ मंगल करणी ।\nमन बेचैन भया हैं तुम बिन वैतरणी ।।\nॐ जय यमुना माता…', transliteration: ''),
