    LyricStanza(startTimeMs: 90000, devanagari: 'ढोल नगारा शरणायुंने, झालरनो झणकार,\nमैया झालरनो झणकार,\nमीठा सूर मोरलीना, करता एकाकार,\nॐ जय मेलडी माता', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'अनेक रूपे एक तमे छो, परचा माँ पुरनार,\nमैया परचा माँ पुरनार,\nमहीमा तमारो मोटो, जगमां जय जयकार,\nॐ जय मेलडी माता', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'सचराचरमां वास करो छो, माता ममताळी,\nमैया माता ममताळी,\nसमरे वेला आवो, करवा रखवाळी,\nॐ जय मेलडी माता', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'भवसागरमां भटकेलाने, पलमां माँ तारे,\nमैया पलमां माँ तारे,\nपापी पावन थाता, माँ तारा घ्वारे,\nॐ जय मेलडी माता', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'आदी अनादी मात तमे छो, वेदोमां वखणातां,\nमैया वेदोमां वखणातां,\nदेवो,दानव,मानव,गुण तारा गाता,\nॐ जय मेलडी माता', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'अमी भरेली आंखोथी,माँ अमृत वरसावो,\nमैया अमृत वरसावो,\nसुना पडेला जीवनमां खुशीयो लहेरावो,\nॐ जय मेलडी माता', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'फोरमता फुलडानो हुं तो, फुलगजरो लावुं,\nमैया फुलगजरो लावुं,\nहैयाना हेतेथी माँ तमने पहेरावुं,\nॐ जय मेलडी माता', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'श्वासे श्वासे समरण करतो, अतुल तमारो दास,\nमैया अतुल तमारो दास,\nभक्तोने दर्शन आपो, पुरण करो माँ आश,\nॐ जय मेलडी माता', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'जय मेलडी माता, ॐ जय मेलडी माता,\nआरती गाता तमारी, हैया हरखाता,\nॐ जय मेलडी माता, ॐ जय मेलडी माता,\nॐ जय मेलडी माता, ॐ जय मेलडी माता,', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'ॐ जय मेलडी माता.\nबोलीए मेलडी मातकी जय...', transliteration: ''),
  ],
  'X5JXjHFTBcY': [
    LyricStanza(startTimeMs: 0, devanagari: 'यमुनाष्टकम् ३\n॥ श्रीगोपीजनवल्लभाय नमः॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'नमामि यमुनामहं सकलसिद्धिहेतुं मुदा\nमुरारिपदपङ्कजस्फुरदमन्दरेणूत्कटाम् ।\nतटस्थनवकाननप्रकटमोदपुष्पाम्बुना\nसुरासुरसुपूजितस्मरपितुः श्रियं बिभ्रतीम् ॥ १॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'कलिन्दगिरिमस्तके पतदमन्दपूरोज्ज्वला\nविलासगमनोल्लसत्प्रकटगण्डशैलोन्नता ।\nसघोषगतिदन्तुरा समधिरूढदोलोत्तमा\nमुकुन्दरतिवर्धिनी जयति पद्मबन्धोः सुता ॥ २॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'भुवं भुवनपावनीमधिगतामनेकस्वनैः\nप्रियाभिरिव सेवितां शुकमयूरहंसादिभिः ।\nतरङ्गभुजकङ्कणप्रकटमुक्तिकावालुका\nनितम्बतटसुन्दरीं नमत कृष्णतुर्यप्रियाम् ॥ ३॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'अनन्तगुण भूषिते शिवविरञ्चिदेवस्तुते\nघनाघननिभे सदा ध्रुवपराशराभीष्टदे ।\nविशुद्धमथुरातटे सकलगोपगोपीवृते\nकृपाजलधिसंश्रिते मम मनस्सुखं भावय ॥ ४॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'यया चरणपद्मजा मुररिपोः प्रियम्भावुका\nसमागमनतोऽभवत् सकलसिद्धिदा सेवताम् ।\nतया सदृशतामियात्कमलजा सपत्नीव य-\nद्धरिप्रियकलिन्दया मनसि मे सदा स्थीयताम् ॥ ५॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'नमोऽस्तु यमुने सदा तव चरित्रमत्यद्भुतं\nन जातु यमयातना भवति ते पयः पानतः ।\nयमोऽपि भगिनीसुतान्कथमु हन्ति दुष्टानपि\nप्रियो भवति सेवनात्तव हरेर्यथा गोपिकाः ॥ ६॥', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'ममाऽस्तु तव सन्निधौ तनुनवत्वमेतावता\nन दुर्लभतमा रतिर्मुररिपौ मुकुन्दप्रिये ।\nअतोऽस्तु तव लालना सुरधुनी परं सङ्गमा-\nत्तवैव भुवि कीर्तिता न तु कदापि पुष्टिस्थितैः ॥ ७॥', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'स्तुतिं तव करोति कः कमलजासपत्निप्रिये\nहरेर्यदनुसेवया भवति सौख्यमामोक्षतः ।\nइयं तव कथाऽधिका सकलगोपिकासङ्गमः ।\nस्मरश्रमजलाणुभिः सकलगात्रजैः सङ्गमः ॥ ८॥', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'तवाऽष्टकमिदं मुदा पठति सूरसूते सदा\nसमस्तदुरितक्षयो भवति वै मुकुन्दे रतिः ।\nतया सकलसिद्धयो मुररिपुश्च सन्तुष्यति\nस्वभावविजयो भवेद्वदति वल्लभः श्रीहरेः ॥ ९॥\nइति श्रीवल्लभाचार्यविरचितं श्रीयमुनाष्टकं सम्पूर्णम् ।', transliteration: ''),
  ],
  'X_vvNRPms88': [
    LyricStanza(startTimeMs: 0, devanagari: '|| राणी सती दादीजी आरती ||\nॐ जय श्री राणी सती माता, मैया जय जगदम्ब सती, अपने भक्त जनों की, अपने दास जनों की, दूर करो विपत्ती॥ ॐ जय श्री राणी सती …', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'अवनि अनंतर ज्योति अखंडीत, मंडित चहुँ ककुंभा दुर्जन दलन खडग की विद्युत सम प्रतिभा॥ ॐ जय श्री राणी सती …\nमरकत मणि मंदिर अति मंजुल, शोभा लखि न पडे, ललित ध्वजा चहुँ ओरे , कंचन कलश धरे', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: '॥ ॐ जय श्री राणी सती …\nघंटा घनन घडावल बाजत, शंख मृदुग घूरे, किन्नर गायन करते वेद ध्वनि उचरे', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: '॥ ॐ जय श्री राणी सती …\nसप्त मात्रिका करे आरती, सुरगण ध्यान धरे, विविध प्रकार के व्यजंन, श्रीफल भेट धरे', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: '॥ ॐ जय श्री राणी सती …\nसंकट विकट विदारनि, नाशनि हो कुमति, सेवक जन ह्रदय पटले, मृदूल करन सुमति', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: '|| ॐ जय श्री राणी सती …\nअमल कमल दल लोचनी, मोचनी त्रय तापा| दास आयो है शरण आपकी, लाज रखो माता', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: '॥ ॐ जय श्री राणी सती … श्री राणी सती मैया जी की आरती, जो कोई नर गावे, सदनसिद्धि नवनिधी , मनवांछित फल पावे\n|| ॐ जय श्री राणी सती …', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'ॐ जय श्री राणी सती माता, मैया जय जगदम्ब सती, अपने भक्त जनों की, अपने दास जनों की, दूर करो विपत्ती\n॥ ॐ जय श्री राणी सती …', transliteration: ''),
  ],
  'Y5kIExTTtvY': [
    LyricStanza(startTimeMs: 0, devanagari: '॥ श्री गंगा मैया आरती ॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'नमामि गंगे ! तव पाद पंकजम्,\nसुरासुरैः वंदित दिव्य रूपम् ।\nभक्तिम् मुक्तिं च ददासि नित्यं,\nभावानुसारेण सदा नराणाम् ॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'हर हर गंगे, जय माँ गंगे,\nहर हर गंगे, जय माँ गंगे ॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'ॐ जय गंगे माता,\nश्री जय गंगे माता ।\nजो नर तुमको ध्याता,\nमनवांछित फल पाता ॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'चंद्र सी जोत तुम्हारी,\nजल निर्मल आता ।\nशरण पडें जो तेरी,\nसो नर तर जाता ॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: '॥ ॐ जय गंगे माता..॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'पुत्र सगर के तारे,\nसब जग को ज्ञाता ।\nकृपा दृष्टि तुम्हारी,\nत्रिभुवन सुख दाता ॥', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: '॥ ॐ जय गंगे माता..॥', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'एक ही बार जो तेरी,\nशारणागति आता ।\nयम की त्रास मिटा कर,\nपरमगति पाता ॥', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: '॥ ॐ जय गंगे माता..॥', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'आरती मात तुम्हारी,\nजो जन नित्य गाता ।\nदास वही सहज में,\nमुक्त्ति को पाता ॥', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: '॥ ॐ जय गंगे माता..॥', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'ॐ जय गंगे माता,\nश्री जय गंगे माता ।\nजो नर तुमको ध्याता,\nमनवांछित फल पाता ॥', transliteration: ''),
    LyricStanza(startTimeMs: 390000, devanagari: 'ॐ जय गंगे माता,\nश्री जय गंगे माता ।', transliteration: ''),
  ],
  'aai1k4SX_uk': [
    LyricStanza(startTimeMs: 0, devanagari: 'नरसिंहकवचम्\nश्री गणेशाय नमः ।\nश्रीमद्दिव्यलक्ष्मीनृसिंहाय नमः ।\nअथ श्रीलक्ष्मीनृसिंहकवचप्रारम्भः ।\nॐ अस्य श्रीलक्ष्मीनृसिंहकवचमालामन्त्रस्य व्यासप्रह्लाद ऋषिः शिरसि ।\nश्रीलक्ष्मीनृसिंहो देवता हृदये । अनुष्टुप्छन्दः मुखे ।\nसर्वव्यापी स्तम्भवासो बीजं नाभौ ।\nश्रीः शक्तिः पादयोः ।', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'गुह्यरूपधृक् कीलकं सर्वाङ्गे ।\nश्रीलक्ष्मीनृसिंहप्रसादसिद्ध्यर्थे श्रीलक्ष्मीनृसिंहकवचस्तोत्रमन्त्रराजजपे विनियोगः ।\nअथ करन्यासः ।\nॐ योगिहृत्पद्मवासाय अङ्गुष्ठाभ्यां नमः ।\nॐ लक्ष्मीनृसिंहाय तर्जनीभ्यां नमः ।\nॐ स्वप्रकाशाय मध्यमाभ्यां नमः ।\nॐ सहस्रशीर्षाय अनामिकाभ्यां नमः ।\nॐ सोमसूर्याग्निलोचनाय कनिष्ठिकाभ्यां नमः ।', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'ॐ दिव्यास्त्रशोभितभुजाय करतलकरपृष्ठाभ्यां नमः ।\nअथ हृदयादिन्यासः ।\nॐ योगिहृत्पद्मवासाय हृदयाय नमः ।\nॐ लक्ष्मीनृसिंहाय शिरसे स्वाहा ।\nॐ स्वप्रकाशाय शिखायै वषट् ।\nॐ सहस्रशीर्षाय कवचाय हुम् ।\nॐ सोमसूर्याग्निलोचनाय नेत्रत्रयाय वौषट् ।\nॐ दिव्यास्त्रशोभितभुजाय अस्त्राय फट् ।', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'ॐ भूर्भुवस्वरोम् ।\nइति दिग्बन्धः ।\nअथ ध्यानम् ।\nकर्पूरधामबलं कटकाङ्गदादि-छत्रं त्रिनेत्रशशिशेखरमण्डितास्यम् ।\nवामाङ्कसंस्थितरमानयनाभिरामं चक्राब्जशङ्खसगदं नृहरि नमामि ॥ ।\nनमस्कृत्य गणाधीशं सर्वविघ्ननिवारणम् ।\nनृसिंहकवचं वक्ष्ये प्रह्लादेनोदितं पुरा ।\nसर्वरक्षाकरं पुण्यं सर्वोपद्रवनाशनम् ॥ १॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'सर्व सम्पत्करं चैव स्वर्गमोक्षप्रदायकम् ।\nध्यात्वा नृसिंहं देवेशं हेमसिंहासनस्थितम् ॥ २॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'विवृतास्यं त्रिनयनं शरदिन्दुसमप्रभम् ।\nलक्ष्म्यालिङ्गितवामाङ्गं विभूतिभिरुपाश्रितम् ॥ ३॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'चतुर्भुजं कोमलाङ्गं स्वर्णकुण्डलशोभितम् ।\nसरोजशोभितोरस्कं रत्नकेयूरमुद्रितम् ॥ ४॥', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'तप्तकाञ्चनसंकाशं पीतनिर्मलवाससम् ।\nइन्द्रादिसुरमौलिस्थस्फुरन्माणिक्यदीप्तिभिः ॥ ५॥', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'विराजितपदद्वन्द्वं शङ्खचक्रादि हेतिभिः ।\nगरुत्मता च विनयात् स्तूयमानं मुदान्वितम् ॥ ६॥', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'स्वहृत्कमलसंवासं कृत्वा तु कवचं पठेत् ।\nनृसिंहो मे शिरः पातु लोकरक्षार्थसम्भवः ॥ ७॥', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'सर्वगोऽपि स्तम्भवासः भालं मे रक्षतु ध्वनिम् ।\nनृसिंहो मे दृशौ पातु सोमसूर्याग्निलोचनः ॥ ८॥', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'स्मृतिं मे पातु नृहरिर्मुनिवर्यस्तुतिप्रियः ।\nनासं मे सिंहनासस्तु मुखं लक्ष्मीमुखप्रियः ॥ ९॥', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'सर्वविद्याधिपः पातु नृसिंहो रसनां मम ।\nवक्त्रं पात्विन्दुवदनं सदा प्रह्लादवन्दितः ॥ १०॥', transliteration: ''),
    LyricStanza(startTimeMs: 390000, devanagari: 'नृसिंहः पातु मे कण्ठं स्कन्धौ भूभरान्तकृत् ।\nदिव्यास्त्रशोभितभुजो नृसिंहः पातु मे भुजौ ॥ ११॥', transliteration: ''),
    LyricStanza(startTimeMs: 420000, devanagari: 'करौ मे देववरदो नृसिंहः पातु सर्वतः ।\nहृदयं योगिसाध्यश्च निवासं पातु मे हरिः ॥ १२॥', transliteration: ''),
    LyricStanza(startTimeMs: 450000, devanagari: 'मध्यं पातु हिरण्याक्षवक्षःकुक्षिविदारणः ।\nनाभिं मे पातु नृहरिः स्वनाभि ब्रह्मसंस्तुतः ॥ १३॥', transliteration: ''),
    LyricStanza(startTimeMs: 480000, devanagari: 'ब्रह्माण्डकोटयः कट्यां यस्यासौ पातु मे कटिम् ।\nगुह्यं मे पातु गुह्यानां मन्त्राणां गुह्यरूपदृक् ॥ १४॥', transliteration: ''),
    LyricStanza(startTimeMs: 510000, devanagari: 'ऊरु मनोभवः पातु जानुनी नररूपधृक् ।\nजङ्घे पातु धराभारहर्ता योऽसौ नृकेसरी ॥ १५॥', transliteration: ''),
    LyricStanza(startTimeMs: 540000, devanagari: 'सुरराज्यप्रदः पातु पादौ मे नृहरीश्वरः ।\nसहस्रशीर्षा पुरुषः पातु मे सर्वशस्तनुम् ॥ १६॥', transliteration: ''),
    LyricStanza(startTimeMs: 570000, devanagari: 'महोग्रः पूर्वतः पातु महावीराग्रजोऽग्नितः ।\nमहाविष्णुर्दक्षिणे तु महाज्वालस्तु नैरृतौ ॥ १७॥', transliteration: ''),
    LyricStanza(startTimeMs: 600000, devanagari: 'पश्चिमे पातु सर्वेशो दिशि मे सर्वतोमुखः ।\nनृसिंहः पातु वायव्यां सौम्यां भीषणविग्रहः ॥ १८॥', transliteration: ''),
    LyricStanza(startTimeMs: 630000, devanagari: 'ईशान्यां पातु भद्रो मे सर्वमङ्गलदायकः ।\nसंसारभयतः पातु मृत्योर्मृत्युर्नृकेसरी ॥ १९॥', transliteration: ''),
    LyricStanza(startTimeMs: 660000, devanagari: '(जले रक्षतु वाराहः स्थले रक्षतु वामनः ।\nअटव्यां नारसिंहश्च सर्वतः पातु केशवः ॥)\nइदं नृसिंहकवचं प्रह्लादमुखमण्डितम् ।\nभक्तिमान् यः पठेन्नित्यं सर्वपापैः प्रमुच्यते ॥ २०॥', transliteration: ''),
    LyricStanza(startTimeMs: 690000, devanagari: 'पुत्रवान् धनवान् लोके दीर्घायुरुपजायते ।\nयं यं कामयते कामं तं तं प्राप्नोत्यसंशयम् ॥ २१॥', transliteration: ''),
    LyricStanza(startTimeMs: 720000, devanagari: 'सर्वत्र जयमाप्नोति सर्वत्र विजयी भवेत् ।\nभूम्यन्तरीक्षदिव्यानां ग्रहाणां विनिवारणम् ॥ २२॥', transliteration: ''),
    LyricStanza(startTimeMs: 750000, devanagari: 'वृश्चिकोरगसम्भूत विषापहरणं परम् ।\nब्रह्मराक्षसयक्षाणां दूरोत्सारणकारणम् ॥ २३॥', transliteration: ''),
    LyricStanza(startTimeMs: 780000, devanagari: 'भूर्जे वा तालपत्रे वा कवचं लिखितं शुभम् ।\nकरमूले धृतं येन सिध्येयुः कर्मसिद्धयः ॥ २४॥', transliteration: ''),
    LyricStanza(startTimeMs: 810000, devanagari: 'देवासुरमनुष्येषु स्वं स्वमेव जयं लभेत् ।\nएकसन्ध्यं त्रिसन्ध्यं वा यः पठेन्नियतो नरः ॥ २५॥', transliteration: ''),
    LyricStanza(startTimeMs: 840000, devanagari: 'सर्वमङ्गलमाङ्गल्यं भुक्तिं मुक्तिं च विन्दति ।\nद्वात्रिंशतिसहस्राणि पठेत् शुद्धात्मनां नृणाम् ॥ २६॥', transliteration: ''),
    LyricStanza(startTimeMs: 870000, devanagari: 'कवचस्यास्य मन्त्रस्य मन्त्रसिद्धिः प्रजायते ।\nअनेन मन्त्रराजेन कृत्वा भस्माभिमन्त्रणम् ॥ २७॥', transliteration: ''),
    LyricStanza(startTimeMs: 900000, devanagari: 'तिलकं विन्यसेद्यस्तु तस्य ग्रहभयं हरेत् ।\nत्रिवारं जपमानस्तु दत्तं वार्यभिमन्त्र्य च ॥ २८॥', transliteration: ''),
    LyricStanza(startTimeMs: 930000, devanagari: 'प्राशयेद्यो नरो मन्त्रं नृसिंहध्यानमाचरेत् ।\nतस्य रोगाः प्रणश्यन्ति ये च स्युः कुक्षिसम्भवाः ॥ २९॥', transliteration: ''),
    LyricStanza(startTimeMs: 960000, devanagari: 'किमत्र बहुनोक्तेन नृसिंहसदृशो भवेत् ।\nमनसा चिन्तितं यत्तु स तच्चाप्नोत्यसंशयम् ॥ ३०॥', transliteration: ''),
    LyricStanza(startTimeMs: 990000, devanagari: '(नृसिंहकोश २ -\nइति परमरहस्यसारमेतत्कवचवरं पठतीह यस्तु भक्त्या ।\nस भवति धनधान्यपुत्र भोगी तनुविगमे समुपैति नारसिंहम् ॥ ३१॥', transliteration: ''),
    LyricStanza(startTimeMs: 1020000, devanagari: 'तप्तहाटककेशान्तज्वलत्पावकलोचन ।\nवज्रायुधनखस्पर्श दिव्यसिंह नमोऽस्तु ते ॥ ३२॥', transliteration: ''),
    LyricStanza(startTimeMs: 1050000, devanagari: 'श्रीनृसिंहो दिव्यसिंहः सर्वाभीष्टप्रदायकः ।\nएकवीरोऽद्भुतबलो मन्त्रयन्त्रकभञ्जनः ॥ ३३॥', transliteration: ''),
    LyricStanza(startTimeMs: 1080000, devanagari: 'भयं नास्ति भयं नास्ति नृसिंहपदसेवानात्।\nसत्यं सत्यं वचो वच्मि शङ्करोऽहं त्रिलोचनः ॥ ३४॥', transliteration: ''),
    LyricStanza(startTimeMs: 1110000, devanagari: 'कुतो भीतिः कुतो मृत्युः कुतस्तस्य दरिद्रता ।\nमृत्योर्मृत्युः रमानाथो यस्य नाथो नृकेसरी ॥ ३५॥', transliteration: ''),
    LyricStanza(startTimeMs: 1140000, devanagari: 'भर्जनं भवबीजानां वर्धनं सुखसम्पदाम् ।\nतर्जनं यमदूतानां नृहरेर्नामगर्जनम् ॥ ३६॥', transliteration: ''),
    LyricStanza(startTimeMs: 1170000, devanagari: 'माता नृसिंहश्च पिता नृसिंहो भ्राता नृसिंहश्च सखा नृसिंहः\nविद्या नृसिंहो द्रविणं नृसिंहः स्वामी नृसिंहः सकलं नृसिंहः ॥ ३७॥', transliteration: ''),
    LyricStanza(startTimeMs: 1200000, devanagari: 'यतो नृसिंहः परतो नृसिंहो यतो यतो यामि ततो नृसिंहः ।\nनृसिंहदेवादपरं न किञ्चित् ।\nतस्मान्नृसिंहं शरणं प्रपद्ये ॥ ३८॥', transliteration: ''),
  ],
  'bl7D9lkR21E': [
    LyricStanza(startTimeMs: 0, devanagari: 'मैं अरज करूँ श्री राधा गोविन्द आप सुन लीजो ।\nथाँका चरण कमल की भक्ति सदा मोहे दीजो ।। १ ।।', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'ऐजी प्रभु मैं अनाथ तुम नाथ कृपा मोपे कीजो ।\nअब मेरी गरीब की विनय कान घर लीजो ॥ २ ॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'ऐजी प्रभु भवसागर मैं भयो जात महाराजा ।\nमैं बेद पुराण न सुनो जी जगत के राजा ।। ३ ।।', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'ऐजी प्रभु मोह माया जंजाल जनम की फाँसी ।\nमैं फसा जात हूँ निकसा कैसे जासी ।। ४ ।।', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'ऐजी प्रभु अजायेमल से पतित उबारेन त्यारे ।\nजब सुआ पढ़ावत गणिका हरि ने त्यारी ।। ५ ।।', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'अजी प्रभु प्रहलाद काज नृसिंह रूप हरि धारो।\nजब हिरण्य कश्यप को उदर नखन ते बिदारयो ।। ६ ।।', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'ऐजी प्रभु द्रुपद सुता को चीर बढायो बहु भारी ।\nजब दुष्ट दुशासन खैंचत खैँचत हारि ।। ७ ।।', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'ऐजी प्रभु ब्रज पर कोप कियो इन्द्र ने भारी ।\nजब बावाँ नख पर गोवर्धन गिरधारी ।। ८ ।।', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'ऐजी प्रभु पाप पुण्य का भार शीश पर भारी ।\nमेरा भाग उतारो आपहि हो बनवारी ।। ९ ।।', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'ऐजी प्रभु विप्र सुदामा की विनती आप सुन लीजो ।\nम्हारी हुई दरिद्रता दूर भक्ति निज दीजो ।। १० ।।', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'ऐजी प्रभु ऐजी प्रभुमुझ गरीब की सुन-सुन अन्तर्यामी ।\nअब मेरा बेड़ा पार लगावो आप मेरे स्वामी ।। ११ ।।', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'ऐजी प्रभु भक्तवत्सल भगवान जगत के राजा ।\nम्हारी गौर \'सूर\' की विनय सुनो महाराजा ।। १२ ।।\nमैं अरज करूँ श्री राधा गोविन्द आप सुन लीजो, थाँका चरण कमल की भक्ति सदा मोहे दीजो', transliteration: ''),
  ],
  'bxamgoLWfJo': [
    LyricStanza(startTimeMs: 0, devanagari: 'जननी उमिया शिर नमुं, करुं चालीसा आज।\nकृपा करहु मोपर सदा, पूरन हो मम काज॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: '॥ चोपाई (स्वरूप, माहात्म्य अने स्तुति) ॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'आद्यशक्ति मा उमिया तु छे, परा शक्ति मा उमिया तु छे ॥१', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'शिव शक्ति मा उमिया तु छे, प्राण शक्ति मा उमिया तु छे ॥२', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'शकल विश्व नी सर्जनहारी, प्राणी मात्र नी पालनहारी ॥३', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'ममता महिमा माता तु प्यारी, सौ पर करुणा तुं करनारी ॥४', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'ब्रह्मा सर्जन शक्ति वाचक, विष्णु तवनव शक्ति आचक ॥५', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'महेश तव शक्ति पर रांचे, तव शक्ति विण जग के नचाले ॥६', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'उमिया तुं छे वेद नी वाणी, रूषिमुनीयो ए तुजने जाणी ॥७', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'पुराणो ए पण तने वखाणी, संतो भगतो ए पण मानी ॥८', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'तव शक्ति से जगत उजासे, तव शक्ति से सौ नर तरासे ॥९', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'तव शक्ति से सूरज चमके, तव शक्ति से चंद्र दमके ॥१०', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'तव शक्ति से पवन वहे छे, तव शक्ति से वर्षा थई छे ॥११', transliteration: ''),
    LyricStanza(startTimeMs: 390000, devanagari: 'तव शक्ति से धरती थंभी, तव शक्ति से आकाश उंची ॥१२', transliteration: ''),
    LyricStanza(startTimeMs: 420000, devanagari: 'तव शक्ति से सागर गाजे, तव शक्ति से पर्वत शाजे ॥१३', transliteration: ''),
    LyricStanza(startTimeMs: 450000, devanagari: 'तव शक्ति से जीवो फूले, तव शक्ति से फळो शोभे ॥१४', transliteration: ''),
    LyricStanza(startTimeMs: 480000, devanagari: 'तुं सिवाय कोण छे माता, आ जगत नो आधार छे माता ॥१५', transliteration: ''),
    LyricStanza(startTimeMs: 510000, devanagari: 'तुं सिवाय कोण रखवाळी, जीवो नी हेतुवाळी भाळी ॥१६', transliteration: ''),
    LyricStanza(startTimeMs: 540000, devanagari: 'अंबा तु छे दुःखहारणी, भक्तो नी छे संकट मारणी ॥१७', transliteration: ''),
    LyricStanza(startTimeMs: 570000, devanagari: 'भक्त जनो ना मन इच्छा पूरे, सदा सुख संपत्ति धरे ॥१८', transliteration: ''),
    LyricStanza(startTimeMs: 600000, devanagari: 'श्री उमिया नाम जपे जे कोई, ते दुःख मां डूबे न कोई ॥१९', transliteration: ''),
    LyricStanza(startTimeMs: 630000, devanagari: 'श्री उमिया चरणो ध्यावे, ते सुख सागर मां न्हावे ॥२०', transliteration: ''),
    LyricStanza(startTimeMs: 660000, devanagari: 'साकंत थकी संताप हरे, भक्तो ना संकट सौ टळे ॥२१', transliteration: ''),
    LyricStanza(startTimeMs: 690000, devanagari: 'श्री उमिया स्मरण करनारे, कलि मां हर्षित थइ विहरे ॥२२', transliteration: ''),
    LyricStanza(startTimeMs: 720000, devanagari: 'रोग शोक दारिद्र भय हारी, उमिया मा करे उद्धारी ॥२३', transliteration: ''),
    LyricStanza(startTimeMs: 750000, devanagari: 'शत्रु पर विजय आपे माता, सदा रहे यश गाता ॥२४', transliteration: ''),
    LyricStanza(startTimeMs: 780000, devanagari: 'न्यायालय मां सफळता दे, वाद विवाद मां विजय छे ॥२५', transliteration: ''),
    LyricStanza(startTimeMs: 810000, devanagari: 'कार्य सिद्ध करे मा उमिया, करे अवरोध सौ दूरिया ॥२६', transliteration: ''),
    LyricStanza(startTimeMs: 840000, devanagari: 'गृह मां सुख शांति लावे, कुटुंब ने सौ सुख आवे ॥२७', transliteration: ''),
    LyricStanza(startTimeMs: 870000, devanagari: 'बाळको ने सदगति दे, गुणो थी भरपूर बनावे ॥२८', transliteration: ''),
    LyricStanza(startTimeMs: 900000, devanagari: 'दांपत्य जीवन सुखमय करे, प्रेम नो अखंड खजानो धरे ॥२९', transliteration: ''),
    LyricStanza(startTimeMs: 930000, devanagari: 'विद्या दे तुं मा उमिया, ग्हान दे तुं मा उमिया ॥३०', transliteration: ''),
    LyricStanza(startTimeMs: 960000, devanagari: 'धन धान्य नो भंडार भरे, मा उमिया तुं सौ सुख करे ॥३१', transliteration: ''),
    LyricStanza(startTimeMs: 990000, devanagari: 'सौभाग्य आपे जगदम्बा, सदा रहे सुमंगल शम्बा ॥३२', transliteration: ''),
    LyricStanza(startTimeMs: 1020000, devanagari: 'जे भक्त आ चालीसा गाशे, अष्टसिद्धि नव निधि पाशे ॥३३', transliteration: ''),
    LyricStanza(startTimeMs: 1050000, devanagari: 'दस हजार पाठ जे करशे, ते मनवांछित फळ धरशे ॥३४', transliteration: ''),
    LyricStanza(startTimeMs: 1080000, devanagari: 'सात दिन नित्य जे पाठ करे, ते कोई दुःख ना व्यापे ॥३५', transliteration: ''),
    LyricStanza(startTimeMs: 1110000, devanagari: 'एक मास सुधी जे गाशे, ते सर्व सिद्धि प्राप्त करशे ॥३६', transliteration: ''),
    LyricStanza(startTimeMs: 1140000, devanagari: 'प्रातः सायं जे ध्यान धरे, ते मा कृपा तुरत भरे ॥३७', transliteration: ''),
    LyricStanza(startTimeMs: 1170000, devanagari: 'शुद्ध भावे पूजा जे करे, ते जीवन मां सुख भरे ॥३८', transliteration: ''),
    LyricStanza(startTimeMs: 1200000, devanagari: 'उमिया मा कृपा नी दृष्टिथी, जगत नो उद्धार थतो दीठी ॥३९', transliteration: ''),
    LyricStanza(startTimeMs: 1230000, devanagari: 'भक्तो ना काज सवारे, उमिया मा सदा विहारे ॥४०', transliteration: ''),
    LyricStanza(startTimeMs: 1260000, devanagari: '॥ समापन दोहा ॥', transliteration: ''),
    LyricStanza(startTimeMs: 1290000, devanagari: 'उमिया माता करुणामयी, दास नी लाज रखे।\nसुख संपत्ति आपी सदा, भव भय हरे सघळे॥', transliteration: ''),
    LyricStanza(startTimeMs: 1320000, devanagari: 'जय जय उमिया मा, जय जय उमिया मा।\nजय जय उमिया मा, जय जय उमिया मा॥', transliteration: ''),
  ],
  'dkVnDPJiUi4': [
    LyricStanza(startTimeMs: 0, devanagari: 'श्रीगणेशाय नमः ।\nस्कन्द उवाच ।\nयोगीश्वरो महासेनः कार्तिकेयोऽग्निनन्दनः ।\nस्कन्दः कुमारः सेनानीः स्वामी शङ्करसम्भवः ॥ १॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'गाङ्गेयस्ताम्रचूडश्च ब्रह्मचारी शिखिध्वजः ।\nतारकारिरुमापुत्रः क्रौञ्चारिश्च षडाननः ॥ २॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'शब्दब्रह्मसमुद्रश्च सिद्धः सारस्वतो गुहः ।\nसनत्कुमारो भगवान् भोगमोक्षफलप्रदः ॥ ३॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'शरजन्मा गणाधीशपूर्वजो मुक्तिमार्गकृत् ।\nसर्वागमप्रणेता च वाञ्छितार्थप्रदर्शनः ॥ ४॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'अष्टाविंशतिनामानि मदीयानीतियः पठेत् ।\nप्रत्यूषं श्रद्धया युक्तो मूको वाचस्पतिर्भवेत् ॥ ५॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'महामन्त्रमयानीति मम नामानुकीर्तनम् ।\nमहाप्रज्ञामवाप्नोति नात्र कार्या विचारणा ॥ ६॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: '॥ इति श्रीरुद्रयामले प्रज्ञाविवर्धनाख्यं\nश्रीमत्कार्तिकेयस्तोत्रं सम्पूर्णम् ॥', transliteration: ''),
  ],
  'ehd2G7x3EwU': [
    LyricStanza(startTimeMs: 0, devanagari: 'श्रीनीलकण्ठस्तवः\nनमो भूतनाथं नमो देवदेवं\nनमः कालकालं नमो दिव्यतेजः ।\nनमः कालभस्मं नमः शान्तशीलं\nभजे पार्वतीवल्लभं नीलकण्ठम् ॥ १॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'सदा तीर्थसिद्धं सदा भक्तरक्षं\nसदा शैवपूज्यं सदा शुभ्रभस्मम् ।\nसदा ध्यानयुक्तं सदा ज्ञानतल्पं\nभजे पार्वतीवल्लभं नीलकण्ठम् ॥ २॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'श्मशाने शयानं महास्थानवासं\nशरीरं गजानां सदा चर्मवेष्टम् ।\nपिशाचापशूनां प्रतिष्ठं\nभजे पार्वतीवल्लभं नीलकण्ठम् ॥ ३॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'फणीनागकुण्ठेभुजङ्गाद्यनेकं\nगले रुण्डमालं महावीरशूरम् ।\nकटिव्याघ्रचर्माञ्चिताभस्मलेपं\nभजे पार्वतीवल्लभं नीलकण्ठम् ॥ ४॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'शिरश्शुद्धगङ्गं शिवावामभागं\nवियद्दीर्घकेशं सदा मांत्रिनेत्रम् ।\nफणीनागकर्णं सदास्भालचन्द्रं\nभजे पार्वतीवल्लभं नीलकण्ठम् ॥ ५॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'करे शूलधारं मराकष्टनाशं\nसुरेशं परेशं महेशं जनेशम् ।\nधने चारु ईशंध्वजेशं गिरीशं\nभजे पार्वतीवल्लभं नीलकण्ठम् ॥ ६॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'उदासं सुदासं सुकैलासवासं\nधरानिर्झरे संस्थितं ह्यादिदेवम् ।\nअजं हेमकल्पद्रुमं कल्पसेव्यं\nभजे पार्वतीवल्लभं नीलकण्ठम् ॥ ७॥', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'मुनीनां वरेण्यं गुणं रूपवर्णं\nद्विजा सम्पठन्तंशिवं वेदशास्त्रैः ।\nअहो दीनवत्सं कृपालुं शिवं हि\nभजे पार्वतीवल्लभं नीलकण्ठम् ॥ ८॥', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'सदा भावनाथं सदा सेव्यमानं\nसदा भक्तिदेवं सदा पूज्यमानम् ।\nमहातीर्थवासं सदा सेव्यमेकं\nभजे पार्वतीवल्लभं नीलकण्ठम् ॥ ९॥', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: '॥ इति श्रीनीलकण्ठस्तवः सम्पूर्णः ॥', transliteration: ''),
  ],
  'i212quHc20Y': [
    LyricStanza(startTimeMs: 0, devanagari: '॥ श्रीआशापूराऽष्टोत्तर शतनामस्तोत्रम्॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: '॥ श्री गणेशायनमः ॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'अथ मूलमंत्र: -\n॥ ॐ ह्रीं आशापूरायै नमः ॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: '॥ अनेन मन्त्रेण प्राणायाम त्रयं कुर्यात् ॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'अथ हृदयादि न्यासः -\nॐ ह्रां हृदयाय नमः ॥ ॐ ह्रीं शिरसे स्वाहा ॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'ॐ ह्रूं शिखायै वषट् ॥ ॐ ह्रैं कवचाय हुम् ॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'ॐ ह्रौं नेत्रत्रयाय वौषट्॥ॐ ह्रः अस्त्राय फट्॥१॥', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'अथ करन्यासः -\nॐ ह्रां अगुष्ठाभ्यां नमः ॥ ॐ ह्रीं तर्जनीभ्यां नमः ॥', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'ॐ ह्रूं मध्यमाभ्यां नमः ॥ ॐ ह्रैं अनामिकाभ्यां नमः ॥', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'ॐ ह्रौं कनिष्ठिकाभ्यां नमः॥', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'ॐ ह्रः करतलकरपृष्ठाभ्यां नमः ॥', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'अथ ध्यानम् :-\nआशापूरां जगद्धात्रीं रक्तवस्त्रां चतुर्भुजाम्।\nखड्गचापत्रिशूलैश्च गदा बाणादिभिर्युताम्॥', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'मृगेन्द्रवाहिनीं देवीं भक्तानामभयङ्करीम् ।\nकच्छभुजप्रसिद्धां तां ध्याये पोकरणस्थिताम्॥', transliteration: ''),
    LyricStanza(startTimeMs: 390000, devanagari: 'श्रीअम्बा भुवनेश्वरीं भगवतीं कात्यायनीं कालिकां,\nकौमारीं कमलोद्भवां कविकलां कामेश्वरीं कामदाम् ।\nछिन्नां पूर्णपरां गिरीशबगुलां मातङ्गिनीं तारिणीं,\nश्रीचक्रप्रियविन्दुतर्पणपरां श्रीराजराजेश्वरीम् ॥२॥', transliteration: ''),
    LyricStanza(startTimeMs: 420000, devanagari: '॥ इति देवी ध्यात्वा ॥', transliteration: ''),
    LyricStanza(startTimeMs: 450000, devanagari: '॥ यथाशक्ति: जपं कुर्यात् ॥', transliteration: ''),
    LyricStanza(startTimeMs: 480000, devanagari: 'विनियोग :- हस्ते जलं गृहीत्वा\nॐ अस्य श्रीआशापूराऽष्टोतरशतनामस्तोत्रस्य ब्रह्मा\nऋषिरनुष्टुप् छन्दः श्रीआशापुरा देवता सर्वाभीष्ट\nसिद्ध्यर्थे पाठे विनियोगः इति पठित्वा जलं त्यजेत् ॥', transliteration: ''),
    LyricStanza(startTimeMs: 510000, devanagari: 'अथाष्टोत्तर शतनामस्तोत्रम् :-\nआशापूरा महामाया ह्यभेदा चैन्दवी कला ।\nआदिविद्या चादिभूता ह्यादिसिद्धि प्रदायिनी ॥१॥', transliteration: ''),
    LyricStanza(startTimeMs: 540000, devanagari: 'अष्टसिद्धिप्रदा देवीं नवनिधि प्रदायिनी ।\nअन्नपूर्णा महा गौरी लक्ष्मी प्रणवरूपिणी ॥२॥', transliteration: ''),
    LyricStanza(startTimeMs: 570000, devanagari: 'कमला विमला नित्या सर्वशोक निवारिणी ।\nकामक्षा भैरवी भीमा विजया चह्यूमाजया ॥३॥', transliteration: ''),
    LyricStanza(startTimeMs: 600000, devanagari: 'गायत्री गोमती गङ्गा गीता गोत्रविवर्धिनी ।\nगिरिजा चंद्रघंटा च पद्मावती सरस्वती ॥४॥', transliteration: ''),
    LyricStanza(startTimeMs: 630000, devanagari: 'चामुण्डा चण्डिका चण्डी चूडामणिश्च चर्चिका ।\nभगिनी चक्र पाणेश्च चराचर निवासिनी ॥५॥', transliteration: ''),
    LyricStanza(startTimeMs: 660000, devanagari: 'धन धान्या च गौ रूपा धनाढ्या धनदायिनी ।\nधर्मशा धर्मलीना च धर्मराजप्रसादिनी ॥६॥', transliteration: ''),
    LyricStanza(startTimeMs: 690000, devanagari: 'धर्मरूप मय्यी दिव्या धर्माधर्म विचारिणी ।\nसुधर्मा धर्म मर्मज्ञा घर्मिष्ठा धर्मगोचरी ॥७॥', transliteration: ''),
    LyricStanza(startTimeMs: 720000, devanagari: 'वज्रहस्ता महामाया दुर्गा नारायणी शिवा ।\nनर्मदा निर्मला नोला नवभक्ति प्रदायिनी ॥८॥', transliteration: ''),
    LyricStanza(startTimeMs: 750000, devanagari: 'परा विद्या परा सिद्धिः परसैन्य विनाशिनी ।\nपुष्पा पुष्पवती पुण्या परब्रह्मस्वरूपिणी ॥९॥', transliteration: ''),
    LyricStanza(startTimeMs: 780000, devanagari: 'ब्रह्माणी ब्रह्मशक्तिर्हि विष्णुशक्तिश्च वैष्णवी।\nबैकुण्ठा वासिनी चाम्बा वैकुंठ पददायिनी ॥१०॥', transliteration: ''),
    LyricStanza(startTimeMs: 810000, devanagari: 'पंचवक्त्रा महाकाली कच्छभुजनिवासिनी ।\nभारती भद्रकाली च कालरात्रिः कपालिनी ॥११॥', transliteration: ''),
    LyricStanza(startTimeMs: 840000, devanagari: 'मंगला ललिता चार्या जगद्वश्यां च मोहिनी ।\nमहारात्रिर्महादेवी महाविद्या महोदरी ॥१२॥', transliteration: ''),
    LyricStanza(startTimeMs: 870000, devanagari: 'यज्ञकर्त्री हविर्भोक्त्री यज्ञरक्षणतत्परा ।\nयज्ञे च साक्षिणी श्यामा यज्ञ कर्म फलप्रदा ॥१३॥', transliteration: ''),
    LyricStanza(startTimeMs: 900000, devanagari: 'सुफला सत्यसंकल्पा सत्यासत्य विचारिणी।\nसत्यसंपद् प्रदात्री च सत्यलोकनिवासिनी ॥१४॥', transliteration: ''),
    LyricStanza(startTimeMs: 930000, devanagari: 'दारिद्र्यहारिणी माता सर्वदुःखविमोचिनी ।\nसर्वरोग प्रहंत्री च सर्व पाप विनाशिनी ॥१५॥', transliteration: ''),
    LyricStanza(startTimeMs: 960000, devanagari: 'इदं स्तोत्रं महत्पुण्यं सर्व सौभाग्यवर्द्धनम् ।\nप्रातः काले च मध्याह्ने सायं काले पठेन्नरः ॥१६॥', transliteration: ''),
    LyricStanza(startTimeMs: 990000, devanagari: 'आशापूरा प्रसादेन तस्यसिद्धिर्भविष्यति ।\nकिमत्र बहुनोक्तन सत्यं सत्यं न संशय ॥१७॥', transliteration: ''),
    LyricStanza(startTimeMs: 1020000, devanagari: '॥ इति श्री पुष्टिकरज्ञातीयविशा कुलभूषण पंडित\nद्वारिकादासात्मजेन श्रीनाथ शास्त्रिणां विरचितं\nश्रीआशापूराऽष्टोतरशतनामस्तोत्रं सम्पूर्णम् ॥', transliteration: ''),
  ],
  'iBmCao3u3ho': [
    LyricStanza(startTimeMs: 0, devanagari: 'सदा बालरूपाऽपि विघ्नाद्रिहन्त्री\nमहादन्तिवक्त्राऽपि पञ्चास्यमान्या ।\nविधीन्द्रादिमृग्या गणेशाभिधा मे\nविधत्तां श्रियं काऽपि कल्याणमूर्तिः ॥ १॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'न जानामि शब्दं न जानामि चार्थं\nन जानामि पद्यं न जानामि गद्यम् ।\nचिदेका षडास्या हृदि द्योतते मे\nमुखान्निःसरन्ते गिरश्चापि चित्रम् ॥ २॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'मयूराधिरूढं महावाक्यगूढं\nमनोहारिदेहं महच्चित्तगेहम् ।\nमहीदेवदेवं महावेदभावं\nमहादेवबालं भजे लोकपालम् ॥ ३॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'यदा सन्निधानं गता मानवा मे\nभवाम्भोधिपारं गतास्ते तदैव ।\nइति व्यञ्जयन्सिन्धुतीरे य आस्ते\nतमीडे पवित्रं पराशक्तिपुत्रम् ॥ ४॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'यथाब्धेस्तरङ्गा लयं यान्ति तुङ्गा-\nस्तथैवापदः सन्निधौ सेवतां मे ।\nइतीवोर्मिपङ्क्तीर्नृणां दर्शयन्तं\nसदा भावये हृत्सरोजे गुहं तम् ॥ ५॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'गिरौ मन्निवासे नरा येऽधिरूढा-\nस्तदा पर्वते राजते तेऽधिरूढाः ।\nइतीव ब्रुवन्गन्धशैलाधिरूढः\nस देवो मुदे मे सदा षण्मुखोऽस्तु ॥ ६॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'महाम्भोधितीरे महापापचोरे\nमुनीन्द्रानुकूले सुगन्धाख्यशैले ।\nगुहायां वसन्तं स्वभासा लसन्तं\nजनार्तिं हरन्तं श्रयामो गुहं तम् ॥ ७॥', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'लसत्स्वर्णगेहे नृणां कामदोहे\nसुमस्तोमसञ्छन्नमाणिक्यमञ्चे ।\nसमुद्यत्सहस्रार्कतुल्यप्रकाशं\nसदा भावये कार्तिकेयं सुरेशम् ॥ ८॥', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'रणद्धंसके मञ्जुलेऽत्यन्तशोणे\nमनोहारिलावण्यपीयूषपूर्णे ।\nमनःषट्पदो मे भवक्लेशतप्तः\nसदा मोदतां स्कन्द ते पादपद्मे ॥ ९॥', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'सुवर्णाभदिव्याम्बरैर्भासमानां\nक्वणत्किङ्किणीमेखलाशोभमानाम् ।\nलसद्धेमपट्टेन विद्योतमानां\nकटिं भावये स्कन्द ते दीप्यमानाम् ॥ १० ॥', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'पुलिन्देशकन्याघनाभोगतुङ्ग-\nस्तनालिङ्गनासक्तकाश्मीररागम् ।\nनमस्याम्यहं तारकारे तवोरः\nस्वभक्तावने सर्वदा सानुरागम् ॥ ११॥', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'विधौ कॢप्तदण्डान् स्वलीलाधृताण्डा-\nन्निरस्तेभशुण्डान् द्विषत्कालदण्डान् ।\nहतेन्द्रारिषण्डाञ्जगत्त्राणशौण्डान्\nसदा ते प्रचण्डान् श्रये बाहुदण्डान् ॥ १२॥', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'सदा शारदाः षण्मृगाङ्का यदि स्युः\nसमुद्यन्त एव स्थिताश्चेत्समन्तात् ।\nसदा पूर्णबिम्बाः कलङ्कैश्च हीना-\nस्तदा त्वन्मुखानां ब्रुवे स्कन्द साम्यम् ॥ १३॥', transliteration: ''),
    LyricStanza(startTimeMs: 390000, devanagari: 'स्फुरन्मन्दहासैः सहंसानि चञ्च-\nत्कटाक्षावलीभृङ्गसङ्घोज्ज्वलानि ।\nसुधास्यन्दिबिम्बाधराणीशसूनो\nतवालोकये षण्मुखाम्भोरुहाणि ॥ १४॥', transliteration: ''),
    LyricStanza(startTimeMs: 420000, devanagari: 'विशालेषु कर्णान्तदीर्घेष्वजस्रं\nदयास्यन्दिषु द्वादशस्वीक्षणेषु ।\nमयीषत्कटाक्षः सकृत्पातितश्चे-\nद्भवेत्ते दयाशील का नाम हानिः ॥ १५॥', transliteration: ''),
    LyricStanza(startTimeMs: 450000, devanagari: 'सुताङ्गोद्भवो मेऽसि जीवेति षड्धा\nजपन्मन्त्रमीशो मुदा जिघ्रते यान् ।\nजगद्भारभृद्भ्यो जगन्नाथ तेभ्यः\nकिरीटोज्ज्वलेभ्यो नमो मस्तकेभ्यः ॥ १६॥', transliteration: ''),
    LyricStanza(startTimeMs: 480000, devanagari: 'स्फुरद्रत्नकेयूरहाराभिराम-\nश्चलत्कुण्डलश्रीलसद्गण्डभागः ।\nकटौ पीतवासाः करे चारुशक्तिः\nपुरस्तान्ममास्तां पुरारेस्तनूजः ॥ १७॥', transliteration: ''),
    LyricStanza(startTimeMs: 510000, devanagari: 'इहायाहि वत्सेति हस्तान्प्रसार्या-\nह्वयत्यादराच्छङ्करे मातुरङ्कात् ।\nसमुत्पत्य तातं श्रयन्तं कुमारं\nहराश्लिष्टगात्रं भजे बालमूर्तिम् ॥ १८॥', transliteration: ''),
    LyricStanza(startTimeMs: 540000, devanagari: 'कुमारेशसूनो गुह स्कन्द सेना-\nपते शक्तिपाणे मयूराधिरूढ ।\nपुलिन्दात्मजाकान्त भक्तार्तिहारिन्\nप्रभो तारकारे सदा रक्ष मां त्वम् ॥ १९ ॥', transliteration: ''),
    LyricStanza(startTimeMs: 570000, devanagari: 'प्रशान्तेन्द्रिये नष्टसंज्ञे विचेष्टे\nकफोद्गारिवक्त्रे भयोत्कम्पिगात्रे ।\nप्रयाणोन्मुखे मय्यनाथे तदानीं\nद्रुतं मे दयालो भवाग्रे गुह त्वम् ॥ २०॥', transliteration: ''),
    LyricStanza(startTimeMs: 600000, devanagari: 'कृतान्तस्य दूतेषु चण्डेषु कोपा-\nद्दह च्छिन्द्धि भिन्द्धीति मां तर्जयत्सु ।\nमयूरं समारुह्य मा भैरिति त्वं\nपुरः शक्तिपाणिर्ममायाहि शीघ्रम् ॥ २१॥', transliteration: ''),
    LyricStanza(startTimeMs: 630000, devanagari: 'प्रणम्यासकृत्पादयोस्ते पतित्वा\nप्रसाद्य प्रभो प्रार्थयेऽनेकवारम् ।\nन वक्तुं क्षमोऽहं तदानीं कृपाब्धे\nन कार्यान्तकाले मनागप्युपेक्षा ॥ २२॥', transliteration: ''),
    LyricStanza(startTimeMs: 660000, devanagari: 'सहस्राण्डभोक्ता त्वया शूरनामा\nहतस्तारकः सिंहवक्त्रश्च दैत्यः ।\nममान्तर्हृदिस्थं मनःक्लेशमेकं\nन हंसि प्रभो किं करोमि क्व यामि ॥ २३ ॥', transliteration: ''),
    LyricStanza(startTimeMs: 690000, devanagari: 'अहं सर्वदा दुःखभारावसन्नो\nभवान्दीनबन्धुस्त्वदन्यं न याचे ।\nभवद्भक्तिरोधं सदा कॢप्तबाधं\nममाधिं द्रुतं नाशयोमासुत त्वम् ॥ २४ ॥', transliteration: ''),
    LyricStanza(startTimeMs: 720000, devanagari: 'अपस्मारकुष्ठक्षयार्शः प्रमेह-\nज्वरोन्मादगुल्मादिरोगा महान्तः ।\nपिशाचाश्च सर्वे भवत्पत्रभूतिं\nविलोक्य क्षणात्तारकारे द्रवन्ते ॥ २५॥', transliteration: ''),
    LyricStanza(startTimeMs: 750000, devanagari: 'दृशि स्कन्दमूर्तिः श्रुतौ स्कन्दकीर्ति-\nर्मुखे मे पवित्रं सदा तच्चरित्रम् ।\nकरे तस्य कृत्यं वपुस्तस्य भृत्यं\nगुहे सन्तु लीना ममाशेषभावाः ॥ २६॥', transliteration: ''),
    LyricStanza(startTimeMs: 780000, devanagari: 'मुनीनामुताहो नृणां भक्तिभाजा-\nमभीष्टप्रदाः सन्ति सर्वत्र देवाः ।\nनृणामन्त्यजानामपि स्वार्थदाने\nगुहाद्देवमन्यं न जाने न जाने ॥ २७॥', transliteration: ''),
    LyricStanza(startTimeMs: 810000, devanagari: 'कलत्रं सुता बन्धुवर्गः पशुर्वा\nनरो वाथ नारि गृहे ये मदीयाः ।\nयजन्तो नमन्तः स्तुवन्तो भवन्तं\nस्मरन्तश्च ते सन्तु सर्वे कुमार ॥ २८॥', transliteration: ''),
    LyricStanza(startTimeMs: 840000, devanagari: 'मृगाः पक्षिणो दंशका ये च दुष्टा-\nस्तथा व्याधयो बाधका ये मदङ्गे ।\nभवच्छक्तितीक्ष्णाग्रभिन्नाः सुदूरे\nविनश्यन्तु ते चूर्णितक्रौञ्चशैल ॥ २९॥', transliteration: ''),
    LyricStanza(startTimeMs: 870000, devanagari: 'जनित्री पिता च स्वपुत्रापराधं\nसहेते न किं देवसेनाधिनाथ ।\nअहं चातिबालो भवान् लोकतातः\nक्षमस्वापराधं समस्तं महेश ॥ ३०॥', transliteration: ''),
    LyricStanza(startTimeMs: 900000, devanagari: 'नमः केकिने शक्तये चापि तुभ्यं\nनमश्छाग तुभ्यं नमः कुक्कुटाय ।\nनमः सिन्धवे सिन्धुदेशाय तुभ्यं\nपुनः स्कन्दमूर्ते नमस्ते नमोऽस्तु ॥ ३१॥', transliteration: ''),
    LyricStanza(startTimeMs: 930000, devanagari: 'जयानन्दभूमञ्जयापारधाम-\nञ्जयामोघकीर्ते जयानन्दमूर्ते ।\nजयानन्दसिन्धो जयाशेषबन्धो\nजय त्वं सदा मुक्तिदानेशसूनो ॥ ३२॥', transliteration: ''),
    LyricStanza(startTimeMs: 960000, devanagari: 'भुजङ्गाख्यवृत्तेन कॢप्तं स्तवं यः\nपठेद्भक्तियुक्तो गुहं सम्प्रणम्य ।\nसुपुत्रान्कलत्रं धनं दीर्घमायु-\nर्लभेत्स्कन्दसायुज्यमन्ते नरः सः ॥ ३३॥', transliteration: ''),
    LyricStanza(startTimeMs: 990000, devanagari: '॥ इति श्रीमच्छङ्करभगवतः कृतौ\nश्रीसुब्रह्मण्यभुजङ्गं सम्पूर्णम् ॥', transliteration: ''),
  ],
  'irvls6Fhczw': [
    LyricStanza(startTimeMs: 0, devanagari: 'जय जय कमलासान जगमूला।\nरहहु सदा जनपै अनुकूला॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'रुप चतुर्भुज परम सुहावन।\nतुम्हें अहैं चतुर्दिक आनन॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'रक्तवर्ण तव सुभग शरीरा।\nमस्तक जटाजुट गंभीरा॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'ताके ऊपर मुकुट बिराजै।\nदाढ़ी श्वेत महाछवि छाजै॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'श्वेतवस्त्र धारे तुम सुन्दर।\nहै यज्ञोपवीत अति मनहर॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'कानन कुण्डल सुभग बिराजहिं।\nगल मोतिन की माला राजहिं॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'चारिहु वेद तुम्हीं प्रगटाये।\nदिव्य ज्ञान त्रिभुवनहिं सिखाये॥', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'ब्रह्मलोक शुभ धाम तुम्हारा।\nअखिल भुवन महँ यश बिस्तारा॥', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'अर्द्धांगिनि तव है सावित्री।\nअपर नाम हिये गायत्री॥', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'सरस्वती तब सुता मनोहर।\nवीणा वादिनि सब विधि मुन्दर॥', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'कमलासन पर रहे बिराजे।\nतुम हरिभक्ति साज सब साजे॥', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'क्षीर सिन्धु सोवत सुरभूपा।\nनाभि कमल भो प्रगट अनूपा॥', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'तेहि पर तुम आसीन कृपाला।\nसदा करहु सन्तन प्रतिपाला॥', transliteration: ''),
    LyricStanza(startTimeMs: 390000, devanagari: 'एक बार की कथा प्रचारी।\nतुम कहँ मोह भयेउ मन भारी॥', transliteration: ''),
    LyricStanza(startTimeMs: 420000, devanagari: 'कमलासन लखि कीन्ह बिचारा।\nऔर न कोउ अहै संसारा॥', transliteration: ''),
    LyricStanza(startTimeMs: 450000, devanagari: 'तब तुम कमलनाल गहि लीन्हा।\nअन्त बिलोकन कर प्रण कीन्हा॥', transliteration: ''),
    LyricStanza(startTimeMs: 480000, devanagari: 'कोटिक वर्ष गये यहि भांती।\nभ्रमत भ्रमत बीते दिन राती॥', transliteration: ''),
    LyricStanza(startTimeMs: 510000, devanagari: 'पै तुम ताकर अन्त न पाये।\nह्वै निराश अतिशय दुःखियाये॥', transliteration: ''),
    LyricStanza(startTimeMs: 540000, devanagari: 'पुनि बिचार मन महँ यह कीन्हा।\nमहापघ यह अति प्राचीन॥', transliteration: ''),
    LyricStanza(startTimeMs: 570000, devanagari: 'याको जन्म भयो को कारन।\nतबहीं मोहि करयो यह धारन॥', transliteration: ''),
    LyricStanza(startTimeMs: 600000, devanagari: 'अखिल भुवन महँ कहँ कोई नाहीं।\nसब कुछ अहै निहित मो माहीं॥', transliteration: ''),
    LyricStanza(startTimeMs: 630000, devanagari: 'यह निश्चय करि गरब बढ़ायो।\nनिज कहँ ब्रह्म मानि सुखपाये॥', transliteration: ''),
    LyricStanza(startTimeMs: 660000, devanagari: 'गगन गिरा तब भई गंभीरा।\nब्रह्मा वचन सुनहु धरि धीरा॥', transliteration: ''),
    LyricStanza(startTimeMs: 690000, devanagari: 'सकल सृष्टि कर स्वामी जोई।\nब्रह्म अनादि अलख है सोई॥', transliteration: ''),
    LyricStanza(startTimeMs: 720000, devanagari: 'निज इच्छा इन सब निरमाये।\nब्रह्मा विष्णु महेश बनाये॥', transliteration: ''),
    LyricStanza(startTimeMs: 750000, devanagari: 'सृष्टि लागि प्रगटे त्रयदेवा।\nसब जग इनकी करिहै सेवा॥', transliteration: ''),
    LyricStanza(startTimeMs: 780000, devanagari: 'महापघ जो तुम्हरो आसन।\nता पै अहै विष्णु को शासन॥', transliteration: ''),
    LyricStanza(startTimeMs: 810000, devanagari: 'विष्णु नाभितें प्रगट्यो आई।\nतुम कहँ सत्य दीन्ह समुझाई॥', transliteration: ''),
    LyricStanza(startTimeMs: 840000, devanagari: 'भैतहू जाई विष्णु हितमानी।\nयह कहि बन्द भई नभवानी॥', transliteration: ''),
    LyricStanza(startTimeMs: 870000, devanagari: 'ताहि श्रवण कहि अचरज माना।\nपुनि चतुरानन कीन्ह पयाना॥', transliteration: ''),
    LyricStanza(startTimeMs: 900000, devanagari: 'कमल नाल धरि नीचे आवा।\nतहां विष्णु के दर्शन पावा॥', transliteration: ''),
    LyricStanza(startTimeMs: 930000, devanagari: 'शयन करत देखे सुरभूपा।\nश्यायमवर्ण तनु परम अनूपा॥', transliteration: ''),
    LyricStanza(startTimeMs: 960000, devanagari: 'सोहत चतुर्भुजा अतिसुन्दर।\nक्रीटमुकट राजत मस्तक पर॥', transliteration: ''),
    LyricStanza(startTimeMs: 990000, devanagari: 'गल बैजन्ती माल बिराजै।\nकोटि सूर्य की शोभा लाजै॥', transliteration: ''),
    LyricStanza(startTimeMs: 1020000, devanagari: 'शंख चक्र अरु गदा मनोहर।\nशेष नाग शय्या अति मनहर॥', transliteration: ''),
    LyricStanza(startTimeMs: 1050000, devanagari: 'दिव्यरुप लखि कीन्ह प्रणामू।\nहर्षित भे श्रीपति सुख धामू॥', transliteration: ''),
    LyricStanza(startTimeMs: 1080000, devanagari: 'बहु विधि विनय कीन्ह चतुरानन।\nतब लक्ष्मी पति कहेउ मुदित मन॥', transliteration: ''),
    LyricStanza(startTimeMs: 1110000, devanagari: 'ब्रह्मा दूरि करहु अभिमाना।\nब्रह्मारुप हम दोउ समाना॥', transliteration: ''),
    LyricStanza(startTimeMs: 1140000, devanagari: 'तीजे श्री शिवशंकर आहीं।\nब्रह्मरुप सब त्रिभुवन मांही॥', transliteration: ''),
    LyricStanza(startTimeMs: 1170000, devanagari: 'तुम सों होई सृष्टि विस्तारा।\nहम पालन करिहैं संसारा॥', transliteration: ''),
    LyricStanza(startTimeMs: 1200000, devanagari: 'शिव संहार करहिं सब केरा।\nहम तीनहुं कहँ काज धनेरा॥', transliteration: ''),
    LyricStanza(startTimeMs: 1230000, devanagari: 'अगुणरुप श्री ब्रह्मा बखानहु।\nनिराकार तिनकहँ तुम जानहु॥', transliteration: ''),
    LyricStanza(startTimeMs: 1260000, devanagari: 'हम साकार रुप त्रयदेवा।\nकरिहैं सदा ब्रह्म की सेवा॥', transliteration: ''),
    LyricStanza(startTimeMs: 1290000, devanagari: 'यह सुनि ब्रह्मा परम सिहाये।\nपरब्रह्म के यश अति गाये॥', transliteration: ''),
    LyricStanza(startTimeMs: 1320000, devanagari: 'सो सब विदित वेद के नामा।\nमुक्ति रुप सो परम ललामा॥', transliteration: ''),
    LyricStanza(startTimeMs: 1350000, devanagari: 'यहि विधि प्रभु भो जनम तुम्हारा।\nपुनि तुम प्रगट कीन्ह संसारा॥', transliteration: ''),
    LyricStanza(startTimeMs: 1380000, devanagari: 'नाम पितामह सुन्दर पायेउ।\nजड़ चेतन सब कहँ निरमायेउ॥', transliteration: ''),
    LyricStanza(startTimeMs: 1410000, devanagari: 'लीन्ह अनेक बार अवतारा।\nसुन्दर सुयश जगत विस्तारा॥', transliteration: ''),
    LyricStanza(startTimeMs: 1440000, devanagari: 'देवदनुज सब तुम कहँ ध्यावहिं।\nमनवांछित तुम सन सब पावहिं॥', transliteration: ''),
    LyricStanza(startTimeMs: 1470000, devanagari: 'जो कोउ ध्यान धरै नर नारी।\nताकी आस पुजावहु सारी॥', transliteration: ''),
    LyricStanza(startTimeMs: 1500000, devanagari: 'पुष्कर तीर्थ परम सुखदाई।\nतहँ तुम बसहु सदा सुरराई॥', transliteration: ''),
    LyricStanza(startTimeMs: 1530000, devanagari: 'कुण्ड नहाइ करहि जो पूजन।\nता कर दूर होई सब दूषण॥', transliteration: ''),
  ],
  'j2zxoGoOHWw': [
    LyricStanza(startTimeMs: 0, devanagari: 'थारा हाथा माहि कलश,\nबड़ो भारी कवर तेजा हो,\nहाँ रे सावत सुरा ओ,\nधोरे धोरे आरती उतारा,\nतेजा थारी ओ।।', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'पेरयो थने कसुमल,\nजामो कवर तेजा हो,\nहाँ रे सावत सुरा ओ,\nधोरें धोरें आरती उतारां,\nतेजा थारी ओ।।', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'पेरयो थने कोट जरी को,\nकवर तेजा हो,\nहाँ रे सावत सुरा ओ,\nधोरें धोरें आरती उतारां,\nतेजा थारी ओ।।', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'बाँधी थने पचरंग पाग,\nकवर तेजा हो,\nहाँ रे सावत सुरा ओ,\nधोरें धोरें आरती उतारां,\nतेजा थारी ओ।।', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'थारे हाथां माहि सोरठणी,\nतलवार कवर तेजा हो,\nहाँ रे सावत सुरा ओ,\nधोरें धोरें आरती उतारां,\nतेजा थारी ओ।।', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'थारा गला माहि झूले,\nबासक राजा कवर तेजा हो,\nहाँ रे सावत सुरा ओ,\nधोरें धोरें आरती उतारां,\nतेजा थारी ओ।।', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'बेटो है तू जाट को ने,\nअमर कमायो नाम रे,\nअमर कमायो नाम रे,\nधोरें धोरें आरती उतारां,\nतेजा थारी ओ।।', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'खेड़े खेड़े देवली,\nबनावा कवर तेजा ओ,\nहाँ रे सावत सुरा ओ,\nधोरें धोरें आरती उतारां,\nतेजा थारी ओ।।', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'नौमी थारी रात,\nजगावा कवर तेजा ओ,\nहाँ रे सावत सुरा ओ,\nधोरें धोरें आरती उतारां,\nतेजा थारी ओ।।', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'दसमी को चूरमो,\nचढ़ावा कवर तेजा ओ,\nहाँ रे सावत सुरा ओ,\nधोरें धोरें आरती उतारां,\nतेजा थारी ओ।।', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'नौमी थारे दूध,\nचढ़ावा कवर तेजा ओ,\nहाँ रे सावत सुरा ओ,\nधोरें धोरें आरती उतारां,\nतेजा थारी ओ।।', transliteration: ''),
  ],
  'kG9rdaRI_pI': [
    LyricStanza(startTimeMs: 0, devanagari: 'श्रीललिता प्रातःस्तोत्रपञ्चकम्\nप्रातः स्मरामि ललितावदनारविन्दं बिम्बाधरं पृथुलमौक्तिकशोभिनासम् ।\nआकर्णदीर्घनयनं मणिकुण्डलाढ्यं मन्दस्मितं मृगमदोज्ज्वलभालदेशम् ॥ १॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'प्रातर्भजामि ललिताभुजकल्पवल्लीं रत्नाङ्गुळीयलसदङ्गुलिपल्लवाढ्याम् ।\nमाणिक्यहेमवलयाङ्गदशोभमानां पुण्ड्रेक्षुचापकुसुमेषुसृणीःदधानाम् ॥ २॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'प्रातर्नमामि ललिताचरणारविन्दं भक्तेष्टदाननिरतं भवसिन्धुपोतम् ।\nपद्मासनादिसुरनायकपूजनीयं पद्माङ्कुशध्वजसुदर्शनलाञ्छनाढ्यम् ॥ ३॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'प्रातः स्तुवे परशिवां ललितां भवानीं त्रय्यन्तवेद्यविभवां करुणानवद्याम् ।\nविश्वस्य सृष्टिविलयस्थितिहेतुभूतां विश्वेश्वरीं निगमवाङ्-मनसातिदूराम् ॥ ४॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'प्रातर्वदामि ललिते तव पुण्यनाम कामेश्वरीति कमलेति महेश्वरीति ।\nश्रीशाम्भवीति जगतां जननी परेति वाग्देवतेति वचसा त्रिपुरेश्वरीति ॥ ५॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'यः श्लोकपञ्चकमिदं ललिताम्बिकायाः सौभाग्यदं सुललितं पठति प्रभाते ।\nतस्मै ददाति ललिता झटिति प्रसन्ना विद्यां श्रियं विमलसौख्यमनन्तकीर्तिम् ॥ ६॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: '॥ इति श्रीमच्छङ्करभगवतः कृतौ ललिता पञ्चकं सम्पूर्णम् ॥', transliteration: ''),
  ],
  'n18vLugnsFA': [
    LyricStanza(startTimeMs: 0, devanagari: 'देवैः कृता एकलिङ्गशिवस्तुतिः\nदेवा ऊचुः -\nलोकानां त्वं सृष्टिकर्ता महेशः\nपाताऽमीषां भुवनानां हिताय ।\nसर्वस्यादिस्त्वं न कोऽपि त्वदादि-\nरीशो नेशस्त्वदृतेऽन्योऽस्ति भूयः ॥ २३॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'स्थूलः सूक्ष्मो व्यक्तव्यक्तेतरश्च\nदीर्घत्वेऽपि त्वं गुरुत्वे वृत्तोऽसि ।\nत्वं वै वन्द्यो नो तवैवास्ति वन्द्य\nआराध्यस्त्वं न त्वदाराधनीयः ॥ २४॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'धाता विश्वस्यापि धाता न तेऽस्ति\nपाता लोकस्यापि पाता न तेऽभूत् ।\nसंहर्ता त्वं संहरेत्त्वां न कश्चित्\nसर्वज्ञस्त्वं सर्वदा सर्वगोऽसि ॥ २५॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'विद्यां वेत्थ त्वां न विद्या विदन्ति\nदाता त्वं वै नैव दाता तवास्ति ।\nस्तुत्यो लोके स्तुत्य एवास्ति नो ते\nपूज्यो लोके नैव पूज्यस्तवास्ति ॥ २६॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'त्वं वै ब्रह्मा विष्णुरूपोऽमरेन्द्र-\nस्त्वं वै सूर्यस्त्वं च सोमो नभस्वान् ।\nपृथ्वी व्योम ह्यग्निरूपः प्रचेता\nभूतात्मा त्वं विश्वरूपस्त्वमेव ॥ २७॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'एतन्मुक्त्वा पावनं नैव कश्चिद्-\nभोज्यं भोक्ता ज्ञानवान् ज्ञानमग्र्यम् ।\nशास्ता शास्यं सृष्टिकर्ता च सृज्यं\nहव्यं होता यज्ञयाज्यस्त्वमाहुः ॥ २८॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'एतधीनं विद्यते नैव किञ्चिद्-\nहीनस्त्वं वा केनचिन्नैव शम्भो ।\nविद्यापूर्णस्तद्गुर्णस्तानपूर्णं\nसर्वं पश्येत्वां न पश्यन्ति केचित् ॥ २९॥', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'विश्वं तेऽन्तस्त्वं न तस्यान्तरीश\nतस्यादिस्त्वं नैव किञ्चित्तवादिः ।\nआधारस्त्वं न त्वदाधारतास्ति\nविश्वं रूपं नैव रूपं तवास्ति ॥ ३०॥', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'एको रुद्रो न द्वितीयस्तथाऽऽहुः\nपाताले वा चान्तरिक्षे च नाके ।\nवृक्षे तोये खे तडित्तोयदेषु\nकूपे वाथो सागरे ह्रत्सरित्सु ॥ ३१॥', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'देशे देशे लिङ्गरूपेण सर्वं\nगुहापाथः पर्वतेष्वाटवीषु ।\nक्षेत्रे सस्ये सर्ववस्तुस्वरूपं\nविश्वं धत्से सर्वमूर्ते नमस्ते ॥ ३२॥', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'सर्गादौ ये कर्मकारादयोऽपि\nशिल्पा ये त्वां नित्ययुक्ता यजन्ते ।\nआसङ्ख्येयैरात्मभिश्चैव सृष्टा\nयज्या पुत्रा औरसा विश्वमूर्ते ॥ ३३॥', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'तथा विप्रान् क्षत्रियान् वैश्यशूद्रान्\nअन्यान् स्वे स्वे कर्मणि त्वं नियुज्य ।\nराज्ञो नीत्या पालने यत्प्रजानां\nचातुर्वर्ण्यं वेदमार्गे निवेश्य ॥ ३४॥', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'ये ये भक्त्या त्वामुपासन्त ईश\nनेशं पापा मन्यमानाः कुतर्कैः ।\nते ते स्वैः स्वैः कर्मभिः पुण्यपापै-\nर्लिप्यन्ते वै नाभवत्तेष्वभेदः ॥ ३५॥', transliteration: ''),
    LyricStanza(startTimeMs: 390000, devanagari: 'त्वं वै ज्येष्ठो नैव ज्येष्ठास्तु ते ते\nवाचामीशस्त्वं न ते वाच ईशाः ।\nकाव्ये काव्ये त्वं कविर्नैव चान्यः\nकस्ते विन्द्यादेवमन्यो महिम्नः ॥ ३६॥', transliteration: ''),
    LyricStanza(startTimeMs: 420000, devanagari: 'दुष्टान् सर्वान् संहराश्वेकलिङ्ग\nपुष्पैर्बाणैः पञ्चकैराशु शम्भो ।\nम्लेच्छान् पापान् धर्ममार्गस्य शत्रून्\nबद्ध्वा शीघ्रं नागपाशेन दूरे ॥ ३७॥', transliteration: ''),
    LyricStanza(startTimeMs: 450000, devanagari: 'क्षिप्त्वा सर्वा देवताः सौम्यरूप\nत्राहि प्रीत्या सेवकान् विश्वमूर्ते ।\nसंसाराब्धौ पातितं विश्वमीक्ष्य\nधृत्वा हस्ते चाङ्कुशं तेन पाहि ॥ ३८॥', transliteration: ''),
    LyricStanza(startTimeMs: 480000, devanagari: 'इति एकलिङ्गमाहात्म्ये देवैः कृता एकलिङ्गशिवस्तुतिः सम्पूर्णा ।\n- ॥ एकलिङ्गमाहात्म्यम् । अष्टमोऽध्यायः - कामधेनुवरदानम् । ८.२३-३८॥', transliteration: ''),
  ],
  'nELD-UAZptI': [
    LyricStanza(startTimeMs: 0, devanagari: 'रणछोड तो रंगीलो नाथ, विश्व सकळ ने तारो साथ.\nभूमि केरो हरवा भार, जगमां प्रगट्यो वारंवार.\nजन्म धर्यो ते कारागार, जगतमां करवा चमत्कार.\nकंसरायने थाये जाण, तेथी कीधुं तरत प्रयाण.', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'गोकुळमां जई कीधो वास, नंद जशोदाजीनी पास.\nवर्णन करता ना आवे पार, एवी तारी लीला अपार,\nगोवाळोनी साथे जाय, गाय चरावी राजी थाय.\nछानो गोरस लूंटी खाय, पकडातामां छटकी जाय.', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'गोपीकाना चोर्या चित्त, सौना उपर सरखी प्रीत.\nबंसी केरो सुर मधुर, सुणनारा थाये चकचूर.\nशरद पूनमनी आवे रात, सौना हैये थाय प्रभात.\nव्रजवनिता छोडे आवास, दोडी आवे रमवा रास.', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'तारलिया चमके आकाश, चांदलियानो पूर्ण प्रकाश.\nदानव केरो ज्यां ज्यां त्रास, पळमां जईने कीधो नाश\nपटकी मार्यो मामो कंस, रह्यो न जगमां तेनो वंश\nकौरवोने कीधा तंग, पांडवोने राखी संग.', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'अर्जुनने ते कीधो बोध, ज्ञानामृतनो वरस्यो धोध.\nयुद्ध जीतीने कीधी दोड, नाम पड्युं तेथी रणछोड.\nद्वारिकामां कीधो वास, धर्म राजा फरके चोपास.\nगुजराते एक डाकोर गाम, भक्त थयो बोडाणो नाम.', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'पत्नी जेनी गंगाबाई, ते पण भक्तिमां रंगाई.\nहरतां फरतां गाये गान, मेळववा चाहे भगवान.\nतेवामां एक आव्यो संघ, रेलायो भक्तिनो रंग.\nयात्राळुओ द्रारिका जाय, बोडाणो तेमां जोडाय.', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'गोमतीजीमां कीधुं स्नान, भावे नीरख्या श्री भगवान.\nछ मासे आवीश हुं धाम, टेक एवी लीधी निष्काम.\nतुलसी वावी कायम जाय,प्रभुने अर्पी राजी थाय\nसहन करे ए कष्ट अमाप, भले पडे ठंडी के ताप.', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'वृध्ध थयो पण हैये हाम, अविचळ श्रद्धा आठो जाम.\nसित्तेर वर्ष वीत्यां छे एम, त्यारे पण पूरण थइ छे नेम.\nबोडाणो जीत्यो छे दाव, प्रभुना हैये प्रगट्यो भाव.\nहवे लावजे गाडुं साथ, बोल्यो विश्व सकळनो नाथ.', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'खडखडती लीधी छे वेल, वृध्ध थयेल जोड्या बेल.\nगंगाबाईए दीधी विदाय, बोडाणो हरखातो जाय\nबोडाणा रातो रात, मूक्या द्रारिकानी वाट.\nदर्शन करता कहे छे नाथ,गाडुं लाव्यो छुं हुं साथ.', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'गुगळीओ मनमां व्हेमाय, भक्त प्रभुने ना लई जाय.\nमार्या ताळां मजबूत द्रार, रात पडी ने वाग्या बार.\nवालो नीकळी नाठो बार, वेल तरत करी तैयार.\nगाडुं हांके जगदाधार, कहो पछी शुं लागे वार.', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'उमरेठ पकडी लीमडा डाळ, मीठी थइ गई ते तत्काळ.\nव्हाणुं वायुं वीती रात, डाकोर मांहे थयुं प्रभात.\nगंगाबाईए नीरख्या नाथ, उर उमळके जोड्या हाथ.\nडाकोर वरत्यो जय जयकार, द्वारीकामां हाहाकार.', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'द्वारिकाना राजानी साथ, गुगळी लेवा आव्या नाथ.\nभगत सामे लेवा जाय, मार्यो भालो मृत्यु थाय.\nभाविकोनां दिल दुःखाय, बदलो लेवा साम थाय.\nगंगाबाईए धीरज धरी, वहालमजीए विपत्त हरी.', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'गूगळी सोनुं लेवा धाय, वहालो वाळीए तोळाय.\nरीझ्यो विश्व सकळ कळनो भूप, मनसुखरामनुं लीधुं रूप.\nसंत पुनितने दीधी हाम, पूरण कीधां सघळां काम.\nरामभक्त जे करशे पाठ, नाथ झालशे तेनो हाथ.', transliteration: ''),
    LyricStanza(startTimeMs: 390000, devanagari: 'पूर्णिमाए प्रेमथी डाकोर दर्शन जाय\nरामभक्त ते पुनित बने कारज सघळां थाय', transliteration: ''),
  ],
  'pD6r2p7LNp0': [
    LyricStanza(startTimeMs: 0, devanagari: 'हे गुणागार , करुणावतार\nतेरी निर्मल छवी निराली\nकष्टों को मिटाने वाली\nहे दुख हरनी मंगल करणी....२', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'मही व्योम उतारे आरती\nदैत्य दलती सेवक को तारती', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'मचा त्राहीमाम , जब अमरधाम\nदेवों पर विपदा आई\nदुर्गा बनकर तूं धाई\nक्या खूब लड़ी , ले खंग खड़ी', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'असुरों के शीश उतारती\nदैत्य दलती सेवक को तारती', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'हे ममता मयी,तेरी अमिट छवी\nतूं मढ़ देशाण विराजे\nकर शूल सुदर्शन साजे\nहे भयभंजन हे जगरंजन', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'भगतो के काज सुधारती\nदैत्य दलती सेवक को तारती', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'हे दया सिंधू, मां दीनबंधु\nतेरी सकल जगत सकलाई\nसन्मुख हो करती सहाई\nजब भीर पड़े, मां सिंह चढ़े', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'विपदा से आन उबारती\nदैत्य दलती सेवक को तारती', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'जब धर्म घटा ,और पाप बढ़ा\nअवनी पर अंबा आई\nहरने सबकी विपदाई\nनत हो प्रांजल, रसना हर पल', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'तेरा ही नाम उचारती\nदैत्य दलती सेवक को तारती', transliteration: ''),
  ],
  'pZ_Qp2e8QK8': [
    LyricStanza(startTimeMs: 0, devanagari: 'जय हो तारो माँ, जय हो तारो माँ\nजय हो तारो माँ, जय हो तारो माँ\nहे माँ मेलडी हाथ जोडी करु तने वंदना\nतारा विना कोण समजे अंतरनी संवेदना', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'तुं दयाळी तुं कृपाळी आद्यशक्ति ईश्वरी\nमारण तारण एक तुज छे प्रणमु तने परमेश्वरी\nहे माँ मेलडी हाथ जोडी करु तने वंदना\nतारा विना कोण समजे अंतरनी संवेदना', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'अहीं तहीं भटकी रह्या ना मार्ग कोई सुझतो\nकुकर्मोनो वागेलो माडी घाव नथी रूझतो\nभुलो हशे लाखो अमारी माफ तमे करजो\nमने पापना पंथे जता माँ पाछो तमे वाळजो', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'हे माँ मेलडी हाथ जोडी करु तने वंदना\nतारा विना कोण समजे अंतरनी संवेदना', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'काम क्रोध लोभ कपटने हुं ईर्षानो भरेल छुं\nना माफी पामु एवा माडी कर्मोनो करेल छुं\nआ पापीने उगारो माडी दया तमे दाखवो\nतारा विना मारु कोण छे कोनो भरोसो राखवो', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'हे माँ मेलडी हाथ जोडी करु तने वंदना\nतारा विना कोण समजे अंतरनी संवेदना', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'आ पुराए ब्रह्माडमां माडी तमारु तेज छे\nआ विश्वने डोलाववुं तारा माटे सहेज छे\nतारी मरजी विना तो माडी कांईना थइ शके\nतुं धारे माँ जे करवा एने कोई ना रोकी शके', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'हे माँ मेलडी हाथ जोडी करु तने वंदना\nतारा विना कोण समजे अंतरनी संवेदना', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'तारा गुण गावा सात सागरनी शाही ओछी पडे\nतारी करुणाना किस्सा माडी हरघडी नवा जडे\nअनेक रूपो तारा छे माँ तुं छे हर एक अंशमां\nतुं सचराचर रमनारी त्रणे लोक तारा वशमां', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'हे माँ मेलडी हाथ जोडी करु तने वंदना\nतारा विना कोण समजे अंतरनी संवेदना', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'मतलबी आ जगत छे ने संबंध सहु खोखला\nतारा विना उगर्याना माडी नथी कोई दाखला\nअनेक जनने तार्या छे माँ मुजने तारो तमे\nआरो नथी हवे कोई तारा शरणे आव्या अमे', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'हे माँ मेलडी हाथ जोडी करु तने वंदना\nतारा विना कोण समजे अंतरनी संवेदना', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'आधार एक तारो छे माँ एक तारो आशरो\nडुबती आ नैया तारजो पुण्यना प्रकाश पाथरो\nजेवो गणो तेवो ओ माता हुं तमारो बाळ छुं\nबळदेव कहे माँ तारा विना हुं तो निराधार छुं', transliteration: ''),
    LyricStanza(startTimeMs: 390000, devanagari: 'हे माँ मेलडी हाथ जोडी करु तने वंदना\nतारा विना कोण समजे अंतरनी संवेदना\nतारा विना कोण समजे अंतरनी संवेदना', transliteration: ''),
  ],
  'qUMC92hQT1A': [
    LyricStanza(startTimeMs: 0, devanagari: 'ऊँडे पाणी नदियाँ उतरंतां, झड़ मंडिया खग झाटां,\nशक्ति कीजै सहाय शेवगां, बहतां घाटां बाटां।', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'मेवाशा मांझल ठग, मिलियां, नाहर आयां नेड़ां,\nकुशल आपरा राखे करनी, बहतां शायर बेड़ां।', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'बैरी विषधर सर्प निवारे, बळती लाय बुझावे.\nलोवड़ियाल तणा भुज लम्बा, आंचळ दीशा आवे।', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'डाकण भूत कुवे पग डिगतां कड़के बीज अकाशां,\nकरतां याद मेहाशदु करनी! देवि उबारो दासां।', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'बड़ांबड़ी किनियाणी बांका, पोख पूजगां पाळे,\nदेश विदेश मांहि डाढाळी, राज दुवार रुखाळे।', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'मौत कुमौत टाळणां अम्बा, कुमति निवारण माता,\nसुमति देण दारिद्रय नसावण, राखे तन सुख-साता।', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'बीशभुजा रुखवाळे शेवग, बाळक छत्तर छाया,\nटेम कुटेम टाळणीं अम्बा, दुख भाजे दुख आयां|', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'रात दिनां पल छिन मो जगदम्ब! रहजो आप सहाई,\nपूत कपूत क्षमा कर दुर्गा, बिरद निभाज्यो बाई।\nजय श्री करणी माता', transliteration: ''),
  ],
  'rAWoHu96SNM': [
    LyricStanza(startTimeMs: 0, devanagari: 'अथ त्रिपुरसुन्दरी अष्टकम् ।\nकदम्बवनचारिणीं मुनिकदम्बकादम्बिनीं\nनितम्बजित भूधरां सुरनितम्बिनीसेविताम् ।\nनवाम्बुरुहलोचनामभिनवाम्बुदश्यामलां\nत्रिलोचनकुटुम्बिनीं त्रिपुरसुन्दरीमाश्रये ॥ १॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'कदम्बवनवासिनीं कनकवल्लकीधारिणीं\nमहार्हमणिहारिणीं मुखसमुल्लसद्वारुणीम् ।\nदयाविभवकारिणीं विशदलोचनीं चारिणीं\nत्रिलोचनकुटुम्बिनीं त्रिपुरसुन्दरीमाश्रये ॥ २॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'कदम्बवनशालया कुचभरोल्लसन्मालया\nकुचोपमितशैलया गुरुकृपालसद्वेलया ।\nमदारुणकपोलया मधुरगीतवाचालया\nकयाऽपि घननीलया कवचिता वयं लीलया ॥ ३॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'कदम्बवनमध्यगां कनकमण्डलोपस्थितां\nषडम्बुरुहवासिनीं सततसिद्धसौदामिनीम् ।\nविडम्बितजपारुचिं विकचचंद्रचूडामणिं\nत्रिलोचनकुटुम्बिनीं त्रिपुरसुन्दरीमाश्रये ॥ ४॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'कुचाञ्चितविपञ्चिकां कुटिलकुन्तलालंकृतां\nकुशेशयनिवासिनीं कुटिलचित्तविद्वेषिणीम् ।\nमदारुणविलोचनां मनसिजारिसंमोहिनीं\nमतङ्गमुनिकन्यकां मधुरभाषिणीमाश्रये ॥ ५॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'स्मरप्रथमपुष्पिणीं रुधिरबिन्दुनीलाम्बरां\nगृहीतमधुपात्रिकां मदविघूर्णनेत्राञ्चलाम् ।\nघनस्तनभरोन्नतां गलितचूलिकां श्यामलां\nत्रिलोचनकुटुंबिनीं त्रिपुरसुन्दरीमाश्रये ॥ ६॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'सकुङ्कुमविलेपनामलकचुंबिकस्तूरिकां\nसमन्दहसितेक्षणां सशरचापपाशाङ्कुशाम् ।\nअशेषजनमोहिनीमरुणमाल्य भूषाम्बरां\nजपाकुसुमभासुरां जपविधौ स्मराम्यम्बिकाम् ॥ ७॥', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'पुरन्दरपुरन्ध्रिका चिकुरबन्धसैरंध्रिकां\nपितामहपतिव्रता पुटपटीरचर्चारताम् ।\nमुकुन्दरमणीमणीलसदलङ्क्रियाकारिणीं\nभजामि भुवनांबिकां सुरवधूटिकाचेटिकाम् ॥ ८॥', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: '॥ इति श्रीमद् शङ्कराचार्यविरचितं\nत्रिपुरसुन्दर्यष्टकं समाप्तम् ॥\nकदम्बवनवासिनी स्तोत्रम् च', transliteration: ''),
  ],
  'rcqh5H1tmMA': [
    LyricStanza(startTimeMs: 0, devanagari: '।।श्री घंटा कर्ण चालीसा ।। समकित वंत महाबली धनुष बाण है हाथ।\nसंकट चूरे दुख हरे भक्तन को दे साथ। वीर बड़ा महावीर बखानू।\nअंतः करण से शीश नवाऊं मनमंदिर मोहि पधराऊ घंटाकर्ण चालीसा गाऊं\nअरिदमन राजा दरसाई समरांगन के मोहि आई सांध्यकाल लालिमा छाई घंटाराव का शब्द सुनाई', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'दोनो बीच है युद्ध युद्धाई\nखींचा तीर है बाण बढ़ाई वीरगति अंते उपजाई\nबाण व्यंतरी सुर गति पाईं अवधी ज्ञान पूर्व भव जाना समकित वंत बना मतवाला जिनशासन का रक्षक धोरी वंदन करूं हाथ बे जोड़ी।\nनाम तुम्हारा अंतर ध्यावे', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'जीवन में संकट नहीं आवे\nदुख दरिद्रता दूर भगावे सतचित आनंदमय बन जावे भक्तजनों का तू हित कारा।\nजैन धर्म का पूर्ण प्रचारा ।\nश्रद्धा सुमन चढ़ाने आते', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'महुड़ी में आकर गुण गाते।\nभूत पिशाच व्यंतरि आवे तेरे नाम से झट भग जावे। याल व्याल विकराल जावे\nअंतर में ज्योति प्रगट आवे।\nजादू टोना या नजराना', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'जीवन में नहीं ताना-बाना।\nएक सहारा वीर तुम्हारा प्रतिफल देना साथ हमारा।\nरोगजल जलंधरऔर भगंदर\nतीन ताप भय भरा समंदर।', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'इन सब को तू दूर निवारे।\nभक्तन की वीर चढ़ आवे ।\nकोढ़ कराल का दाग मिटाने विषधारी विष दूर भगावे।\nजीवन जन आदर्श बनावे', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'जन जन के झट भाग्य जगावे।\nराज्य विपत्ति सिर पे ना छावे बंधन का कोई जोर ना जतावे। जय जय मंगल लीला पावे\nघंटा कर्ण वीर गुण गावे।\nशक्तिशाली वीर कहावे', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'रिद्धि वृद्धि भंडार भरावे ।\nपुत्र पौत्र धन-धान्य सुहावे कलिमल कर मेल मिट जावे।\nमुकुट मनोहर सर पर छाजे कानों में कुंडल अभिराजे।\nहार हुसीलो गलविच माहे।', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'दिव्य देव श्रृंगार संजोटे ।\nवीर खड़ा है वीरासन में।\nभव्य माल मलके आनन में\nवीर है बावन तेरे सखाई', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'सब सिद्धि तुझ में है समाई ।\nजिनशासन का रक्षक तू है साधर्मी का साधन तू है।\nनित उठ तेरी सेवा सजाऊ हरदम अपने मन में बसाऊं।\nनाम लिया सिद्धि मिल जावे मनवांछित इच्छित फल पावे। महामंत्र चालीसा तुम्हारा।', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'प्रबल पुण्य बढ़ता धन सारा ।\nविजय पताका फहरा जग में जय-जय कीर्ति बढ़े रग रग में। आशा पूरे सहूजन मन की\nपीड़ा दूर होय सब तन की।\nमृत्यु लोक में विचरे विहारी तेरी शोभा अपरंपाररी । सच्चा दिल सुन ध्यान धरणता भवसागर से तिमिर हटनता। धीर वीर गंभीर उदारा', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'तेरे द्वारा धर्म प्रचारा\nनित उठ जो चालीसा गावे।\nवह नर वांछित फल ने पावे', transliteration: ''),
  ],
  'vOJVCT5U3dg': [
    LyricStanza(startTimeMs: 0, devanagari: 'ओम जय श्री जीण मइया, बोलो जय श्री जीण मइया ।\nसच्चे मन से सुमिरे, सब दुःख दूर भया ॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'ओम जय श्री जीण मइया।\nऊंचे पर्वत मंदिर, शोभा अति भारी ।\nदेखत रूप मनोहर, असुरन भयकारी ॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'ओम जय श्री जीण मइया।\nमहासिंगार सुहावन, ऊपर छत्र फिरे ।\nसिंह की सवारी सोहे, कर में खड़ग धरे ॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'ओम जय श्री जीण मइया।\nबाजत नौबत द्वारे, अरु मृदंग डैरु ।\nचौसठ जोगन नाचत, नृत्य करे भैरू ॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'ओम जय श्री जीण मइया।\nबड़े बड़े बलशाली, तेरा ध्यान धरे ।\nऋषि मुनि नर देवा, चरणो आन पड़े ॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'ओम जय श्री जीण मइया।\nजीण माता की आरती, जो कोई जन गावे ।\nकहत रूड़मल सेवक, सुख सम्पति पावे ॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'ओम जय श्री जीण मइया ।\nओम जय श्री जीण मइया, बोलो जय श्री जीण मइया ।\nसच्चे मन से सुमिरे, सब दुःख दूर भया ॥\nओम जय श्री जीण मइया।', transliteration: ''),
  ],
  'vWKD3Q3LxsA': [
    LyricStanza(startTimeMs: 0, devanagari: 'निवासं गिरौ सुर्कुटे वन्दनीये बुरांशादिवृक्षैस्तृणैर्छादितं च ।\nप्रसादं च यस्याः शुभां रांसुली वा,\nनमामीति लोके प्रसिद्धां श्रीकंठां ।।३', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: '(उनका निवास स्थान सुरकुट नामक सुन्दर स्थान में एक पर्वत पर है और वह घास तथा अन्य बुरांश , देवदार आदि वृक्षों से ढका हुआ है।\nऔर रांसुली वृक्ष की कलियां ही जिसके धाम का प्रसाद (कृपा ) और सुफल है,\nउन विश्वविख्यात श्रीकंठा (सुरकंडा सुरी) देवि को मैं प्रणाम करता हूँ\nजगत्वैभवीं मातरं नौमि तुभ्यं\nया सेविता पूजिता लेखवारै: ।\nजगत्तारिणीं देवि गिर्यात्मजां त्वां\nनमो देवि तुभ्यं सदा सिद्धपीठम् ||४||', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'जगतजननी, मैं तुम्हें प्रणाम करता हूँ\nहे देवी तुम पर्वतपुत्री हो जो संसार का उद्धार करती हो\nहे देवी, सिद्धपीठ सुरकंडा, मैं आपको सदैव नमस्कार करता हूँ\nन जानामि मन्त्रं न जानामि तन्त्रं\nन जानामि सेवां न वा कर्मकाण्डम्।\nन जानामि पुण्यं न जानामि ध्यानं\nजानामि जडधारिणां देवि सम्यक् ॥ ५', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'मैं मंत्र नहीं जानता, मैं तंत्र नहीं जानता\nमैं सेवा या अनुष्ठान नहीं जानता।\nमैं गुण नहीं जानता, मैं साधना नहीं जानता\nमैं तो जड़धारियों की देवि सुरकंडा को भलीभांति जानता हूं जो सिद्धिदात्री हैं।\n६). विदेशे च देशे जले वा स्थले च\nप्रवासे च मार्गे तथा चैव गेहे\nचतुर्दिक् विपत्तौ तथा शत्रुमध्ये\nसती शैलपुत्री सुरी पातु नित्यम् ||६||', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'हे देवी देश-विदेश में, जल - थल पर\nप्रवासे में और घर पर हर तरफ मुसीबत में और दुश्मन के बीच में सती शैलपुत्री सूरी सदैव मेरी रक्षा करें\nदुःखार्तो क्षुधार्त: प्रलोभी -प्रमत्तः\nकृतघ्नी च कोधी कुपुत्रश्च वन्ध्या ।\nदरिद्र: कुलघ्नी कुमार्गी कुबुद्धि:\nभजन्तीह लोके पराम्बा भवानीम्॥ ७', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'हे देवी दुखी कष्टापन्न , भूखे , वंचित, कृतघ्न, क्रोधी, दुष्ट पुत्र वाले हों या अपुत्र हों ।अथवा गरीब: , पथभ्रष्ट, कुबुद्धि हों\nवे भी इस संसार में देवी पराम्बा की पूजा उपासना कर देवि की कृपा से सुख- संपन्नता व ऐश्वर्य प्राप्त करते हैं ।7\nनमस्ते - नमस्ते सदा दिव्यरूपा नमस्ते-नमस्ते सदा कांतरूपा।\nनमस्ते-नमस्ते सदा भव्यरूपा\nनमस्ते नमस्ते सदा सुरकण्डा ॥ ८', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'सदैव दिव्य स्वरूप वाली देवि को प्रणाम, सदैव सुन्दर स्वरूपवाली देवि को प्रणाम।\nहमेशा शानदार अप्रतिम सौंदर्य की देवि को प्रणाम, जगज्जननी सुरकंडा को प्रणाम।\nप्रवीणेन कृतं स्तोत्रं दिव्यभावसमन्वितम्।\nये पठन्ति नरा भक्त्या, तेषां शक्ति: प्रसीदति ॥', transliteration: ''),
  ],
  'v_iqaLhRkUM': [
    LyricStanza(startTimeMs: 0, devanagari: 'वंदो प्रभु श्री रामदेव के, चरण कमल चित्त लाय,\nअर्थ धर्मप्रद, मोक्षफल, बिनु प्रयास मिल जाय', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'जय अजमल सुत, जय सुखधामा, भवसागर हित बोहित नामा\nजय मेंणादे के दग तारे, जय जय नेतल प्राण पियारे', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'चौदहसो इकसठ शनिवारा, भादों दूज शुक्ल पखवारा\nलियो द्वारकापति अवतारा, प्रगटे रण भूमि भय भारा', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'पोढे प्रभु पलना में आई, दुइ सुत देखा मातु घबडाई\nचमत्कार प्रभु प्रथम दिखावा, पय उफनत कर बढा उठावा', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'धनि माया-पति धन्य निकई, रूप राशि गुण वरणि न जाई\nधन्य पोकरण पावनधामा, खेले जहां स्वंय श्रीराम', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'माया पति माया रुचिराई, नैन पाय सोनित हर्षाई\nकपडे के घोडा ऊड धाये, दर्जी के प्रभु बंध छुडाये', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'सखा संग खेले हरिराई, गेंद भेरवा भूमि पठाई\nखोजत गेंद चले श्रीरामा, पहुंचे बालीनाथ सुधामा', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'बालीनाथ गेंद पकराई, कहा पुत्र तुम जाउ पराई\nश्री गुरु बालीनाथ बनाये, जिन कंथा निज हाथ उठाये', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'कंथा कीचत भैरव हारा, प्रभु माया वश मिले न पारा\nतब प्रभु कियो वेष विकराला, चढ लीलुडे कर ले भाला', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'भैरव माया बहुत दिखाई, चली न प्रभु सन्मुख चतुराई\nभैरव भीम काय विकराला, हनेउ तुरत प्रभु दीनदयाला', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'जय भक्तन हित प्रभु दनुजरी, कृपा सिन्धु सन्तन सुखकारी\nदैत्य मार प्रभु गुरु पहं आये, विनय कीन्ह मृदु बचन सुहाये', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'कृपा आपकी दैत्य संहारा, तब गुरु आशिष वचन उचारा\nवत्स दैत्य यह भूमि उजारी, नगर बसाय करो सुखकारी', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'गुरूआज्ञा प्रभु नगर बसावा, नगर रुणीचा नाम धरावा\nकृपा बोयता पर प्रभु कीन्ही, डुबत नाव सिन्धु तर दीन्ही', transliteration: ''),
    LyricStanza(startTimeMs: 390000, devanagari: 'भक्त पुकार कान में आई, ध्यान रूप पहुंचे हरिराई\nसदा सत्य पथ तुमहिं सुहावा, प्रभु मिश्री को लवण बनावा', transliteration: ''),
    LyricStanza(startTimeMs: 420000, devanagari: 'बणजारा लाखा घबडायो, प्रभु की शरण दौड कर आयो\nक्षमा कीन्ह प्रभु दया निकेता, मिश्री बना लवण था जेता', transliteration: ''),
    LyricStanza(startTimeMs: 450000, devanagari: 'पांच पीर मक्का से आये, देख प्रथम प्रभु को चकराये\nमृत स्वार्थीयो जीवित कीन्हो, पीरन पीर मान प्रभु लीन्हो', transliteration: ''),
    LyricStanza(startTimeMs: 480000, devanagari: 'को जग में प्रभु पर्चन हारा, माया पति गुण सिंधु अपारा\nप्रभुने भोजन पात्र मंगाये, मक्कासे पलमें चले आये', transliteration: ''),
    LyricStanza(startTimeMs: 510000, devanagari: 'एक देगमे विविध प्रकार, पीरन रुचि-रुचि कीन्ह आहारा\nगर्व कियो पढिहारन भारी, सह न सके प्रभु नेजाधारी', transliteration: ''),
    LyricStanza(startTimeMs: 540000, devanagari: 'मद मेटत प्रभु विलम्ब न लाये, रतना के जा फंद छुडाये\nजभ्भा को परिचय बतलायो, खारो सर्वर नीर बनायो', transliteration: ''),
    LyricStanza(startTimeMs: 570000, devanagari: 'प्रभु नेजा धरती में मार्यो, फोड धरा को नीर निकार्यो\nलूंटी चोरन सुगना बाई, चढ लीलुडे जाय बचाई', transliteration: ''),
    LyricStanza(startTimeMs: 600000, devanagari: 'सगुनको उदास जब पायो, शीघ्र बापजी पुत्र जिवायो\nदला शेठ को आप निरंजन, कटे शीश में डाला जीवन', transliteration: ''),
    LyricStanza(startTimeMs: 630000, devanagari: 'अलख निरंजन नेजाधारी, किये दूर भक्त दुःख भारी\nदिन दयाळु, कृपाळु रामा, करे भक्त के पूर्ण कामा', transliteration: ''),
    LyricStanza(startTimeMs: 660000, devanagari: 'तुम कलियुग के प्रत्यक्ष देवा, करे संत सुर चरणन सेवा\nजो नित्य ऊठ चालीसा गावे, ताके प्रभु सब काम बनावे', transliteration: ''),
    LyricStanza(startTimeMs: 690000, devanagari: 'जो ईच्छा मन में जब लाते, प्रभु की कृपा सफलता पाते\nआधि-व्याधि सब संकटहारी, प्रभु को नाम सदा सुखकारी', transliteration: ''),
    LyricStanza(startTimeMs: 720000, devanagari: 'जिन पर प्रभु करुणा करी रंक बनाये राय,\nथोडी सेवा से रीझते, कोमल सरल सुभाय', transliteration: ''),
  ],
  'vzHdO0Jcsk8': [
    LyricStanza(startTimeMs: 0, devanagari: 'जय मोमाई माता, ॐ जय मोमाई माता,\nआरती गाता तमारी, हैया हरखाता,\nॐ जय मोमाई माता', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'लाखो दिवडा जळहळ बळता,तेज तणो नहीं पार,\nमैया तेज तणो नहीं पार,\nदिव्य अलौकिक आभा, विजळीनो चमकार,\nॐ जय मोमाई माता', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'मंगलकारी मुर्ति तमारी, मंदिरमां शोभे,\nमैया मंदिरमां शोभे,\nदर्शन करवा तमारा, मन सौनु लोभे,\nॐ जय मोमाई माता', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'ढोल नगारा शरणायुंने, झालरनो झणकार,\nमैया झालरनो झणकार,\nमीठा सूर मोरलीना, करता एकाकार,\nॐ जय मोमाई माता', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'अनेक रूपे एक तमे छो, परचा माँ पुरनार,\nमैया परचा माँ पुरनार,\nमहीमा तमारो मोटो, जगमां जय जयकार,\nॐ जय मोमाई माता', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'सचराचरमां वास करो छो, माता ममताळी,\nमैया माता ममताळी,\nसमरे वेला आवो, करवा रखवाळी,\nॐ जय मोमाई माता', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'भवसागरमां भटकेलाने, पलमां माँ तारे,\nमैया पलमां माँ तारे,\nपापी पावन थाता, माँ तारा घ्वारे,\nॐ जय मोमाई माता', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'आदी अनादी मात तमे छो, वेदोमां वखणातां,\nमैया वेदोमां वखणातां,\nदेवो,दानव,मानव,गुण तारा गाता,\nॐ जय मोमाई माता', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'अमी भरेली आंखोथी,माँ अमृत वरसावो,\nमैया अमृत वरसावो,\nसुना पडेला जीवनमां खुशीयो लहेरावो,\nॐ जय मोमाई माता', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'फोरमता फुलडानो हुं तो, फुलगजरो लावुं,\nमैया फुलगजरो लावुं,\nहैयाना हेतेथी माँ तमने पहेरावुं,\nॐ जय मोमाई माता', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'श्वासे श्वासे समरण करतो, अतुल तमारो दास,\nमैया अतुल तमारो दास,\nभक्तोने दर्शन आपो, पुरण करो माँ आश,\nॐ जय मोमाई माता', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'जय मोमाई माता, ॐ जय मोमाई माता,\nआरती गाता तमारी, हैया हरखाता,\nॐ जय मोमाई माता, ॐ जय मोमाई माता,\nॐ जय मोमाई माता, ॐ जय मोमाई माता,', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'ॐ जय मोमाई माता.\nबोलीए मोमाई मातकी जय...', transliteration: ''),
  ],
  'wvw6pBcviLo': [
    LyricStanza(startTimeMs: 0, devanagari: 'देवि सुरेश्वरि भगवति गङ्गे त्रिभुवनतारिणि तरलतरङ्गे ।\nशङ्करमौलिविहारिणि विमले मम मतिरास्तां तव पदकमले ॥ १॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'भागीरथि सुखदायिनि मातस्तव जलमहिमा निगमे ख्यातः ।\nनाऽहं जाने तव महिमानं पाहि कृपामयि मामज्ञानम् ॥ २॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'हरिपदपाद्यतरङ्गिणि गङ्गे हिमविधुमुक्ताधवलतरङ्गे ।\nदूरीकुरु मम दुष्कृतिभारं कुरु कृपया भवसागरपारम् ॥ ३॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'तव जलममलं येन निपीतं परमपदं खलु तेन गृहीतम् ।\nमातर्गङ्गे त्वयि यो भक्तः किल तं द्रष्टुं न यमः शक्तः ॥ ४॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'पतितोद्धारिणि जाह्नवि गङ्गे खण्डितगिरिवरमण्डितभङ्गे ।\nभीष्मजननि हे मुनिवरकन्ये पतितनिवारिणि त्रिभुवनधन्ये ॥ ५॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'कल्पलतामिव फलदाम् लोके प्रणमति यस्त्वां न पतति शोके ।\nपारावारविहारिणि गङ्गे विमुखयुवतिकृततरलापाङ्गे ॥ ६॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'तव चेन्मातः स्रोतः स्नातः पुनरपि जठरे सोऽपि न जातः ।\nनरकनिवारिणि जाह्नवि गङ्गे कलुषविनाशिनि महिमोत्तुङ्गे ॥ ७॥', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'पुनरसदङ्गे पुण्यतरङ्गे जय जय जाह्नवि करुणापाङ्गे ।\nइन्द्रमुकुटमणिराजितचरणे सुखदे शुभदे भृत्यशरण्ये ॥ ८॥', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'रोगं शोकं तापं पापं हर मे भगवति कुमतिकलापम् ।\nत्रिभुवनसारे वसुधाहारे त्वमसि गतिर्मम खलु संसारे ॥ ९॥ गतिर्मय\nअलकानन्दे परमानन्दे कुरु करुणामयि कातरवन्द्ये ।\nतव तटनिकटे यस्य निवासः खलु वैकुण्ठे तस्य निवासः ॥ १०॥', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'वरमिह नीरे कमठो मीनः किं वा तीरे शरटः क्षीणः ।\nअथवा श्वपचो मलिनो दीनस्तव न हि दूरे नृपतिकुलीनः ॥ ११॥', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'भो भुवनेश्वरि पुण्ये धन्ये देवि द्रवमयि मुनिवरकन्ये ।\nगङ्गास्तवमिमममलं नित्यं पठति नरो यः स जयति सत्यम् ॥ १२॥', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'येषां हृदये गङ्गाभक्तिस्तेषां भवति सदा सुखमुक्तिः ।\nमधुराकान्तापञ्झटिकाभिः परमानन्दकलितललिताभिः ॥ १३॥', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'गङ्गास्तोत्रमिदं भवसारं वाञ्छितफलदम् विमलं सारम् ।\nशङ्करसेवकशङ्कररचितं पठति सुखीस्तव इति च समाप्तः ॥ १४॥', transliteration: ''),
    LyricStanza(startTimeMs: 390000, devanagari: '॥ इति श्रीमच्छङ्कराचार्यविरचितं गङ्गास्तोत्रं सम्पूर्णम् ॥', transliteration: ''),
  ],
  'yY13vYa5_cM': [
    LyricStanza(startTimeMs: 0, devanagari: 'गंगालहरी\nसमृद्धं सौभाग्यं सकलवसुधायाः किमपि तन्\nमहैश्वर्यं लीलाजनितजगतः खण्डपरशोः ।\nश्रुतीनां सर्वस्वं सुकृतमथ मूर्तं सुमनसां\nसुधासोदर्यं ते सलिलमशिवं नः शमयतु ॥ १॥', transliteration: ''),
    LyricStanza(startTimeMs: 30000, devanagari: 'दरिद्राणां दैन्यं दुरितमथ दुर्वासनहृदां\nद्रुतं दूरीकुर्वन् सकृदपि गतो दृष्टिसरणिम् ।\nअपि द्रागाविद्याद्रुमदलनदीक्षागुरुरिह\nप्रवाहस्ते वारां श्रियमयमपारां दिशतु नः ॥ २॥', transliteration: ''),
    LyricStanza(startTimeMs: 60000, devanagari: 'उदञ्चन्मार्तण्डस्फुटकपटहेरम्बजननी-\nकटाक्षव्याक्षेपक्षणजनितसंक्षोभनिवहाः ।\nभवन्तु त्वङ्गन्तो हरशिरसि गङ्गातनुभुव-\nस्तरङ्गाः प्रोत्तुङ्गा दुरितभयभङ्गाय भवताम् ॥ ३॥', transliteration: ''),
    LyricStanza(startTimeMs: 90000, devanagari: 'तवालम्बादम्ब स्फुरदलघुगर्वेण सहसा\nमया सर्वेऽवज्ञासरणिमथ नीताः सुरगणाः ।\nइदानीमौदास्यं भजसि यदि भागीरथि तदा\nनिराधारो हा रोदिमि कथय केषामिह पुरः ॥ ४॥', transliteration: ''),
    LyricStanza(startTimeMs: 120000, devanagari: 'स्मृतिं याता पुंसामकृतसुकृतानामपि च या\nहरत्यन्तस्तन्द्रां तिमिरमिव चन्द्रांशुसरणिः ।\nइयं सा ते मूर्तिः सकलसुरसंसेव्यसलिला\nममान्तःसन्तापं त्रिविधमपि पापं च हरताम् ॥ ५॥', transliteration: ''),
    LyricStanza(startTimeMs: 150000, devanagari: 'अपि प्राज्यं राज्यं तृणमिव परित्यज्य सहसा\nविलोलद्वानीरं तव जननि तीरं श्रितवताम् ।\nसुधातः स्वादीयस्सलिलभरमातृप्ति पिबतां\nजनानामानन्दः परिहसति निर्वाणपदवीम् ॥ ६॥', transliteration: ''),
    LyricStanza(startTimeMs: 180000, devanagari: 'प्रभाते स्नातीनां नृपतिरमणीनां कुचतटी-\nगतो यावन्मातर्मिलति तव तोयैर्मृगमदः ।\nमृगास्तावद्वैमानिकशतसहस्रैः परिवृता\nविशन्ति स्वच्छन्दं विमलवपुषो नन्दनवनम् ॥ ७॥', transliteration: ''),
    LyricStanza(startTimeMs: 210000, devanagari: 'स्मृतं सद्यः स्वान्तं विरचयति शान्तं सकृदपि\nप्रगीतं यत्पापं झटिति भवतापं च हरति ।\nइदं तद्गङ्गेति श्रवणरमणीयं खलु पदं\nमम प्राणप्रान्ते वदनकमलान्तर्विलसतु ॥ ८॥', transliteration: ''),
    LyricStanza(startTimeMs: 240000, devanagari: 'यदन्तः खेलन्तो बहुलतरसन्तोषभरिता\nन काका नाकाधीश्वरनगरसाकाङ्क्षमनसः ।\nनिवासाल्लोकानां जनिमरणशोकापहरणं\nतदेतत्ते तीरं श्रमशमनधीरं भवतु नः ॥ ९॥', transliteration: ''),
    LyricStanza(startTimeMs: 270000, devanagari: 'न यत्साक्षाद्वेदैरपि गलितभेदैरवसितं\nन यस्मिन् जीवानां प्रसरति मनोवागवसरः ।\nनिराकारं नित्यं निजमहिमनिर्वासिततमो\nविशुद्धं यत्तत्त्वं सुरतटिनि तत्त्वं न विषयः ॥ १०॥', transliteration: ''),
    LyricStanza(startTimeMs: 300000, devanagari: 'महादानैर्ध्यानैर्बहुविधवितानैरपि च यन्\nन लभ्यं घोराभिः सुविमलतपोराशिभिरपि ।\nअचिन्त्यं तद्विष्णोः पदमखिलसाधारणतया\nददाना केनासि त्वमिह तुलनीया कथय नः ॥ ११॥', transliteration: ''),
    LyricStanza(startTimeMs: 330000, devanagari: 'नृणामीक्षामात्रादपि परिहरन्त्या भवभयं\nशिवायास्ते मूर्तेः क इह महिमानं निगदतु ।\nअमर्षम्लानायाः परममनुरोधं गिरिभुवो\nविहाय श्रीकण्ठः शिरसि नियतं धारयति याम् ॥ १२॥', transliteration: ''),
    LyricStanza(startTimeMs: 360000, devanagari: 'विनिन्द्यान्युन्मत्तैरपि च परिहार्याणि पतितै-\nरवाच्यानि व्रात्यैः सपुलकमपास्यानि पिशुनैः ।\nहरन्ती लोकानामनवरतमेनांसि कियतां\nकदाप्यश्रान्ता त्वं जगति पुनरेका विजयसे ॥ १३॥', transliteration: ''),
    LyricStanza(startTimeMs: 390000, devanagari: 'स्खलन्ती स्वर्लोकादवनितलशोकापहृतये\nजटाजूटग्रन्थौ यदसि विनिबद्धा पुरभिदा ।\nअये निर्लोभानामपि मनसि लोभं जनयतां\nगुणानामेवायं तव जननि दोषः परिणतः ॥ १४॥', transliteration: ''),
    LyricStanza(startTimeMs: 420000, devanagari: 'जडानन्धान् पङ्गून् प्रकृतिबधिरानुक्तिविकलान्\nग्रहग्रस्तानस्ताखिलदुरितनिस्तारसरणीन् ।\nनिलिम्पैर्निर्मुक्तानपि च निरयान्तर्निपततो\nनरानम्ब त्रातुं त्वमिह परमं भेषजमसि ॥ १५॥', transliteration: ''),
    LyricStanza(startTimeMs: 450000, devanagari: 'स्वभावस्वच्छानां सहजशिशिराणामयमपा-\nमपारस्ते मातर्जयति महिमा कोऽपि जगति ।\nमुदायं गायन्ति द्युतलमनवद्यद्युतिभृतः\nसमासाद्याद्यापि स्फुटपुलकसान्द्राः सगरजाः ॥ १६॥', transliteration: ''),
    LyricStanza(startTimeMs: 480000, devanagari: 'कृतक्षुद्रैनस्कानथ झटिति सन्तप्तमनसः\nसमुद्धर्तुं सन्ति त्रिभुवनतले तीर्थनिवहाः ।\nअपि प्रायश्चित्तप्रसरणपथातीतचरिता-\nन्नरानूरीकर्तुं त्वमिव जननि त्वं विजयसे ॥ १७॥', transliteration: ''),
    LyricStanza(startTimeMs: 510000, devanagari: 'निधानं धर्माणां किमपि च विधानं नवमुदां\nप्रधानं तीर्थानाममलपरिधानं त्रिजगतः ।\nसमाधानं बुद्धेरथ खलु तिरोधानमधियां\nश्रियामाधानं नः परिहरतु तापं तव वपुः ॥ १८॥', transliteration: ''),
    LyricStanza(startTimeMs: 540000, devanagari: 'पुरो धावं धावं द्रविणमदिराघूर्णितदृशां\nमहीपानां नानातरुणतरखेदस्य नियतम् ।\nममैवायं मन्तुः स्वहितशतहन्तुर्जडधियो\nवियोगस्ते मातर्यदिह करुणातः क्षणमपि ॥ १९॥', transliteration: ''),
    LyricStanza(startTimeMs: 570000, devanagari: 'मरुल्लीलालोलल्लहरिलुलिताम्भोजपटली-\nस्खलत्पांसुव्रातच्छुरणविसरत्कौङ्कुमरुचि ।\nसुरस्त्रीवक्षोजक्षरदगरुजम्बालजटिलं\nजलं ते जम्बालं मम जननजालं जरयतु ॥ २०॥', transliteration: ''),
    LyricStanza(startTimeMs: 600000, devanagari: 'समुत्पत्तिः पद्मारमणपदपद्मामलनखा-\nन्निवासः कन्दर्पप्रतिभटजटाजूटभवने ।\nअथाऽयं व्यासङ्गो हतपतितनिस्तारणविधौ\nन कस्मादुत्कर्षस्तव जननि जागर्तु जगति ॥ २१॥', transliteration: ''),
    LyricStanza(startTimeMs: 630000, devanagari: 'नगेभ्यो यान्तीनां कथय तटिनीनां कतमया\nपुराणां संहर्तुः सुरधुनि कपर्दोऽधिरुरुहे ।\nकया वा श्रीभर्तुः पदकमलमक्षालि सलिलै-\nस्तुलालेशो यस्यां तव जननि दीयेत कविभिः ॥ २२॥', transliteration: ''),
    LyricStanza(startTimeMs: 660000, devanagari: 'विधत्तां निःशङ्कं निरवधि समाधिं विधिरहो\nसुखं शेषे शेतां हरिरविरतं नृत्यतु हरः ।\nकृतं प्रायश्चित्तैरलमथ तपोदानयजनैः\nसवित्री कामानां यदि जगति जागर्ति जननी ॥ २३॥', transliteration: ''),
    LyricStanza(startTimeMs: 690000, devanagari: 'अनाथः स्नेहार्द्रां विगलितगतिः पुण्यगतिदां\nपतन् विश्वोद्धर्त्रीं गदविगलितः सिद्धभिषजम् ।\nसुधासिन्धुं तृष्णाकुलितहृदयो मातरमयं\nशिशुः सम्प्राप्तस्त्वामहमिह विदध्याः समुचितम् ॥ २४॥', transliteration: ''),
    LyricStanza(startTimeMs: 720000, devanagari: 'विलीनो वै वैवस्वतनगरकोलाहलभरो\nगता दूता दूरं क्वचिदपि परेतान् मृगयितुम् ।\nविमानानां व्रातो विदलयति वीथिर्दिविषदां\nकथा ते कल्याणी यदवधि महीमण्डलमगात् ॥ २५॥', transliteration: ''),
    LyricStanza(startTimeMs: 750000, devanagari: 'स्फुरत्कामक्रोधप्रबलतरसञ्जातजटिल-\nज्वरज्वालाजालज्वलितवपुषां नः प्रतिदिनम् ।\nहरन्तां सन्तापं कमपि मरुदुल्लासलहरि-\nच्छटाचञ्चत्पाथःकणसरणयो दिव्यसरितः ॥ २६॥', transliteration: ''),
    LyricStanza(startTimeMs: 780000, devanagari: 'इदं हि ब्रह्माण्डं सकलभुवनाभोगभवनं\nतरङ्गैर्यस्यान्तर्लुठति परितस्तिन्दुकमिव ।\nस एष श्रीकण्ठप्रविततजटाजूटजटिलो\nजलानां सङ्घातस्तव जननि तापं हरतु नः ॥ २७॥', transliteration: ''),
    LyricStanza(startTimeMs: 810000, devanagari: 'त्रपन्ते तीर्थानि त्वरितमिह यस्योद्धृतिविधौ\nकरं कर्णे कुर्वन्त्यपि किल कपालिप्रभृतयः ।\nइमं त्वं मामम्ब त्वमियमनुकम्पार्द्रहृदये\nपुनाना सर्वेषामघमथनदर्पं दलयसि ॥ २८॥', transliteration: ''),
    LyricStanza(startTimeMs: 840000, devanagari: 'श्वपाकानां व्रातैरमितविचिकित्साविचलितै-\nर्विमुक्तानामेकं किल सदनमेनःपरिषदाम् ।\nअहो मामुद्धर्तुं जननि घटयन्त्याः परिकरं\nतव श्लाघां कर्तुं कथमिव समर्थो नरपशुः ॥ २९॥', transliteration: ''),
    LyricStanza(startTimeMs: 870000, devanagari: 'न कोऽप्येतावन्तं खलु समयमारभ्य मिलितो\nयदुद्धारादाराद्भवति जगतो विस्मयभरः ।\nइतीमामीहां ते मनसि चिरकालं स्थितवती-\nमयं सम्प्राप्तोऽहं सफलयितुमम्ब प्रणय नः ॥ ३०॥', transliteration: ''),
    LyricStanza(startTimeMs: 900000, devanagari: 'श्ववृत्तिव्यासङ्गो नियतमथ मिथ्याप्रलपनं\nकुतर्केश्वभ्यासः सततपरपैशुन्यमननम् ।\nअपि श्रावं श्रावं मम तु पुनरेवं गुणगणा-\nनृते त्वत्को नाम क्षणमपि निरीक्षेत वदनम् ॥ ३१॥', transliteration: ''),
    LyricStanza(startTimeMs: 930000, devanagari: 'विशालाभ्यामाभ्यां किमिह नयनाभ्यां खलु फलं\nन याभ्यामालीढा परमरमणीया तव तनुः ।\nअयं हि न्यक्कारो जननि मनुजस्य श्रवणयो-\nर्ययोर्नान्तर्यातस्तव लहरिलीलाकलकलः ॥ ३२॥', transliteration: ''),
    LyricStanza(startTimeMs: 960000, devanagari: 'विमानैः स्वच्छन्दं सुरपुरमयन्ते सुकृतिनः\nपतन्ति द्राक् पापा जननि नरकान्तः परवशाः ।\nविभागोऽयं तस्मिन्नशुभमयमूर्तौ जनपदे\nन यत्र त्वं लीलादलितमनुजाशेषकलुषा ॥ ३३॥', transliteration: ''),
    LyricStanza(startTimeMs: 990000, devanagari: 'अपि घ्नन्तो विप्रानविरतमुशन्तो गुरुसतीः\nपिबन्तो मैरेयं पुनरपि हरन्तश्च कनकम् ।\nविहाय त्वय्यन्ते तनुमतनुदानाध्वरजुषा-\nमुपर्यम्ब क्रीडन्त्यखिलसुरसम्भावितपदाः ॥ ३४॥', transliteration: ''),
    LyricStanza(startTimeMs: 1020000, devanagari: 'अलभ्यं सौरभ्यं हरति सततं यः सुमनसां\nक्षणादेव प्राणानपि विरहशस्त्रक्षतहृदाम् ।\nत्वदीयानां लीलाचलितलहरीणां व्यतिकरात्\nपुनीते सोऽपि द्रागहह पवमानस्त्रिभुवनम् ॥ ३५॥', transliteration: ''),
    LyricStanza(startTimeMs: 1050000, devanagari: 'कियन्तः सन्त्येके नियतमिहलोकार्थघटकाः\nपरे पूतात्मानः कति च परलोकप्रणयिनः ।\nसुखं शेते मातस्तव खलु कृपातः पुनरयं\nजगन्नाथः शश्वत्त्वयि निहितलोकद्वयभरः ॥ ३६॥', transliteration: ''),
    LyricStanza(startTimeMs: 1080000, devanagari: 'भवत्या हि व्रात्याधमपतितपाखण्डपरिषत्\nपरित्राणस्नेहः श्लथयितुमशक्यः खलु यथा ।\nममाप्येवं प्रेमा दुरितनिवहेष्वम्ब जगति\nस्वभावोऽयं सर्वैरपि खलु यतो दुष्परिहरः ॥ ३७॥', transliteration: ''),
    LyricStanza(startTimeMs: 1110000, devanagari: 'प्रदोषान्तर्नृत्यत्पुरमथनलीलोद्धृतजटा-\nतटाभोगप्रेङ्खल्लहरिभुजसन्तानविधुतिः ।\nबिलक्रोडक्रीडज्जलडमरुटङ्कारसुभग-\nस्तिरोधत्तां तापं त्रिदशतटिनीताण्डवविधिः ॥ ३८॥', transliteration: ''),
    LyricStanza(startTimeMs: 1140000, devanagari: 'सदैव त्वय्येवार्पितकुशलचिन्ताभरमिमं\nयदि त्वं मामम्ब त्यजसि समयेऽस्मिन्सुविषमे ।\nतदा विश्वासोऽयं त्रिभुवनतलादस्तमयते\nनिराधारा चेयं भवति खलु निर्व्याजकरुणा ॥ ३९॥', transliteration: ''),
    LyricStanza(startTimeMs: 1170000, devanagari: 'कपर्दादुल्लस्य प्रणयमिलदर्धाङ्गयुवतेः\nपुरारेः प्रेङ्खन्त्यो मृदुलतरसीमन्तसरणौ ।\nभवान्या सापत्न्यस्फुरितनयनं कोमलरुचा\nकरेणाक्षिप्तास्ते जननि विजयन्तां लहरयः ॥ ४०॥', transliteration: ''),
    LyricStanza(startTimeMs: 1200000, devanagari: 'प्रपद्यन्ते लोकाः कति न भवतीमत्रभवती-\nमुपाधिस्तत्रायं स्फुरति यदभीष्टं वितरसि ।\nशपे तुभ्यं मातर्मम तु पुनरात्मा सुरधुनि\nस्वभावादेव त्वय्यमितमनुरागं विधृतवान् ॥ ४१॥', transliteration: ''),
    LyricStanza(startTimeMs: 1230000, devanagari: 'ललाटे या लोकैरिह खलु सलीलं तिलकिता\nतमो हन्तुं धत्ते तरुणतरमार्तण्डतुलनाम् ।\nविलुम्पन्ती सद्यो विधिलिखितदुर्वर्णसरणिं\nत्वदीया सा मृत्स्ना मम हरतु कृत्स्नामपि शुचम् ॥ ४२॥', transliteration: ''),
    LyricStanza(startTimeMs: 1260000, devanagari: 'नरान् मूढांस्तत्तज्जनपदसमासक्तमनसो\nहसन्तः सोल्लासं विकचकुसुमव्रातमिषतः ।\nपुनानाः सौरभ्यैः सततमलिनो नित्यमलिनान्\nसखायो नः सन्तु त्रिदशतटिनीतीरतरवः ॥ ४३॥', transliteration: ''),
    LyricStanza(startTimeMs: 1290000, devanagari: 'यजन्त्येके देवान् कठिनतरसेवांस्तदपरे\nवितानव्यासक्ता यमनियमरक्ताः कतिपये ।\nअहं तु त्वन्नामस्मरणकृतकामस्त्रिपथगे\nजगज्जालं जाने जननि तृणजालेन सदृशम् ॥ ४४॥', transliteration: ''),
    LyricStanza(startTimeMs: 1320000, devanagari: 'अविश्रान्तं जन्मावधि सुकृतजन्मार्जनकृतां\nसतां श्रेयः कर्तुं कति न कृतिनः सन्ति विबुधाः ।\nनिरस्तालम्बानामकृतसुकृतानां तु भवतीं\nविनाऽमुष्मिंल्लोके न परमवलोके हितकरम् ॥ ४५॥', transliteration: ''),
    LyricStanza(startTimeMs: 1350000, devanagari: 'पयः पीत्वा मातस्तव सपदि यातः सहचरै-\nर्विमूढैः संरन्तुं क्वचिदपि न विश्रान्तिमगमम् ।\nइदानीमुत्सङ्गे मृदुपवनसञ्चारशिशिरे\nचिरादुन्निद्रं मां सदयहृदये शायय चिरम् ॥ ४६॥', transliteration: ''),
    LyricStanza(startTimeMs: 1380000, devanagari: 'बधान द्रागेव द्रढिमरमणीयं परिकरं\nकिरीटे बालेन्दुं नियमय पुनः पन्नगगणैः ।\nन कुर्यास्त्वं हेलामितरजनसाधारणतया\nजगन्नाथस्यायं सुरधुनि समुद्धारसमयः ॥ ४७॥', transliteration: ''),
    LyricStanza(startTimeMs: 1410000, devanagari: 'शरच्चन्द्रश्वेतां शशिशकलश्वेतालमुकुटां\nकरैः कुम्भाम्भोजे वरभयनिरासौ च दधतीम् ।\nसुधाधाराकाराभरणवसनां शुभ्रमकर-\nस्थितां त्वां ये ध्यायन्त्युदयति न तेषां परिभवः ॥ ४८॥', transliteration: ''),
